window.POEM_DB=window.POEM_DB||{};POEM_DB["ming_004"]={"n":"程敏政","dyn":"明","poems":[{"t":"四月五日微雨免朝与李太史世贤步出皇城门喜而有作","f":"七言律诗","c":["轻阴小雨夜连晨，中使传呼散紫宸。","天气薰蒸疑作暑，风光回转欲留春。","班分辇道花迎佩，仗出宫墙柳映人。","独喜联镳归去早，六街消尽马蹄尘。"]},{"t":"挽张世琏舍人","f":"七言律诗","c":["去年君家会邻曲，芙蕖花红池水绿。","今年君死藤束棺，芙渠花落池水寒。","明年花开对新主，太息人生几何许。","楚些招君君不来，斜日虚堂泪如雨。"]},{"t":"闻南都新开池馆之胜漫摘坦侄二属对成诗二章 其一","f":"七言律诗","c":["一川新绿板桥通，更起盆亭著镜中。","杜曲儿孙供酒盏，谢家兄弟走诗筒。","草鞋半湿莎庭露，蒲扇轻回竹埭风。","胜日无因陪胜赏，只凭春梦到江东。"]},{"t":"闻南都新开池馆之胜漫摘坦侄二属对成诗二章 其二","f":"七言律诗","c":["别业新开水竹居，游尘全不到庭除。","楝花台榭闻幽鸟，荻草盆池种小鱼。","翁醉不劳方竹引，客吟多借古藤书。","何时罢直金华省，日日江头奉板舆。"]},{"t":"卧病七旬方起试笔作字适世贤有诗见慰依韵奉酬","f":"七言律诗","c":["独卧空房思有馀，茂陵憔悴旧相如。","病来自觉逢迎倦，客至从嗔礼法疏。","风约黄尘凝砚沼，雨催青草上阶除。","读君诗罢还成句，枣笔藤笺试手初。"]},{"t":"朔州行送王汝璧太守述职西还","f":"古风","c":["朔州城头塞云结，朔州城下沙如雪。","赫连古戍白草枯，一路角声吹不歇。","居民半是防秋兵，十里五里屯军营。","偏师夜坐烽火息，飞挽小儿歌太平。","王郎家世本灵武，明目张髯气如虎。","羽林骄将不敢欺，碛里人耕好田土。","穷州十年多苦辛，奉檄东来觐紫宸。","长官知名圣君喜，边吏有才能几人。","遥遥朔州城，劝子一卮酒，马蹄明朝向山后。","女墙孤月重相思，定倚危楼望南斗。"]},{"t":"题安城彭学士山水图","f":"七言古诗","c":["何人结屋青山里，终日开窗见山喜。","近峰错落走檐牙，远岫蜿蜒插天嘴。","澄江一道山前过，短棹平分浪痕破。","船头水气绿侵衣，载酒高人面山坐。","石泉下冲沙渚浑，桑榆接地成深村。","柴扉欲扣不可到，或有细路通云根。","竹鹤老人名画手，半幅生绡大于斗。","水分山断意无穷，目送飞鸿度江口。","安城先生尘虑脱，南望乡人楚天阔。","高堂永日对山歌，肃肃凉风起蘋末。"]},{"t":"傅家面食行","f":"七言古诗","c":["傅家面食天下工，制法来自东山东。","美如甘酥色瑩雪，一块入口心神融。","旁人未许窥炙釜，素手每自开蒸笼。","侯鲭尚食固多品，此味或恐无专功。","并洛人家亦精办，敛手未敢来争雄。","主人官属司徒公，好客往往尊罍同。","我虽北人本南产，饥肠不受饼饵充。","惟到君家不须劝，大嚼颇惧冰盘空。","膝前新生两小童，大者已解呼乃翁。","愿君饤饾常加丰，待我醉携双袖中。"]},{"t":"涿州道中录野人语","f":"五言古诗","c":["我行范阳道，水次遇老叟。","时当孟冬尽，破褐露两肘。","邂逅一咨诹，向我再三剖。","哭言水为沴，天意苦难究。","今年六月间，一日夜当丑。","山水从西来，声若万雷吼。","水头高十丈，没我堤上柳。","手指官路旁，瓦砾半榛莽。","昔有十数家，青帘市村酒。","人物与屋庐，平明荡无有。","水面沈沈来，忽见铁枢牖。","数日得传闻，水蚀紫荆口。","老稚随波流，积尸比山阜。","远近皆汤汤，昏垫弗可救。","如此数月馀，乃可辨疆亩。","下田尽沮洳，高田剩稂莠。","农家一岁计，不复望升斗。","官府当秋来，催租不容后。","嗟嗟下小民，命在令与守。","更有观风使，仰若大父母。","见此如不闻，恐或坐其咎。","我民千馀人，血首当道叩。","始获免三分，有若释重负。","奈何急馀徵，日日事鞭殴。","夫征又百出，一一尽豪取。","悲哉一村中，窜者已八九。","老夫家无妻，一儿并一妇。","两孙方提携，尽可慰衰朽。","岂期天不吊，一旦遂穷疚。","一儿水中没，一妇嫁邻某。","两孙鬻他人，偿官尚难勾。","老身自执役，有气孰敢抖。","反羡死者安，苦恨生多寿。","诏书开赈济，奉者有贤否。","终为吏所欺，此食亦难就。","与其馁填壑，不若举身走。","一饱死即休，宁复念丘首。","呼天一何高，呼地一何厚。","我闻老叟言，垂涕者良久。","恭惟天子圣，化泽被寰囿。","声色弗自御，游畋敢谁诱。","稼穑深所知，真如古明后。","庶徵岂不谙，一变故非偶。","无乃诸皋夔，此责当敬受。","谁谓斯民痛，不可事焫灸。","我亦食人禄，深惭结朱绶。","岂无致泽心，无地可藉手。","立马野踟蹰，悲风动林薮。"]},{"t":"过石门桥铺","f":"七言律诗","c":["道上人稀日出迟，弊裘风起不胜吹。","马行冰地如临镜，鸦啄霜田似阅棋。","野寺饭时钟隐隐，谁家耕处冢累累。","晨门一去无消息，伫立河梁有所思。"]},{"t":"严州道中情思颇适","f":"七言律诗","c":["山远沙平水似烟，篷窗赢得枕书眠。","暖风一日初黄柳，好雨连宵剩绿田。","傍岸凫鹥如送客，随家鸡犬不惊船。","相看便有江湖恋，耕凿娱亲在几年。"]},{"t":"癸巳日长至与世贤太史陪祀山陵往反得律诗十首 其三 度东山岭","f":"七言律诗","c":["石桥驻马问田翁，一坞深深隔树东。","帝子阁前沙似粟，野神祠下路如弓。","疏松古涧风微动，细草阴厓雪半融。","回望红尘才数里，不知身在乱山中。"]},{"t":"宿资胜寺与王文玙进士夜谈","f":"五言律诗","c":["载酒朝相过，论心夜未中。","卧残禅室冷，谈彻讲堂空。","香篆销轻缕，灯花落小红。","好怀摅不尽，钟起院墙东。"]},{"t":"古城驿遇南京参赞机务兵部尚书薛公诗以送之并谢惠粲 其一","f":"七言律诗","c":["楼船三月下江东，猎猎旌旗暖受风。","林壑有情归谢傅，庙堂何意起裴公。","貔貅作队迎新诏，龙虎分疆拥旧宫。","幕府勋劳应日盛，军储曾赞几元戎。"]},{"t":"古城驿遇南京参赞机务兵部尚书薛公诗以送之并谢惠粲 其二","f":"七言古诗","c":["幕府勋劳应日盛，军储曾赞几元戎。"]},{"t":"古城驿遇南京参赞机务兵部尚书薛公诗以送之并谢惠粲 其二","f":"七言律诗","c":["贱子乘春上石渠，喜逢先达舣舟馀。","当床幸展梁生拜，乞米宁工鲁郡书。","岸雨绿苗方净好，水风黄柳共虚徐。","相逢无限通家意，请向诸郎报起居。"]},{"t":"暮雨夜泊","f":"七言古诗","c":["黑风摧山雨如注，未到下邳无泊处。","暗中杂遝人语声，且逐淮南漕舟住。","淮南漕舟三百强，粉宇舵楼成堵墙。","轮更转箭镇相续，似觉人人嫌夜长。","灭烛悠然倚床坐，远村曙鸡闻一个。","前途早有役夫来，岸东相呼岸西和。"]},{"t":"徐州饭管洪尹珍主事家有怀亡弟","f":"古风","c":["去年过彭城，朔风萧萧征马鸣。","今年过彭城，东风渺渺扁舟行。","渐觉此身为客惯，才见花飞又花绽。","南去北来曾几时，随阳却似云中雁。","九里峰前春草芳，百步矶头春水长。","偶然一饭剪银烛，行河使者尚书郎。","逍遥堂空谁作主，感慨当时对床语。","归来展转不成眠，独倚篷窗听风雨。"]},{"t":"夹沟道中","f":"七言律诗","c":["猎猎风帆水满塘，明明春岸柳成行。","连村犬不惊薪女，傍渚鸥全识棹郎。","官闸聚舟多漕运，野田空屋半逃亡。","推篷不见青山色，始觉风光是异乡。"]},{"t":"题蔡挥使所藏林良双鹊","f":"楚辞体","c":["老木长梢半空起，影落君家素屏里。","枝间双鹊不飞去，似向高堂报君喜。","凉风晓入庭户清，主人坐对宛有情。","眼前岂独惜珍羽，耳畔忽疑闻好声。","亦有娟娟白头鸟，相顾裴裒若相保。","广东画史深可人，生态无穷意难了。","主人堂堂真壮夫，喜受文士相追呼。","征蛮不带岭南物，衣衾之外惟此图。","堂下有儿堂上母，客至矜图饮醇酒。","呀然一笑共平生，崔白边鸾竟何有。","鹊兮鹊兮不可求，愿君身比张梁州。","不须椎石取金印，看尔生封忠孝侯。"]},{"t":"古箭渡","f":"七言律诗","c":["古箭渡头春水急，古箭铺下春泥湿。","风吹一道雨微收，黑压四山云未入。","邮亭饭罢闻竹鸡，肩舆扶过苍崖西。","行人道侧乱相指，雨阵复来云脚齐。"]},{"t":"黄鹤山樵为沈兰坡作小景兰坡孙启南求题","f":"五言古诗","c":["在昔兰坡翁，结屋断尘鞅。","俯听溪阁邃，仰眺岩扉敞。","天机久已熟，真趣可谁赏。","颇闻黄鹤山，樵斧隔林响。","居然驾小舟，来趁夜潮长。","相对喜忘言，欲去愁孤往。","挥毫意不极，缣素大于掌。","高松发天籁，哀壑生夏爽。","抚景尚如昨，斯人已黄壤。","逆旅开画奁，斜阳落书幌。","高风邈难扳，题诗寄遐想。"]},{"t":"题蒙泉岳先生葡萄","f":"七言古诗","c":["刘郎未撤轮台戍，使者年年向西去。","宛国传将马乳来，汉宫始识葡萄树。","茂陵石马秋风寒，玄香冷落黄金盘。","后来尚食不到此，当时价抵千琅玕。","镇夷城头初罢鼓，谪仙挥毫气如虎。","一番风味眼底生，万斛骊珠手中吐。","铁面长髯谁比伦，慷慨便作凉州春。","兔起鹘落总天趣，日观之徒空逼真。","愿子珍藏无草草，谪仙已逐秋花老。","临池不觉三叹嗟，前辈风流到今少。"]},{"t":"周德章驸马府赏海棠","f":"古风","c":["冥冥花雾拥回廊，冉冉猩红隔画墙。","按谱更谁争有韵，失评空自说无香。","莫烧银烛惊春梦，好障丹纱护晓妆。","仙种北来初识面，临风?醉九霞觞。"]},{"t":"游王司言国宾郊园","f":"七言律诗","c":["风逗黄云涨麦川，井分新绿绕瓜田。","童穿墙缺携壶到，客趁堂虚借榻眠。","乐憩午阴怜困马，预传秋律爱鸣蝉。","城楼咫尺忘归晚，多少诗情落照边。"]},{"t":"功臣庙下作","f":"七言古诗","c":["鸡鸣山侧英雄坊，朱门半掩青松长。","功臣庙食自洪武，下车进谒开中堂。","元勋佐命推六王，俨然并坐徐与常。","左李右邓沐最少，霜髯独见东瓯汤。","秉圭服冕垂衣裳，异姓联翩如雁行。","公侯十六分两傍，金貂玉带相辉光。","瓣香一炷三叹息，却走苔阶观画廊。","朅从真主兴濠梁，材杰奋起骖龙翔。","长江飞渡入建康，血战往往皆鹰扬。","当时陈虏号最强，屡仗左纛乘飞艎。","诸军一衄番水阳，不日降旗来武昌。","神威自此若破竹，僣窃次第归天亡。","按图未取东海方，下令先缚盐城张。","远清闽广服蛮徼，继下滇蜀连氐羌。","东南略遣疮痏息，健儿不敢窥牧场。","临江发兵二十万，如以虓虎驱群羊。","沛然时雨仰星旅，抚绥六幕宁八荒。","乾坤一统成帝乡，九州入贡纷梯航。","文孙继承万亿载，诸将之功何可忘。","礼官四时奉蒸尝，令典与国同无疆。","锡封赐履遥相望，山河带砺分天章。","至今一二传世芳，馀者中微殊可伤。","安得司勋彻圣听，两汉故实芸编香。","摩挲丹青落日黄，一时际遇思明良。","陆机有颂愧莫续，风云飒爽天茫茫。"]},{"t":"发昌平","f":"七言律诗","c":["出郭先登乱石冈，冻云垂野日苍凉。","田麰冬尽犹悭雪，陵树年深总奈霜。","寝殿四围山色近，御桥横截涧声长。","斋居依旧西风下，鹓鹭相联第几行。"]},{"t":"钱舜举清晖堂所写戏婴图为临淮顾谦赋","f":"七言古诗","c":["海榴花开白日长，绣屏十二云锦张。","沉沉午漏下初刻，搔头不整慵来妆。","一姬南面金缕裳，两姬夹侍相颉颃。","颀然围坐看儿戏，斑管雕弧堆象床。","三姬鼎足如雁行，玉阶随步鸣双珰。","以口抚婴爱入骨，笑语彷佛闻昭阳。","一姬下坐收锦裆，洗儿自与浇兰汤。","娟娟秀若化生子，银盆水煖芙蓉香。","一姬转盻殊未央，拭巾在手明吴霜。","小鬟两两意閒适，纨扇不动薰风凉。","苕溪画史推钱郎，柔思独步丹青场。","摩挲旧本岂易得，流传远自清晖堂。","才人不说顾长康，鉴赏欲博千金强。","《螽斯》、《麟趾》尚可作，为君击节歌周王。"]},{"t":"四月二十八日起屡赐鲜笋青梅鲥鱼枇杷杨梅雪梨鲜藕","f":"七言律诗","c":["都城三伏暑方炎，天上分鲜我亦沾。","缄发紫泥留榼筥，香生青箬带冰盐。","南舟远贡来何数，北客初尝味更添。","为感岁时翻赐帖，不知残日下疏帘。"]},{"t":"题陆廉伯庶子所藏墨梅","f":"七言古诗","c":["宋人写梅工染地，染出疏花得花意。","寒枝点缀纵复横，宛在江村立烟际。","元人写梅铁作圜，千玉万玉相联拳。","天机浅深各有态，三昧定属何人传。","忽拭此图真宋手，入眼丹青未能有。","凉风未觉生衣襟，古月犹疑照窗牖。","断缣残墨惊海棠，当时价抵千金强。","几人豪夺几悬购，完璧乃归君子堂。","多君家在毗陵住，高洁平生似梅树。","秀餐亭上岁寒盟，时约花神共来去。","我今归卧新安山，暗香正绕清溪湾。","北河冰坚未成往，春梦夜落松筠间。","补之不作林逋老，红绿纷纷竞妍好。","愧无佳句慰幽芳，三复莓苔被花恼。"]},{"t":"任月山五王醉归图","f":"七言古诗","c":["何处离宫春宴罢，五马如龙自天下。","锦鞯蹀躞摇东风，不用金吾候随驾。","缓策乌骓衣柘黄，颜赪不奈流霞浆。","手戮淫昏作天子，三郎旧是临淄王。","大醉不醒危欲堕，双拥官奴却鞍座。","宋王开国长且贤，谁敢尊前督觞过。","申王伏马思吐茵，丝缰侧控劳奚人。","可怜身与马斗力，天街一饷流香尘。","岐王薛王年尚少，酒力禁持美风调。","前趋后拥奉诸兄，临风彷佛闻呼召。","夜漏归时严禁垣，花萼楼中金炬繁。","大衾长枕已预设，帝家手足称开元。","我闻逸乐关成败，狗马沉酣示明戒。","二公作诰五子歌，此意当时可谁解。","仙李枝空人不还，王孙一日开真颜。","鸰原终古存风教，珍重丹青任月山。"]},{"t":"春社谣","f":"七言古诗","c":["我家社公耕凿主，求晴得晴雨得雨。","今春作社神更欢，值我一年新病愈。","墙下小桃红满枝，塘东弱柳垂金丝。","社饭炊香出茅屋，腊酒一倾连数卮。","土鼓逄逄过林际，醉插山花共神戏。","隔邻鸡犬喜欲狂，接席儿童相笑詈。","满爇炉香焚纸钱，大家再拜祈丰年。","放臣敢道金马客，明日扶犁同下田。"]},{"t":"访进士何斯复于歙北黄荆渡不值时斯复方以养亲告归","f":"七言律诗","c":["问路寻君径出城，过桥自得绕溪行。","小翻翠柳东风软，返射青山夕照明。","为就江鱼长供母，暂容沙鸟一寻盟。","前村种药归应晚，欲话心期恐未成。"]},{"t":"沈启南画障为张通守题","f":"七言古诗","c":["石田老人非画师，胸中丘壑天所私。","挥毫便觉真趣发，意到岂借丹青施。","通守张君画成癖，半幅生绡比全璧。","望中谓作云门山，游人拟办登山屐。","峰回路转溪流长，谁向石林开草堂。","风檐举手欲相问，扁舟载客来何方。","老人画出今人上，乡评未数黄公望。","一石俄成斧劈痕，不类群羊更奇壮。","石田隐处轻辋川，秀句却似王维传。","吴歌一日变楚语，幽芳懒斗春花妍。","我从胥门八回过，古寺长邀听经坐。","老人不惜与画山，击节诗成几人和。","尚方有诏徵遗才，白发苍颜能一来。","还君此图意无限，停云正绕姑苏台。"]},{"t":"题罢猎图","f":"七言古诗","c":["沙碛风高树鸣叶，马放平原人罢猎。","解装散出青草间，两两胡姬映桃颊。","酪浆满注金叵罗，侑饮似唱阴山歌。","雪鹰离绦犬噬肉，穹庐到处皆行窝。","大旆扬扬出烟表，不觉残阳过林杪。","健儿自许力未疲，翻身欲射云中鸟。","打围之乐乐未央，挽弓握矢心茫茫。","岭阴直接贺兰道，马上终老单于乡。","当今圣人制诸夏，八方无尘羽书寡。","但愿胡雏似画中，莫近三边古城下。"]},{"t":"题田家娶妇图","f":"七言古诗","c":["径草如烟柳如幕，日上茅檐鼓声作。","田翁遣女不出村，东舍西邻隔墟落。","新妇驾牛儿跨驴，家人后拥翁前驱。","儿家举酒拦道劝，舅甥几世同桑榆。","耳边阿㜷私属父，肩上娇婴肯离祖。","欢声一路到柴关，野伶山歌《柘枝》舞。","两门彷佛朱与陈，乡仪简古民风淳。","华筵肆设竞珠翠，想见纷纷京洛尘。","妇馌男耕罢征戍，安得移家个中住。","长因击节颂年丰，不作催租打门句。"]},{"t":"题戎王出猎图","f":"七言古诗","c":["黑山之北青海头，草木摇落风飕飕。","平原一望渺无际，猎骑四踏黄云秋。","戎王小年面如玉，彷佛当时李存勖。","锦袍白马弯雕弧，一箭真应倒苍鹿。","苍鹿却走青羊奔，沙碛霜中馀血痕。","相随两两奉驱策，毡裘辫发皆羌浑。","一犬腾身逐惊兔，后骑鞲鹰笑相顾。","大家贾勇各忘疲，倒载争多不知暮。","健儿独往先着鞭，自期百发无虚弦。","何物霜蹄忽星迸，脱手落地仍欣然。","几辆毡车驻山口，应待归来劝胡酒。","共燖熊掌炙驼峰，《敕勒歌》长出林薮。","歌长昼短乐未央，皂旗闪烁天苍凉。","明朝移帐定何所，择地还开新猎场。","方今圣人居大宝，烽燧无烟罢天讨。","胡雏长作画中看，莫近飞狐塞垣道。"]},{"t":"吊刘竹东后赋此","f":"七言律诗","c":["春泥半拥蓬扉开，萧萧翠竹如新栽。","百年老友不复见，旧雨故人空一来。","南郢歌工罢瑶瑟，西湖诗板生青苔。","感怀欲去重回首，黄柳白鸦增暮哀。"]},{"t":"拱北楼","f":"七言古诗","c":["危楼突兀中天起，雄峙高城压诸垒。","登楼北望空濛间，正距皇都三百里。","直沽东去当海门，九河下泻鲸涛奔。","一道科徵比州县，十连虎豹分营屯。","天子端居不忘武，敕遣提刑此开府。","眼中壮观忽岿然，缓带时来阅干橹。","四方玉帛趋神京，千车万舶无留行。","题品休歌太行路，丽谯却数天津城。","忆昔文皇曾驻跸，父老相传至今日。","宪臣初下新条章，宿将谁谙旧军律。","城头大旆翻晴红，城边细柳摇薰风。","我来徙倚不能去，宸居宛在红云中。","画角悠扬鼓声壮，雉堞嵯峨日初上。","掀髯听讲阴符篇，谁道儒生不堪将。","槛外滔滔河水流，酒酣击节歌新楼。","盛年相与赤心在，范公敢谢苍生忧。"]},{"t":"琼花","f":"七言绝句","c":["贪看江都第一春，龙舟元不为东巡。","閒花亦自能倾国，何况当时解语人。"]},{"t":"驱车上东门行","f":"五言绝句","c":["雉堞连云起，秦城属汉家。","更无丞相犬，犹有故侯瓜。"]},{"t":"迎驾次韵亨父","f":"七言律诗","c":["一声清跸下郊坛，阊阖齐开敞玉阑。","十二銮铃陈路马，三千犀甲拥材官。","垆烟散綵凝香雾，扇影屯云护浅寒。","最是词臣偏近辇，龙颜春色有馀欢。"]},{"t":"元日早朝","f":"七言律诗","c":["宫鸦集曙彩鞭挥，剑佩森森拱太微。","日晃御床明绣衮，云回銮辂见青旂。","鸿胪立仗传三呼，马监随班控六飞。","喜值芳年叨侍从，起居长许近皇闱。"]},{"t":"门有车马客行","f":"古风","c":["席为门，茅盖屋，穷巷萧然媚幽独。","里中却有张氏翁，能识陈郎非碌碌。","有女不嫁王侯族，愿与陈郎侍栉沐。","陈郎居处非楼台，席门终日凌风开。","巍冠时有长者来，车轮马足飞黄埃。","蛟螭自古困泥滓，男儿岂久居蒿莱。","伟哉陈郎被戎服，从赤龙，逐秦鹿，宰制天下如宰肉。","分茅既受五侯封，秉钧更享千钟禄。","张氏女，鬓未苍，鱼轩命服何煌煌。","始知乃翁眼力长，何事儿孙废绳武，不知门外有韦郎。"]},{"t":"君马黄","f":"古风","c":["周穆王，挟造父。","乘飞黄，谒王母。","晓驰黄泽西，夜宿瑶池浒。","一曲蟠桃宴未终，玉帛纷纷向徐土。","回首西京路脩阻，纵有飞黄竟何补。","君不见汉高侧室儿，能却千里马。","拱手垂衣治天下，南粤称臣无叛者。"]},{"t":"墙上难为趋行","f":"五言绝句","c":["君子如处子，一生当守身。","愿学段干木，不学宋东邻。"]},{"t":"将进酒","f":"古风","c":["安汉公，将进酒，蝮蛇蜿蜒持在手。","未央宫中日将酉，一杯才入君王口。","六宫便作招魂啼，太后朝来号王母。","君不见申氏子，伶其身，内庭侍宴将及晨。","坐中起为寿，刃此手足亲。","申氏子，长眉颦，夺取一吸如饮醇。","肝脑不惜涂宫裀，吁嗟此意宁求伸。","不忍他人害兄弟，何况自己忘君臣。","安汉公，非得计，四海孤身葬无地。","早知今日反羞伶，何似当初莫称帝。"]},{"t":"铜雀妓","f":"古风","c":["魏公好色不知足，爱子已为张绣戮。","归来不悔旧时差，临河更把高台筑。","台上美人如万花，日日歌管声諠哗。","老瞒自欲比西伯，内则何似周王家。","当时美人浪自许，各逞新妆奉新主。","岂徒媚惑令主昏，冶容诲淫吾不与。","君不见邺中长想二乔来，有心不到黄公女。"]},{"t":"辟廱","f":"古风","c":["有严辟廱，四方之则。","孰其师之，一人孔硕。","眷此硕人，明德是崇。","穆其家风，自清惠公。","侍禁有声，出教国子。","横金服绯，再命伊始。","戟门夜启，舍菜于庭。","硕人顾瞻，是仪是刑。","朝鼓镗镗，硕人升坐。","诸生执经，或右或左。","相帝之治，爰藉群才。","迟此硕人，乐哉斯培。","材成孔多，功亦云懋。","耆俊之求，入副元后。","允兹明良，庶事攸康。","蔚有耿光，吾道之昌。"]},{"t":"巫山高","f":"古风","c":["十二峰头云似絮，十二峰下翻盆雨。","朝朝暮暮雨复晴，不知谁是阴晴主。","中有美人高髻鬟，神宫杳杳居深山。","人间有路不可往，云屏雾障愁跻攀。","怀王夜宿无人共，忽有山灵入幽梦。","醒来不见意中人，但觉阳台曙光动。","侍臣宋玉多才名，高唐一赋深有情。","自言亲到巫山里，美人再会如平生。","云雨当年只如此，襄王却是无名子。","后人不解真是非，误把遗迹著诗史。","巫山高，高嶙峋，楚宫花木今几春。","何时倚棹危峰下，一吊襄王父与臣。"]},{"t":"明妃曲","f":"七言古诗","c":["明妃本是巫山女，貌美如花解人语。","家门正对楚王台，惯听乡人说云雨。","一朝被选入汉宫，几年不识天子容。","宫车日日向何所，鱼钥只把长门封。","象床不寐心如捣，自惜红颜暗中老。","裴回顾影泪双垂，生死不如台下草。","胡王欲得汉家姬，六宫尽蹙双蛾眉。","孤怀不觉心语口，犹胜永巷常凄其。","欣然独上毡车里，胡王得之惊且喜。","短箫吹出霸陵桥，两两雎鸠水中起。","古城北去多战场，黄沙白草春无光。","多情自得虏庭乐，回首汉月空茫茫。","打围夜向阴山宿，更为胡王理丝竹。","汉家莫悔误和戎，琵琶不是思归曲。"]},{"t":"结袜子 其一","f":"古风","c":["有崇不道干天诛，西伯杖钺登戎车。","夜发渭水滨，晓至岐山隅。","朱丝履结忽自解，玉帐彳亍难为趋。","左顾颠适右闳散，冠剑济济非庸奴。","低头自结双带子，大圣自与常人殊。","呜呼大圣自与常人殊，溺冠骑项将何如。"]},{"t":"结袜子 其二","f":"古风","c":["梁王未赴宣武军，崇勋殿上酬元勋。","君臣面庆若鱼水，心腹戈矛人不闻。","天容惨淡愁风云，舄带忽解双龙纹。","特敕梁王手亲结，左右不敢生纷纭。","老奸长跪黼座下，浃背汗流如救焚。","呜呼天子贱役尔当结，砀山贼徒何足云。"]},{"t":"双瑞","f":"古风","c":["义兴之郊，有山隆隆。","孰窆其亲，有孝徐公。","有庐萧萧，倚山之麓。","徐公是居，哀慕孔笃。","爰有鸠二，来巢于梁。","其色缟缟，如君子裳。","雁雁于飞，日泳于渚。","濯濯其仪，扰而不去。","观者动色，异口同词。","有瑞徐公，维天锡之。","一锡不已，乃至于再。","发彼庆源，如水斯溉。","济济徐公，改服来朝。","贰命秩宗，维庆之昭。","允显其身，亦显其子。","奕世光荣，维庆之似。","维孝锡类，庆与之俱。","孰瑞之诬，而大其闾。","庆也无涯，勖哉令德。","匪瑞之夸，繄孝之式。"]},{"t":"雪崖操二章","f":"楚辞体","c":["维雪皓皓，言积其崖。","匪伊梅兮，孰鬯予怀。","乃赓载歌，其音孔嘉。","岁寒有盟，愿与之偕。","维崖嵚嵚，言冱其雪。","匪伊梅兮，孰□岩穴。","载传之图，其色孔洁。","有盟岁寒，我心则说。"]},{"t":"思亲堂","f":"楚辞体","c":["有堂渠渠，有客佖佖。","言思其亲，日甚一日。","堂上有山，堂下有江。","伊亲之思，江山靡长。","赫赫宫保，维客之季。","煌煌命书，屡贲于隧。","客拜稽首，家庆孔延。","维菽与水，下不及泉。","乃作斯堂，奉妣暨考。","若著若存，于以终老。","繄罔极兮，孰逃亲仁。","越终慕兮，孰非子身。","客哉孝思，亦既耄矣。","德既邵矣，式克肖矣。","孝思维则，世徵于堂。","爰锡厥类，斯堂之光。"]},{"t":"寿鞠","f":"古风","c":["有寿者鞠，其色孔黄。","月日维九，荐此令芳。","有寿者鞠，其味孔甘。","和以醇酒，礼庭燕酣。","诞是花辰，维泌焦父。","异世同生，曾大二祖。","维泌焦父，子为从臣。","有来恩纶，及是花辰。","永言礼庭，鞠本坚好。","载植载培，对尔寿考。","永言礼庭，鞠蘤滋蕃。","积庆开先，宜尔孙玄。"]},{"t":"芝颂","f":"楚辞体","c":["有翼者丘，在国之隅。","有屹者碑，在墓之衢。","孰藏于斯，山回川抱。","曰定兴王，维国元老。","繄定兴王，维国虎臣。","不世之功，视彼交人。","维交有州，故中国地。","孰遣弗庭，而自为异。","王往征之，如鹰之扬。","殄贼于荒，脱人于汤。","还定招来，乃郡乃邑。","告功庙社，礼绝班级。","功既往矣，而弗及详。","家乘无徵，闻者孔伤。","济济嗣公，今天子傅。","爰访爰蒐，得上功簿。","如获拱璧，如还大弓。","奉告于祠，天相予衷。","乃属钜公，爰辑爰次。","大书特书，神畀予志。","乃刻贞珉，金薤青瑶。","远映宸奎，上逼璇霄。","松柏丸丸，奰?矗矗。","蛟螭蜿蜿，后土骇肃。","碑既树矣，忽炳其灵。","有芝来生，一本九茎。","数协阳爻，状若云朵。","孰幻之根，孰名之蓏。","其色正黄，毓秀中央。","其本紫兮，载扬其芳。","守者走告，观者如堵。","谓此奇祥，匪今斯古。","维王之功，愈远而明。","维公之孝，弥久而贞。","芝生于房，于汉中叶。","祝国之釐，明明载牒。","芝见于庭，有晋世臣。","兆家之昌，孙子振振。","维王之功，震于南土。","与国咸休，盟在册府。","维王之后，世显中朝。","如石如玄，横玉珥貂。","享祠巍巍，王在中寝。","公子是承，有苾其饮。","俎豆煌煌，王降于堂。","公孙是将，维食之香。","天显相王，河间之胄。","维本之固，而末之茂。","天显相王，三冈之阡。","剑舄之传，维吉之延。","史臣作诗，以颂厥美。","一章之荣，百世之纪。"]},{"t":"野哭","f":"楚辞体","c":["野哭者谁，子伊氏维。","顾弗安于，寝言思其。","父言升其，堂言抚其。","床音容无，方乃筑室。","于场匪言，斯扬维以。","永伤维草，萋萋维木。","繄繄于今，三年而身。","之痗兮而，志弗馁兮。","日往于田，号泣于天。","有鸟有?，亦子是怜。","维孝思则，然孰吴之。","区而有斯，士孰顾之。","宗而有斯，子维士子。","兮家之纪，兮里之砥。","兮维士子，兮亦孔之。","名维有司，之称维帝。"]},{"t":"咏史十四首 其一","f":"五言古诗","c":["重华受尧禅，揖让何雍雍。","奉尧若考妣，臣道尽始终。","夏王继虞统，心与重华同。","汉家逆操子，亦欲希前踪。","如何臣故主，贬号山阳公。"]},{"t":"咏史十四首 其二","f":"五言古诗","c":["周公作周礼，本以致太平。","后来讲求者，往往乱自生。","一悲新室篡，再苦新法行。","善哉豫公语，万古当作程。","关雎与麟趾，此化何时明。"]},{"t":"咏史十四首 其三","f":"五言古诗","c":["寄生根不牢，蜾裸种还异。","当时浪自喜，久远安可计。","鄙哉文信侯，蕞尔琅琊吏。","坐令秦晋史，半作他人帝。","厉阶谁所启，剿灭固天意。","独喜赵王孙，世主沙漠地。"]},{"t":"咏史十四首 其四","f":"五言律诗","c":["霸王弑义帝，汉祖诛元勋。","君臣道既绝，可得全其身。","平生固不同，毕竟同一死。","不知垓下剑，何似淮南矢。"]},{"t":"咏史十四首 其五","f":"五言古诗","c":["王陵在汉军，母伏剑于楚。","赵苞守渔阳，母作鲜卑虏。","二子皆名臣，忍独遗其母。","忠孝有偏重，贤者当自处。","我爱徐元直，翩然别新主。"]},{"t":"咏史十四首 其六","f":"五言律诗","c":["大狱考巫蛊，穷兵击狂胡。","壮心一朝悔，刚断今古无。","轮台诏西极，望苑起后湖。","朝歌罔怪者，社稷终为墟。"]},{"t":"咏史十四首 其七","f":"五言古诗","c":["世祖中兴主，手拯三纲颓。","温温东海王，废弃同草莱。","子房致园绮，国本无惊猜。","乃知隆准公，决断何雄哉。","邓侯奉朝请，严生归钓台。","高光可并驾，史论空喧豗。"]},{"t":"咏史十四首 其八","f":"五言古诗","c":["孔明讨汉贼，凛凛三代师。","广厦既已倾，一木安可支。","想象鞠躬志，惨澹风云姿。","亦有王将军，举义何孜孜。","伐陈奉孱主，百折无回辞。","嗟哉古烈士，万世同一时。"]},{"t":"咏史十四首 其九","f":"五言古诗","c":["犍为李孝子，本是汉家人。","不受邺中诏，名节今古闻。","胡为让官表，自称伪朝臣。","我欲删此语，庶作无瑕珍。","客言且勿删，不见扬子云。","已受中散禄，更上美新文。"]},{"t":"咏史十四首 其十","f":"五言律诗","c":["洸洸死后名，赫赫生前功。","古来贤达士，谦伐心靡同。","洒涕岘山顶，沈碑襄水中。","惜哉羊与杜，此念何匆匆。"]},{"t":"咏史十四首 其十一","f":"五言古诗","c":["炀帝伐炀公，亲自提戈戟。","殷鉴尚不远，何况目所击。","如何大业纪，半是亡陈迹。","由来昏德主，先后同一失。","所惜贞观君，再发辽东役。"]},{"t":"咏史十四首 其十二","f":"五言律诗","c":["太宗内巢妇，不惧辰嬴耻。","后来聘充华，闻谏即能止。","昏昏复昭昭，哲后固如此。","古云狂作圣，敛袂观唐史。"]},{"t":"咏史十四首 其十三","f":"五言古诗","c":["赵氏有家法，不戮士大夫。","秦济两宗王，恨骨犹号呼。","亲亲既如此，朝野将何如。","飞愚社稷臣，东澈周孔徒。","一朝恣砧斧，不啻厖与猪。","宋人善粉饰，此语良不诬。"]},{"t":"咏史十四首 其十四","f":"古风","c":["宏范北元帅，世杰南将军。","两人本兄弟，奉主各致身。","厓山?风起，顷刻生死分。","烈烈万古忠，矫矫一世勋。","我方编二史，执笔扬其芬。"]},{"t":"杂诗二首 其一","f":"五言古诗","c":["苦暑夜不寐，起读月令章。","乃知季夏后，有土居中央。","下以开素景，上以承朱阳。","寒暑相代谢，天运固有常。","如何历家算，视此殊乖张。","谓是大火西，柔金遇而藏。","三庚作三伏，坐使元化戕。","试问创者谁，眇眇秦汉王。","恭惟大统历，贤者宜消详。"]},{"t":"杂诗二首 其二","f":"五言古诗","c":["西域当晦时，微月见西北。","元有耶律氏，遂作庚午历。","斯人非妄者，乃是目所击。","流沙与昧谷，万古地不易。","相传无此语，止谓哉生魄。","天道岂不常，推移在异域。","何得起巫咸，为我究其迹。"]},{"t":"隐士五首 其一 楚狂","f":"五言古诗","c":["天王不西狩，列国多游士。","楚狂独何人，长歌向夫子。","慷慨凤德衰，当已胡弗已。","晏岁草木蕃，吾道亦云否。","岐山鸟不至，吾已方自此。"]},{"t":"隐士五首 其二 沮溺","f":"五言古诗","c":["辨士朝入境，莫享禄万钟。","胡为两遗老，垦此荒田中。","行行问津者，日晚悲途穷。","邯郸杀鸣犊，颈血流殷红。","临河返车辔，太息尼山翁。"]},{"t":"隐士五首 其三 荷筱","f":"五言古诗","c":["丈人皓须眉，以杖荷其筱。","不暇与客言，耘此田间草。","日暮游客来，鸡黍聊结好。","膝前两儿郎，终岁足温饱。","栖栖陈蔡间，弦歌向谁道。"]},{"t":"隐士五首 其四 晨门","f":"五言古诗","c":["石门何巍巍，下有司晨者。","击柝夜不堪，随分老田野。","中原多战伐，仁义若土苴。","栖迟复何为，所幸知者寡。","何意鲁乘田，终年走车马。"]},{"t":"隐士五首 其五 荷蒉","f":"五言古诗","c":["于于田舍翁，行行荷其蒉。","过馆闻磬声，知是客游卫。","嗟此行路难，莫道隐居易。","徬徨野水侧，浅揭深则厉。","多少乘桴心，终成半途废。"]},{"t":"古诗二首 其一","f":"五言古诗","c":["墙东马缨蕊，朝开夜还合。","墙西木槿花，朝放夜已落。","化机有常运，物性固难凿。","胡乃万物灵，冥行苦不觉。","得失觉何有，终身浪悲乐。"]},{"t":"古诗二首 其二","f":"五言古诗","c":["新秋原野净，閒步西山麓。","山上有骁媒，山下有麀鹿。","见之感物理，不觉心烦促。","天生本同类，何忍自鱼肉。","弋人前致词，弋具未为毒。","不见馀耳交，一旦成翻覆。"]},{"t":"出塞行","f":"七言古诗","c":["汉家将军如虎貔，铁衣炯炯登肜墀。","鞠躬再拜向天子，肘系金印盘双螭。","阴山之阴单于宅，名王渠帅相出没。","天诛一顾不可留，旌旗如云戒明发。","袖中剑气吞长虹，指麾白日回苍穹。","偏师五路捣沙碛，铁骑十万屯云中。","皇威四驰掣惊电，胆落旄头逐飞箭。","降车昼走穹庐王，捷书夜报明光殿。","君王有诏无穷追，凯歌散入边城陴。","满决银河洗兵马，尽收土宇归华夷。","明廷告勒有尊敦，钜笔如椽我当载。","酒酣击节聊载歌，一为将军歌出塞。"]},{"t":"元夕灯诗十首应制 其一 起火","f":"七言绝句","c":["活火翻成一缕烟，暖风吹上碧云边。","须臾响作春雷起，万紫千红献帝前。"]},{"t":"元夕灯诗十首应制 其二 牡丹","f":"七言绝句","c":["曾烧银烛照红妆，贪睡花神梦正长。","高卧不知身已幻，碧纱笼里度春光。"]},{"t":"元夕灯诗十首应制 其三 金莲","f":"七言绝句","c":["内前花炬刻金莲，彻送儒臣事漫传。","此夕一枝光照夜，顾因观赏监当年。"]},{"t":"元夕灯诗十首应制 其四 木香","f":"七言绝句","c":["煌煌火树照金门，不倩韩郎为染根。","御苑春光长不老，好花开到木香盆。"]},{"t":"元夕灯诗十首应制 其五 石竹","f":"七言绝句","c":["银缸分出影参差，旋点朱英上绿枝。","一夕自开还自谢，化机谁谓有停时。"]},{"t":"元夕灯诗十首应制 其六 玉簪","f":"七言绝句","c":["一种名花号玉簪，冰容斜倚翠云衾。","谁知点缀春宵景，尽把芳心变赤心。"]},{"t":"元夕灯诗十首应制 其七 古老钱","f":"七言绝句","c":["字画依稀古老钱，火中埋没几团圆。","休言转眼全无用，买断鳌峰不夜天。"]},{"t":"元夕灯诗十首应制 其八 蝶恋花","f":"七言绝句","c":["鳌山花卉竞春红，舞蝶时来趁煖风。","一霎不知何处在，恍疑飞过漆园东。"]},{"t":"元夕灯诗十首应制 其九 飞火","f":"七言绝句","c":["夜深灯火下蓬莱，一片飞霞烛上台。","箫鼓不惊仙漏永，芙蓉芍药满山开。"]},{"t":"元夕灯诗十首应制 其十 金菊","f":"七言绝句","c":["巨鳌峰下彩云深，谁遣秋容入上林。","始觉化工生意溥，菊花新放满枝金。"]},{"t":"与亨大懋衡二太史天瑞元益贯之三给事同游神乐观是日廉伯有约不至 其一","f":"七言律诗","c":["城楼旗角荡朝晖，行入郊坰访翠微。","尘净石坛门闭早，藓封山径客来稀。","柳阴閒系青骢马，花气浓薰白苧衣。","南郭堤沙平似掌，不妨身戴月明归。"]},{"t":"与亨大懋衡二太史天瑞元益贯之三给事同游神乐观是日廉伯有约不至 其二","f":"七言律诗","c":["城南策马一经过，眼底偏惊乐事多。","地主旋开桑落酒，山童能唱竹枝歌。","翠云宫殿闻玄鹤，青草池塘见白鹅。","却爱道人幽独好，几时携手入烟萝。"]},{"t":"与亨大懋衡二太史天瑞元益贯之三给事同游神乐观是日廉伯有约不至 其三","f":"七言律诗","c":["宿雨初晴晓出关，偶然行乐便忘还。","棋声互答闻松外，诗韵分题写竹间。","鳌背朵云瞻北阙，马头残照见西山。","故人何事红尘里，不共知心半日閒。"]},{"t":"送杨朝用挥使受代还金陵","f":"七言律诗","c":["将军才子重文韬，楚楚登坛一凤毛。","禁阙柳迎新试马，辕门花拂旧征袍。","离亭晓日红尘动，归路秋风白浪高。","江上太平无战伐，不须重淬百金刀。"]},{"t":"送董尚矩编修省亲还宁都","f":"七言律诗","c":["三载抽毫近御屏，一封优诏许归宁。","亲闱宠浥钧天露，文苑光回午夜星。","泽国离筵秋看剑，河桥挝鼓昼扬铃。","乡人定识江都裔，曾把天人对汉庭。"]},{"t":"题青州先贤祠","f":"七言律诗","c":["青州名迹半荒凉，只有丛祠古道傍。","百代英魂随水去，一方遗泽共山长。","秋来废苑甘棠老，春到空阶碧草芳。","闻说西平贤太守，怀人时见菊花觞。"]},{"t":"分得戏马台送李应祯舍人还江东","f":"楚辞体","c":["拔山壮士重瞳子，一战雎阳万人死。","归来戏马筑高台，四顾凭陵剑光紫。","霜蹄騕袅空复多，骓不逝兮将奈何。","芳草千年台下土，西风一夕帐中歌。","王孙衣锦还江左，楚树青青系征舸。","登高把酒问兴亡，芒砀山头日初堕。","苜蓿花残春水生，怀古匆匆不尽情。","回首荒基何处是，淡烟疏柳隔彭城。"]},{"t":"中伏日西风大作三日昼寒太守李昂重建","f":"五言律诗","c":["暑气方全盛，秋风忽大来。","庭柯雕翠色，书案积黄埃。","病欲披新絮，愁思拨旧醅。","遥知田舍子，心事又成灰。"]},{"t":"寿潘贡士父","f":"五言律诗","c":["七帙行将近，祈年趁晚菘。","称觞来野老，捧食拜溪童。","玄发经霜白，酡颜映酒红。","名郎归侍綵，佳气满吴中。"]},{"t":"夏月有怀","f":"五言律诗","c":["露坐南楹下，东城夜未央。","上帘邀月影，移席趁荷香。","病觉吟身瘦，眠愁客梦长。","星河净如练，因尔叹殊乡。"]},{"t":"挽余钟母","f":"七言律诗","c":["一夕谖花惨不开，满庭凉露鹤声哀。","神姬约伴游仙去，帝子亲书遣祭来。","古道悲风吹绛旐，玄墙阴雨上青苔。","倚庐人诵南陔处，愁见当时玉镜台。"]},{"t":"乐丘八咏分得卧虹桥为沈时旸主事乃翁赋","f":"七言律诗","c":["五湖东半落枫桥，隐若晴虹破寂寥。","漫漫芙蓉难识路，阴阴杨柳乍通潮。","分披野色寻幽惯，倚徙江天入望遥。","想去乐丘应不远，过从时复见渔樵。"]},{"t":"病起","f":"五言绝句","c":["卧病经旬久，开窗思有馀。","不知秋几许，黄叶满庭除。"]},{"t":"中秋病中时与李士钦叔侄近别","f":"五言律诗","c":["西风能几日，此夜忽中秋。","宇宙清如洗，山河影欲流。","病身愁对酒，羁思懒登楼。","遥想南归者，凄凉共一舟。"]},{"t":"云乐","f":"五言律诗","c":["居官淹冀土，全室住江关。","弟妹身如玉，庭闱发未班。","昼眠思剑外，晚眺近西山。","扰扰红尘里，何时解绶还。"]},{"t":"古镜行","f":"七言古诗","c":["何代青铜没深土，野人得自漳河浒。","藓花半蚀未经磨，云是朱砂水银古。","暗中忽有光射人，历年想过汉与秦。","背刻蛟螭杂鸾雀，制样不似菱花新。","良朋寄赠来千里，坐客摩挲惊且喜。","共言旧物真是奇，拂拭还收锦囊里。","千金有价遇尔难，晓奁不许窥团团。","留取他年奉明主，坐使奸谀心胆寒。"]},{"t":"侯门怨","f":"七言古诗","c":["绮窗日暮愁云结，宝鸭香销紫檀屑。","美人一去不复还，恨满空林听鶗鴂。","金盘蜡烛半成灰，罗幌凝尘惨不开。","王孙夜夜愁多梦，疑有芳魂落镜台。","捲帘忽见孤飞燕，白日光阴疾如箭。","坟头应长素馨花，长对春风寄幽怨。"]},{"t":"题杨补之松桧图","f":"七言古诗","c":["五松已受秦封辱，六桧复被秦名污。","参天直干尚如此，二雏已灭随烟芜。","大夫伪号若刍狗，处士雄心射牛斗。","眼前便觉风雨来，耳畔疑闻蛰龙吼。","良工此图笔意精，王孙一购千金轻。","恨无大手如子美，为赋成都古柏行。"]},{"t":"六月五日雨后早朝偶然作","f":"五言古诗","c":["夜来一尺雨，汨没西家墙。","不知早已霁，但觉天苍凉。","独行御沟畔，流水声泱泱。","仰视河汉间，星斗烂辉光。","好风吹苧衣，毛发森秋霜。","渺然鸱夷子，扁舟泛江乡。","又若万里鸿，凌厉青云翔。","人生贵适意，此境安可常。","遥遥禁中鼓，隐隐夜未央。","下马一憩息，旭日升东方。"]},{"t":"义轩遗诲编","f":"五言古诗","c":["莆中有高人，乃是太丘孙。","当其易箦时，神气了不昏。","治命五十六，恳恳皆名言。","宿草经几年，手泽今尚存。","我时再拜观，长恨隔九原。","鄙哉邺中子，香履留私恩。","亦有汴京相，苦欲为缁髡。","平生竟何如，此道不复论。","掩卷三叹息，彷佛来生魂。"]},{"t":"斋居次韵世赏廷言","f":"七言律诗","c":["多才几宿共斋诚，玉署三回见月生。","纪盛又传新得句，怀人空读旧题名。","幽花小埭春光浅，古木回廊夜气清。","只恐御坛高处冷，寝帏通夕未忘情。"]},{"t":"立春南郊送驾次韵亨父 其一","f":"七言律诗","c":["虎符清晓发千牛，黄道乘春出翠斿。","远陋汉仪祠泰畤，早闻周乐奏崇邱。","风回礼殿铃声杂，月上行宫扇影稠。","共喜一宵阴色净，帝心元自与天游。"]},{"t":"立春南郊送驾次韵亨父 其二","f":"七言律诗","c":["前日亲郊看卜牛，天门此夕驻龙斿。","斋居散吏瞻宸扆，扈跸才人识帝丘。","枫陛漏随春日转，竹宫灯杂夜星稠。","礼成共喜沾周宴，何必惊心数宦游。"]},{"t":"次韵原博宾之舜咨鸣治赐宴联句 其一","f":"七言律诗","c":["一派钧韶合内筵，叨陪还厕玉堂仙。","虎贲队拥戈三百，鹤酝材高斗十千。","镐邑风云春燕喜，尧阶簪绂晓蝉联。","词林四度沾嘉会，鬓压宫花忆少年。"]},{"t":"次韵原博宾之舜咨鸣治赐宴联句 其二","f":"七言律诗","c":["晓殿晴光覆四筵，坐中人是谪来仙。","銮回阁道旌幢半，骑列句陈甲胄千。","棫朴愿歌周代雅，柏梁谁续汉庭联。","龙颜共喜春先上，旰食忧勤记往年。"]},{"t":"次韵原博宾之舜咨鸣治赐宴联句 其三","f":"七言律诗","c":["衮衣亲押庆成筵，步辇乘春下集仙。","尚食缓传杯数九，教坊争出舞群千。","晴薰御纛虹光动，花覆宫袍兽锦联。","席上忽看云绚彩，从龙佳气入新年。"]},{"t":"次韵原博宾之舜咨鸣治赐宴联句 其四","f":"七言律诗","c":["黄幄中分列御筵，捧觞新曲度游仙。","漏声书下铜龙五，仗影春回玉马千。","白雪调烦词客和，红云班许近臣联。","不知泰岳登坛处，石检重封是几年。"]},{"t":"题画","f":"七言绝句","c":["黄鸟飞飞绿树低，望中疑是上林西。","君王不受珍禽献，一任空山自在啼。"]},{"t":"送李立之太常先生再赴南京 其一","f":"五言律诗","c":["南国旧衣冠，重游兴未阑。","文章周柱史，礼乐汉祠官。","台阁抡材久，郊亭话别难。","直应行色好，梅柳遍江干。"]},{"t":"送李立之太常先生再赴南京 其二","f":"五言律诗","c":["又送容台去，分司识故宫。","一尊留夕照，双佩下春空。","地迥燕山隔，冰消潞水通。","临风思无限，云起暮江东。"]},{"t":"与廉伯世贤同至月河寺","f":"七言律诗","c":["秋风吹雨净飞埃，十日东城两度来。","绕院绿阴留客住，一亭红艳对僧开。","芙蓉涧侧观澜去，苜蓿园西问稼回。","有约明朝更携手，望云同上雨花台。"]},{"t":"过观音寺和壁上旧日留题","f":"七言律诗","c":["胜地曾容半榻分，当时不厌往来勤。","风尘尚识门前路，岁月惊看壁上文。","旧屋雕梁空燕垒，古原青草见羊群。","西风不尽登楼兴，宦况萧然薄似云。"]},{"t":"元日寿董都督","f":"七言律诗","c":["旌节初离海上营，喜从元日庆长生。","函关气逐东风到，垒壁星连北斗明。","射虎不忧双臂弱，据鞍宁许一身轻。","侯门最得春光早，满进椒花酒数行。"]},{"t":"分得荷荡香风为周民表评事赋先茔十景","f":"七言律诗","c":["一川云锦为谁栽，香触繁阴扫不开。","依约似随菱唱散，飘扬还近藕船来。","青房雨歇游鱼上，翠葆风回宿鹭猜。","极目感慈山下路，水花空对夕阳台。"]},{"t":"题倪云林小景","f":"七言古诗","c":["平生最爱云林子，雅澹高情非画史。","偶然落笔自可人，不藉丹青布生纸。","石田茅屋谁所营，疏篁老木摇春声。","轻绡半幅不盈咫，十里溪山无限情。","临风恍在西湖里，只欠双桡荡湖水。","晚潮初落少人行，菱唱依稀月中起。","云林老去今几年，风物萧萧似眼前。","焚香闭阁无尘事，愿借山堂一榻眠。"]},{"t":"黄鹤山樵山水为杨考功宗器题","f":"七言古诗","c":["黄鹤山樵已仙去，风采惟留画中趣。","几回把玩欲招呼，海阔天高不知处。","但见一亭临大河，远峰对面如青螺。","孤洲水花晚色净，疏林落叶秋声多。","少年我忆游江汉，好山最喜推篷看。","迩来寄足尘海中，梦魂长到黄芦岸。","考功家近七闽山，雅怀亦似水云閒。","题诗不尽莼鲈兴，何日相期解绶还。"]},{"t":"偶作寄王用宾太守","f":"七言绝句","c":["侯门不肯礼儒生，年少元戎更不情。","此际贺兰山下路，西风落日槛车行。"]},{"t":"偶成","f":"七言绝句","c":["丁香枝上叶初繁，渐觉疏阴过短垣。","睡起不知初日午，画帘风动雀声喧。"]},{"t":"送克俭克宽弟省觐南京 其一","f":"七言绝句","c":["江流不尽弟兄情，此日那堪送汝行。","一片离魂收不住，夜来先到石头城。"]},{"t":"送克俭克宽弟省觐南京 其二","f":"七言绝句","c":["二月城南草似烟，二郎齐上木兰船。","江行记取云飞处，正是愁人白昼眠。"]},{"t":"送克俭克宽弟省觐南京 其三","f":"七言绝句","c":["杨柳青青叶尚稀，赠行空有泪沾衣。","他时何处添离恨，水国秋风一雁飞。"]},{"t":"宁国蒋氏山居四景 其一 竹屋书巢","f":"七言绝句","c":["草玄何处结檐楹，一坞深深竹数茎。","子夜天风来谷口，吾伊声杂翠鸾声。"]},{"t":"宁国蒋氏山居四景 其二 梅溪钓艇","f":"七言绝句","c":["双桨悠悠出岸沙，钓鱼人住水西涯。","隔溪残雪春犹浅，时见寒梅一树花。"]},{"t":"宁国蒋氏山居四景 其三 丹厓错薪","f":"七言绝句","c":["红叶纷纷蔽草莱，不辞提斧斲苍苔。","断厓斜日无人到，时听樵歌出涧来。"]},{"t":"宁国蒋氏山居四景 其四 绿野腴田","f":"七言绝句","c":["茅屋山头布谷鸣，老人忙起课农耕。","不知门外春多少，稻颖青青一望平。"]},{"t":"苦热与汪汝温露坐树下怅然有怀","f":"五言古诗","c":["赤日行天中，歘若飞火轮。","炎光一回薄，勃勃来蒸人。","山云惨不兴，池水枯无津。","花枝半怃悴，物色多酸辛。","羁怀苦不释，奈此朱明辰。","虚堂敞前楹，夐寂无四邻。","古槐荫庭除，扫地铺藤茵。","冷然生细爽，拂拂清我神。","丝桐一挥手，岸此华阳巾。","玄蝉起长号，微风动青蘋。","世鞅少息肩，忽忆江之滨。","园池既潇洒，竹树清无尘。","念我群从友，欣然奉双亲。","整冠自叹息，悲哉游子身。"]},{"t":"东风解冻应制","f":"七言古诗","c":["去岁都城三尺雪，御水潺潺冻全结。","半夜春从地底回，一片菱花煖初裂。","春风著水水不知，縠纹澹澹挼清漪。","退朝閒步石桥上，流澌半入昆明池。","黄柳垂丝拂东岸，荡潏波心影凌乱。","青阳杲杲射圆沙，几簇鱼苗聚还散。","太乙东皇随斗行，韶华拍塞皆春声。","临流揽胜心独喜，物色向人如有情。","天潢固是得春早，坐想八方春更好。","航海番人入贡来，万里川光净于扫。"]},{"t":"春山雪霁应制","f":"七言古诗","c":["东风夜扫肜云散，坐见西山倚晴汉。","旭日昭回万玉林，芙蓉百二光凌乱。","韶华却在璚岛中，玉泉水来如白虹。","野人行爱草木润，飞鸟下顾川原空。","乘春骋望登高阁，春意山容两回薄。","天开图画绕都城，共喜年初得嘉乐。","太平有象乐未央，不用大蒐开猎场。","凤池旧重郢人曲，阳春白雪成新章。","极目崔嵬动遐想，山下游车护来往。","满前物色总宜人，细麦青青更堪赏。"]},{"t":"癸巳日长至与世贤太史陪祀山陵往反得律诗十首 其一 沙河道中用廉伯赠行韵","f":"七言律诗","c":["冷吹抟沙没草莱，日高阴色未全开。","人穿败叶林中去，路指荒城尽处回。","旅舍晨炊供熟黍，谯楼晚角弄残梅。","五年不识风尘苦，两度叨陪李贺来。"]},{"t":"癸巳日长至与世贤太史陪祀山陵往反得律诗十首 其二 宿昌平再用前韵","f":"七言律诗","c":["暂停饥马啄荒莱，寒入重衾手倦开。","残雪夜惊双涧合，鲜飙晨送一阳回。","前村野色催行李，何处歌声调落梅。","明发园陵天尺五，溪山应识我重来。"]},{"t":"癸巳日长至与世贤太史陪祀山陵往反得律诗十首 其四 用世贤韵","f":"七言律诗","c":["东山岭上冻云重，落木寒山有虎踪。","薄宦征行非汉使，老农歌颂似尧封。","沙痕曳白萦枯苇，日脚垂红透曲松。","短策羸骖驱不进，滥骑安得马如龙。"]},{"t":"癸巳日长至与世贤太史陪祀山陵往反得律诗十首 其五 斋所用世贤韵","f":"七言律诗","c":["斋居门对此山幽，且拂枯枰角两筹。","百里风尘劳法从，四陵云气想宸游。","官奴识路行篝火，客子凌寒坐拥裯。","不尽往来分榻意，遣情时藉管城侯。"]},{"t":"癸巳日长至与世贤太史陪祀山陵往反得律诗十首 其六 再用廉伯韵","f":"七言律诗","c":["旋拥山炉爇断莱，疏棂正对土床开。","女墙月上催诗就，寝树风残约梦回。","雪后弊衾寒似铁，病来吟骨瘦于梅。","空山露下人踪灭，忽听铃声枕畔来。"]},{"t":"癸巳日长至与世贤太史陪祀山陵往反得律诗十首 其七 谒陵用东山岭诗韵","f":"七言律诗","c":["十年如梦漆园翁，两度西陵更向东。","先帝未归黄泽马，小臣徒抱鼎湖弓。","明楼雾气寒初散，御沼冰花煖欲融。","想得宸游应恋此，灵舆来下月明中。"]},{"t":"癸巳日长至与世贤太史陪祀山陵往反得律诗十首 其八 再用廉伯韵","f":"七言律诗","c":["野樵谁敢斲蒿莱，翠柏阴中兆域开。","鹓序衣冠晨拜舞，龙宫星斗夜昭回。","宣章道士声如鹤，守影中人发似梅。","礼罢不须灯火伴，联镳乘月下山来。"]},{"t":"癸巳日长至与世贤太史陪祀山陵往反得律诗十首 其九 土城怀古再用世贤韵","f":"七言律诗","c":["废堞荒凉水色幽，昔人曾此夜传筹。","西风不见龙鸾过，斜日空馀鹿豕游。","行旅似闻吹晓角，直更谁复抱寒裯。","兴亡总逐浮尘散，输却青山一醉侯。"]},{"t":"癸巳日长至与世贤太史陪祀山陵往反得律诗十首 其十 入城与世贤别仍用其韵","f":"七言律诗","c":["晓过荒城望九重，马蹄偏识旧行踪。","河山沃野围京界，烟火连村别县封。","露气渐消双凤阙，日华先上万年松。","城门暂与君相别，还约联珂觐六龙。"]},{"t":"挽西安王太守","f":"七言古诗","c":["太守王公家太行，埋玉虽久声琅琅。","我观东海笔循吏，生色澹沲如登堂。","公初作官不择禄，海上二州成善俗。","后来坐治海丰城，百姓至今犹聚哭。","西安大郡称关中，贤守只云王海丰。","当时去思耿未已，棠阴白草悲秋虫。","人言仕学皆前定，阴功不似公家盛。","三世相传五马符，前有金华后安庆。","安庆高文如乃公，不久报政蓬莱宫。","玺书锦袍还旧物，墟里一日生春风。","我忆王公渺何处，遗泽不随漳水去。","观风使者问先贤，认取庭前古槐树。"]},{"t":"题陈宪章梅花","f":"七言古诗","c":["燕南雪花大如掌，点缀枯槎夜深响。","怅然忽思羌笛声，恨不西湖拨双桨。","赵君喜走江南村，晓持写真来扣门。","小堂虚白凛相对，便觉生意回孤根。","朔风飘萧天色冷，的是当时湖上景。","摩挲欲扫树间苔，舒卷愁翻月中影。","君家仙子真风流，一醉曾赊紫绮裘。","罗浮山下作春梦，素娥执手增离忧。","闻君跨马山阳去，驿路还应得奇遇。","逢人寄取折枝来，莫忘西斋赋诗处。"]},{"t":"甲午六月二十二日闻四龙挂空中大雨","f":"七言古诗","c":["迅雷殷殷声动地，一阵灵风送阴气。","忽见四龙垂半空，头角犹在乌云中。","三龙蜿蜒只摇尾，一龙爪欲翻海水。","须臾分向东西行，大雨飒飒如盆倾。","奇观最是神龙变，卧病空床不相见。","坐闻客语心茫然，叶公之图人浪传。"]},{"t":"盆池莲盛开","f":"七言绝句","c":["盆池荷叶似人长，菡萏开成品字妆。","无奈一春离思苦，赏心空负碧筒香。"]},{"t":"夏月坐柰子树下","f":"七言绝句","c":["散发萧然坐月中，庭柯移影上帘笼。","栖禽何事惊飞起，熟果因风坠软红。"]},{"t":"寄坦侄","f":"七言绝句","c":["一从相别潞河头，回首风光已暮秋。","知汝近来应念我，等閒谁伴竹林游。"]},{"t":"月夜小饮李符台家","f":"七言绝句","c":["绿槐庭下动秋风，草酌相看一笑同。","久坐不知更漏永，月轮飞上屋山东。"]},{"t":"桃源图诗","f":"七言古诗","c":["冬青之木郁葱葱，日落水流西复东。","岁岁年年人不同，桃花依旧笑春风。","百年废兴增叹嘅，落红万点愁如海。","今年花胜去年红，明年花开复谁在。","可惜落花君莫扫，孤芳转盼同衰草。","对此如何不泪垂，十年花送佳人老。","志士幽人莫怨嗟，看到子孙能几家。","寸根千里不易到，留种河阳一县花。"]},{"t":"挽丘时雍太守父晖庵先生","f":"五言古诗","c":["家住番水上，从军向辽阳。","代父远行役，日寓刁斗傍。","时陈俎豆容，绝学惊殊方。","坐令先轸徒，抠衣进中堂。","归来迫迟莫，喜有名家郎。","封君谢恩宠，居然事冠裳。","春阳澹晖晖，颜色忽已藏。","人生首丘愿，浪踪安可常。","伟哉全归子，宿草今苍凉。","我欲奠鸡絮，渺渺川途长。"]},{"t":"夏至日雨病中喜二弟来自南京","f":"五言古诗","c":["亢阳苦作厉，人物皆昏如。","兹辰一阴生，况与甘霖俱。","燔燄忽已扫，清气回堪舆。","我方病炎热，展转无宁居。","得此若新濯，洒洒心情舒。","依约小床润，点射明窗虚。","况我同胞子，千里来宁予。","雁行夜联榻，咫尺庭中隅。","琅琅语颇闻，喜今到吾庐。","伏枕听檐滴，漏下二鼓馀。","苏韦有故事，莫惜花笺书。"]},{"t":"卧病","f":"五言律诗","c":["半生多病里，天不庇穷儒。","药有寻方苦，钱无卖俸馀。","暗消閒岁月，久废旧时书。","却幸身长在，愁怀且破除。"]},{"t":"病中不寐简仲弟","f":"五言律诗","c":["病中愁不寐，起坐听传筹。","拣药求新效，敲棋想旧游。","月明窗向晓，雨过簟生秋。","独喜王孙草，池塘绿似油。"]},{"t":"病中喜雨简季弟","f":"五言律诗","c":["病中身贮火，夜觉雨鸣阶。","厉气潜收障，清风细入怀。","池翻疑倒海，檐瀑似飞厓。","咫尺斋居子，欹床有句谐。"]},{"t":"送同年友张天瑞之陕西参议","f":"七言律诗","c":["瀛洲同会旧诸生，分省西秦重此行。","河上未收胡地马，关中犹驻汉家兵。","穷秋转饷多民隐，圣代旬宣属老成。","不负平生忧国志，按图先问受降城。"]},{"t":"送陆司寇先生致仕还四明 其一","f":"七言律诗","c":["先生韦布到公卿，更向清时取令名。","两鬓晓霜辞魏阙，一帆春雨下鄞城。","耆英自合当人望，勋业都留与世评。","归去不愁朋辈少，鉴湖烟水足鸥盟。"]},{"t":"送陆司寇先生致仕还四明 其二","f":"七言律诗","c":["杖履相从不厌频，通家惟我最情亲。","双莲约赋池中瑞，一果亲颁席上珍。","喜簉鹓行随步武，忍从鲸海送归人。","临岐忽记当时事，转眼风光十二春。"]},{"t":"立秋日雨","f":"五言古诗","c":["凉风飒然至，疏帘觉秋生。","炎熇一挥扫，蟋蟀阶下鸣。","玄发能几时，寒暑相代更。","感之卧复起，彷徨步前楹。","微风动衣袂，肃肃天宇清。","帝乡岂不好，亲舍难为情。","反坐念归计，踯躅东方明。"]},{"t":"秋日病中","f":"五言古诗","c":["我本山泽臞，不奈尘事扰。","趋朝与儤直，长时失昏晓。","况此疾侵寻，药裹讵能了。","颓然卧一榻，颇似安巢鸟。","衷肠杂云乱，苦恨知者少。","推窗一延伫，黄叶坠林杪。","寒蝉固切切，砧韵亦袅袅。","羁怀苦难释，所思在江表。","何时促归装，天长塞鸿杳。"]},{"t":"病中夜试新茶简二弟戏用建除体","f":"七言古诗","c":["建溪新茗如环钩，土人食之除百忧。","呼童满注雪乳脚，使我坐失平生愁。","朝来定与两难弟，执手共瀹青瓷瓯。","腹藁已破五千卷，举身恨不登危楼。","玉川成仙几百载，清气渺渺散不收。","典衣开怀只沽酒，闭门却笑长安游。"]},{"t":"送江淮卫知事沈德","f":"七言古诗","c":["沈君家住钱塘县，自小从师学书剑。","一朝随牒上京师，总诧青油幕中彦。","此时正伐西南夷，尚书帐前多虎貔。","君来跨马作从事，不怕羽檄如星驰。","凯旋北阙方行赏，元戎再入东西广。","载笔先须拣俊才，属櫜又复辞天仗。","朅来元戎罢远征，却总江淮漕运兵。","辕门案牍分曹署，巨舰旌旄作队行。","君在军中不贪利，学取汉朝清白吏。","主人喜是平江孙，佐史还推隐侯裔。","手提长铗漫空弹，一榻恒依大将坛。","半生饱识从军乐，八品甘为寄禄官。","莫惜青衫留滞久，老大功名须到手。","殷勤我是尚书郎，送别旗亭重回首。"]},{"t":"题牛次人韵","f":"七言绝句","c":["已销金甲事春浓，无复全齐火战功。","惟有牧儿相伴在，一山桃树半溪风。"]},{"t":"题小景画","f":"七言绝句","c":["乱石溪声到处闻，疏林山色望中分。","幽人已逐移文去，閒却茅亭一段云。"]},{"t":"题梅送朱伯承都运赴两浙","f":"七言绝句","c":["不须持酒酹花神，此去西湖正及春。","一树官梅应待久，知君才是作羹人。"]},{"t":"恩寿堂寿张给事本谦乃尊教授致政先生夫妇受封","f":"七言古诗","c":["可是名门积至諴，双亲偕老向云岩。","庭前椿树坚持久，堂北萱花迥出凡。","振铎清风传矩度，采蘋高韵协英咸。","阶除脱颖兰初茁，窗下抽荣草不芟。","骥子入官青琐禁，龙章遥拜紫泥缄。","碧闺焕锡安人号，锦轴新题给事衔。","绰楔下临涪水秀，华堂高对蜀峰巉。","琼浆献寿称金斝，彩币将诚出宝函。","南现老人朝驭鹤，西来王母夜乘羬。","檐头送喜蛛丝巧，樯半留人燕语喃。","一日恩光浮院宇，四时佳气动松杉。","仙家宴好图中绘，颂客文宜石上劖。","况是夕郎归庆处，薰风雨露满征帆。"]},{"t":"长至后二日山陵陪祀回适有诏修宋元二史纲目不肖滥预率尔赋此","f":"七言律诗","c":["晓别园陵入觐来，编摩谁意及凡材。","鹓班未放天墀散，凤敕先从史院开。","朱墨两函藏秘省，是非千古在灵台。","叨陪敢继春秋笔，予夺还应取圣裁。"]},{"t":"成化癸巳腊月十日予生盖三十年矣适有史事不克归省怅然有怀谨步韵家君守寿诗一章录似克俭克宽二弟","f":"七言律诗","c":["渐愁华发镜中生，三十年来数贱庚。","未拂朝衣惭戏綵，每沾宫酝想遗羹。","传声自愿如春好，守训何妨似水清。","忽记夜深芸阁梦，渡江称寿最分明。"]},{"t":"送赵良辅南游","f":"七言古诗","c":["冬雨三日泥不乾，一夜朔风吹苦寒。","壮游喜君正年少，何惧悠悠行路难。","城隅木叶已尽脱，晓钟满地催征鞍。","丈夫出门即万里，对酒不用歌悲欢。","君之两姊各远适，三衢白下长眉攒。","天淮去住忽相见，一笑顿使羁怀宽。","江南胜处亦可赏，吴山楚水多奇观。","人生浪迹且行乐，长剑临风时一弹。","归来定是隔年事，三月春城花未残。","白下之郎予季弟，烦君致语多加餐。","近来闻说已胜我，文辞笔下驱波澜。","蹇予苦被尘鞅缚，十度见月空团团。","送君不尽远游兴，悔作东头供奉官。"]},{"t":"新居夏夜","f":"七言绝句","c":["雨馀风起月如霜，白苧衣轻怯晚凉。","夜半呼童移席过，小楼檐下设胡床。"]},{"t":"偶成","f":"七言绝句","c":["细竹编篱护老槎，石盆新水净无沙。","繁枝嫩叶青如剪，时见荼蘼放一花。"]},{"t":"挽朱维吉 其一","f":"七言绝句","c":["一卧幽轩梦不回，独遗寒月照疏梅。","夜深风露萧萧下，恐有吟魂跨鹤来。"]},{"t":"挽朱维吉 其二","f":"七言绝句","c":["磐石山前土一抔，几株乔木带寒流。","明明孝义题碑碣，莫为时名吊奕秋。"]},{"t":"送廉伯陪祀山陵","f":"七言律诗","c":["奉祀仙陵第几番，又随香帛荐中元。","马穿碧树知神路，人立青峰见寝园。","佩影夜联东壁序，铃声秋动北辰垣。","归途正及西城近，黍稷屯云遍野原。"]},{"t":"送曲阜孔知县","f":"七言律诗","c":["奉檄初登子贱台，素王家世不凡材。","诗书鲁壁新弦诵，井牧尼山旧草莱。","帘幕昼垂公署散，盘盂春荐享堂开。","暇时还约贤宗子，共扫奎文石上苔。"]},{"t":"送克俭克宽二弟南归","f":"七言律诗","c":["执手萧然驿路隅，西风黄叶满征车。","来分姜被情无限，去著莱衣乐有馀。","丹穴暂栖垂翅凤，沧溟终起化龙鱼。","少年一第元非幸，努力平生万卷书。"]},{"t":"武昌太守行送秦廷韶考最南还","f":"古风","c":["巍巍武昌城，屹立江汉隅，中有太守专城居。","太守北来江水寒，正直不忧行路难。","太守南归春已老，一道欢声动鱼鸟。","武昌城中官长多，能事不受相撝诃。","终岁足鱼米，父老歌逶迤。","人言太守能赋诗，太守不似元微之。","江城坐治已閒暇，一篇往往传京师。","古来儒吏亦何有，今见风流武昌守。","相逢一别会何时，目送飞鸿过樊口。"]},{"t":"题宗人愈大上舍所藏白描风荷图","f":"七言古诗","c":["镜湖水光如匹练，一霎回风舞团扇。","冯夷乍起水晶宫，仙子齐匀镜中面。","凌波徙倚欲倾城，泽荇渚蒲如有情。","素菂摇香白鹭下，青房堕影游鱼惊。","落手湘云半舒卷，晚色亭亭净于剪。","五侯池馆春阑珊，耻共铅华斗深浅。"]},{"t":"浙江参议卢君雍葬其父爱竹君于枥山庐于墓左产芝十二茎其婿编脩倪君岳求予诗","f":"七言古诗","c":["老人开轩旧爱竹，令子庐墓新生芝。","岁寒节操凛未已，三春和气钟于斯。","土屋深深枥山底，十二天然朵云蕊。","孤绝难同众草芳，色映薇花照江水。","回望谢庭花满烟，儿孙玉立如芝妍。","古人孝感非浪语，至性由来天所怜。"]},{"t":"读宋史四首 其一 太祖","f":"七言绝句","c":["黄袍那得便加身，禅诏由来宿搆新。","地下董狐招不起，谁将心事许三臣。"]},{"t":"读宋史四首 其二","f":"七言绝句","c":["乱离初见武功成，掌上河东未足平。","开宝八年归正统，至公书法爱徐生。"]},{"t":"读宋史四首 其三 太宗","f":"七言绝句","c":["野录山僧本好奇，是谁删润转生疑。","由来授受分明处，涑水先生却备知。"]},{"t":"读宋史四首 其四","f":"七言绝句","c":["金匮盟寒固可哀，何缘推出杀心来。","斧声烛影都无谓，胜国诸公有史才。"]},{"t":"成化甲午冬十二月二十一日祈雪斋居适吴兴沈用宾寓宿公署分韵得西字","f":"七言律诗","c":["寓公清致本苕溪，借榻三回听晓鸡。","出韵令严诗律险，弹棋人倦子声低。","清斋坐合金兰契，法从班联玉笋齐。","雅集又成新故事，独怜才愧庾安西。"]},{"t":"借前韵求用宾作晴洲小景","f":"七言律诗","c":["十年相见掖垣西，联句无才续斗鸡。","卷里法书多魏晋，图中山色似青齐。","莎庭惊鹤霜初下，茗碗留人月易低。","肯与家林挥健笔，不辞新绢买鹅溪。"]},{"t":"斋居喜雪联句","f":"古风","c":["夜寒集疏霰，岁暮呈嘉祥。","天心重昭格，民事期丰穰。","斋诚达宵旰，祀出排缁黄。","同袍此共宿，旅夕能相忘。","凭檐俯轻飏，引烛惊微光。","严城漏声寂，小阁炉烟翔。","簌簌堕庭戺，霏霏闯堂皇。","萦空转飘撇，亚风随低昂。","乍翻燕山席，陡溢韩军囊。","剪裁谢新巧，涂抹羞妍妆。","同出联祖祢，分飞忽参商。","蚕缫散绩室，舞袂投东房。","辉增?衣净，爽激銮铃锵。","长河饫坚腹，断岭横截肪。","隉阱夷险一，羃野东西相。","雅栖惊欹仄，鸟篆馀偏傍。","疏影落高树，清威折幽篁。","雀困馀粒绝，兔穷数罝张。","委径没樵屐，回洲胶渔航。","望失远山色，坐想千林芳。","先春夺造化，异境开鸿荒。","潜阳地中复，宿沴物外藏。","馀孽息蝥螣，庶徵宜粢粱。","楼居足酣眺，市卧怜饥僵。","窗虚气逾肃，景绝诗能当。","云英幻无蒂，水种空传香。","槎通汉渚近，赋擅梁园长。","关戍肌欲皴，田畯乐未央。","沛泽浃穹壤，至治归明良。","竹宫怡圣情，词垣纪篇章。","邈哉继云汉，大庆垂无疆。"]},{"t":"焚香联句","f":"古风","c":["斋夜对炉咏，兹谋出于佥。","旃檀爇幽眇，棐几增芳严。","瑰材藉珍重，烈势防太炎。","远闻觉逾胜，默叩如有占。","片云陡惊散，一星歘疑?。","口浥曹溪流，耳割昆崙尖。","氤氲烛映屏，缥缈风回幨。","坳深隐金粟，火褪委红盐。","芸怜书蠹辟，麝恐庭花嫌。","当窗喷宝鸭，隔研萦铜蟾。","畹兰格调绝，阁梅风味添。","情通一瓣夐，剂许百和兼。","循床袭青绫，拂卷凝湘缣。","输情已绳直，逊意仍蛟潜。","咀华厌鸡舌，采沬婴龙髯。","笼烟袖双握，拨地匕屡拈。","气合惬俱化，心耽惧非廉。","继美荐奇印，留芳下重帘。","甲暖螺蜕腥，班销鹧归燖。","宁为羃广展，不作吹轻纤。","春原得孤嗔，晓殿思遥瞻。","透隙忽已駚，入虚澹相淹。","升腾各登鼎，琐碎或在奁。","妙遣荤秽屏，馨达神明忺。","终陪画省直，不受歌尘黏。","薄温变寒室，长力穷宵签。","静喜日照席，深宜私覆檐。","非同火山炽，何忧木天黔。","吟鼻讵堪拥，德芬方共厌。","燕寂未经宿，呼童惜馀甜。"]},{"t":"游月河寺次韵顾光禄 其一","f":"五言律诗","c":["空门坐隔河，风柳扇微和。","晓色城头尽，春声水上多。","过墙燕市酒，倚席渭城歌。","不尽游人兴，诗悭可奈何。"]},{"t":"游月河寺次韵顾光禄 其二","f":"五言律诗","c":["一径曲通河，经春土脉和。","破篱编苇密，老圃种花多。","惠远还能笑，昌黎不解歌。","题名人半老，莫更问谁何。"]},{"t":"挽金陵倪处士侍郎谦之族人李太常作志","f":"五言律诗","c":["家住修文巷，俄然梦不醒。","谱通宗伯系，冢勒太常铭。","猗顿千金产，童乌一卷经。","不堪人堕泪，择葬近新亭。"]},{"t":"镜中偶见白须","f":"七言律诗","c":["晓起掀髯笑不梳，镜中霜到一茎初。","他乡转觉官无用，半世空惊病有馀。","閒处欲寻支遁语，老来思共阿咸居。","平安独喜南鸿便，一月常收两度书。"]},{"t":"成化乙未廷试受卷纪事有作时年三十 其一","f":"七言律诗","c":["大廷多士若云屯，入对从容感至尊。","新雨过城开晓霁，好风吹柳散春温。","尚方络绎来珍馔，中使催呼锁禁门。","回首十年如梦里，传胪当日愧蒙恩。"]},{"t":"成化乙未廷试受卷纪事有作时年三十 其二","f":"七言律诗","c":["文华清禁接词林，阅卷亲劳法驾临。","黄纸墨痕春淡淡，紫垣钟漏午沈沈。","风云此日开文运，忠孝何人契主心。","今夜礼曹还赐烛，早随冠冕听纶音。"]},{"t":"寿灵台郎吴英母九十","f":"七言律诗","c":["暖风开宴敞云屏，慈寿从今数百龄。","盘诰紫鸾恩浩荡，传书青鸟意叮咛。","北堂秀发宜男草，南极光躔婺女星。","莫对绛人提甲子，五官声价重尧庭。"]},{"t":"夜梦家君晓起得家书时家君已得请还乡","f":"七言律诗","c":["梦接庭闱语未阑，晓来南雁寄书还。","平安字抵千金价，晚节功成九仞山。","窃禄尚堪供薄养，远游何日奉尊颜。","遥知两弟称觞处，綵服应留一副閒。"]},{"t":"琼岛春云应制","f":"七言律诗","c":["五色氤氲晓未开，一春长绕玉峰来。","成祥顷刻非无意，行雨分明是有才。","御气远通花萼殿，灵根偏护柏梁台。","望中忽感从龙念，恐有遗贤在草莱。"]},{"t":"季弟克宽来京师适当端午西湖南海之莲尚未有花而予家盆池特出二萼化工之巧有若为予两人者设耳克宽南行有期辄用开宴以酬花因思予在西城时此花亦于五月盛开司寇陆公辈各赋一诗以为予中举之徵其后果然今十四年矣故诗及之","f":"七言律诗","c":["谁家端午看芙蕖，蜗舍风光似有馀。","苒苒红苞初半拆，田田青伞未全舒。","酒筹暗合愁新别，诗谶先徵忆旧居。","莫忘弟兄携手处，一帘花雨湿征裾。"]},{"t":"次韵罗明仲太史中元谒陵仆三度谒陵皆以冬至又两与李世贤太史行","f":"七言律诗","c":["陪祀频烦下紫清，冒寒长记旧经行。","风生古堠惊鸦宿，月满荒城听马鸣。","花鸟送君今日路，溪山回首隔年情。","道傍老壁题诗处，定有居人说李程。"]},{"t":"送户部吴廷宪主事赴广西提学佥事得文字","f":"五言古诗","c":["泛泛濯锦江，产材多好文。","就中吴季子，壮岁迥不群。","久簉司徒班，荐书新上闻。","朝廷重兴学，简命恩礼勤。","乘骢过梅岭，持节开江氛。","念子掌邦教，此职固所欣。","都门时雨晴，岐路东西分。","峤外岂无士，成之在陶薰。","时名愧葩藻，实学须典坟。","典坟首群行，古圣非徒云。","行行志方健，宁肯上负君。","三岁谅有期，迟子来策勋。"]},{"t":"送袁士蓥太守考绩还淮安得童字","f":"五言古诗","c":["淮阳今大府，南北舟车通。","上官络绎至，卧治将无功。","使君东南来，瘦马从一童。","绩成奏天子，出门岁将穷。","君本法曹郎，皎皎白鍊铜。","坐令郡讼稀，风化千里同。","劝君一卮酒，美政贵保终。","不见古循吏，名与长淮东。"]},{"t":"洞黄词怀黄尚斌先生","f":"五言古诗","c":["洞黄何逶迤，远在天台间。","壁立千芙蓉，四顾相回环。","缅思洞中人，一去何当还。","平生读书处，松桧不改颜。","儿孙日以长，济济通朝班。","孰识岩栖翁，高名配兹山。","我歌洞黄词，怅望春阑珊。","生刍杳莫致，浙水东潺潺。"]},{"t":"大病不寐 其一","f":"五言绝句","c":["月西窗正黑，天色向黎明。","坐数传筹者，沈沈杀五更。"]},{"t":"大病不寐 其二","f":"五言绝句","c":["溽暑人如醉，昏昏一病身。","如何三五夜，番作独醒人。"]},{"t":"陆廉伯太史家赏莲得天字","f":"七言律诗","c":["小院凉生雨后天，一尊同赏瓮池莲。","散花晓日来天女，步月清宵见水仙。","坐客不辞浮白令，主人何惜买红钱。","兴来忍折芳筒尽，回首风光又隔年。"]},{"t":"八月一日丁祀夜作有怀彭文宪公","f":"七言律诗","c":["半夜奎星光烛天，诸生云拥戟门前。","閒阶露下听更坐，别院人稀借榻眠。","灯乱衣冠松外转，风清丝竹殿中传。","西湖故老今何许，分鬯叨陪记往年。"]},{"t":"贺高挥使生子","f":"七言律诗","c":["锦棚香袭旧征袍，转觉王孙甲第高。","喜气镇浮三日迥，啼声浑似五陵豪。","四筵汤饼朝开宴，左户桑蓬夜属櫜。","已是他年真将种，殷勤传付吕虔刀。"]},{"t":"送耿司业先生省亲还南河","f":"七言律诗","c":["白发萱亲在北堂，喜承恩诏趣归装。","秋容黯淡辞都下，晓梦依稀见洛阳。","莱子旧衣增刺绣，阳城新例有封章。","疏庸滥逐门生后，驻马离亭尽一觞。"]},{"t":"文渊阁大学士彭先生哀挽","f":"七言律诗","c":["廊庙忧深病亦深，西风庭木动悲吟。","文星一殒嗟何极，哀诏频颁似不禁。","三馆尚闻修宋史，八方空复望商霖。","平生忠孝封章在，不负先皇策士心。"]},{"t":"乙未十一月十六日长至有感","f":"七言律诗","c":["吟须再见一茎霜，愁思应随一线长。","月色也从今夜减，酒怀争似少年狂。","海榴漫说偏多子，乔木谁怜隔异乡。","好是浮名归未得，十年辛苦尚为郎。"]},{"t":"尹亚卿家饮散用韵二首一读景帝谥议一谢盛筵 其一 读谥议","f":"七言律诗","c":["天赋宗贤拨乱才，八方威命响新雷。","衮衣立受东朝命，玉辇迎从北地来。","九庙有灵知孝友，百年无力报奸回。","今皇盛德嗟何极，一纸虹光烛夜台。"]},{"t":"尹亚卿家饮散用韵二首一读景帝谥议一谢盛筵 其二 谢盛筵","f":"七言律诗","c":["胜日叨陪玉署才，绮筵箫鼓沸晴雷。","宫壶尚足传杯用，堂食初分入馔来。","拂座面惊春色动，联镳身带夕阳回。","题诗欲尽留连意，长句无能效柏台。"]},{"t":"腊月念八日得仲弟克俭南京书季弟克宽杭州书报家君已至徽州","f":"七言律诗","c":["两回家信一时闻，北雁如何久离群。","同气影随三处月，老亲身卧万山云。","怀归有约多成梦，窃禄无才可报君。","学业半荒须渐白，愁颜消得付馀醺。"]},{"t":"燕都石鼓题广人黄瑛江湖胜览卷","f":"七言律诗","c":["岐阳埋没草离离，汴省燕都叹屡移。","一代文章存鸟迹，百年风雨蚀鼍皮。","摩挲尚识宗周器，题跋谁镌蒙古辞。","却爱胜游黄叔度，孔庭怀古立多时。"]},{"t":"白云深处为天台赵时晖赋","f":"七言律诗","c":["幽人卜筑嫌山浅，直入云山十二重。","傍岸野樵多失路，隔林溪碓远闻舂。","衣裳露宿岚光冷，书画晴蒸海气浓。","极目为君思雁荡，烂银舒卷正溶溶。"]},{"t":"成化乙未元夕观灯应制","f":"七言古诗","c":["万岁山头春月圆，万岁山下霏祥烟。","莲花漏水尽一刻，火树百枝光烛天。","条风东来送新暖，低飏星裘动黄伞。","九重金阙倚岧峣，四面红云蔟箫管。","慈闱更欲亲承欢，綵棚十丈空中攒。","随山移仗不知晓，应制还催供奉官。","五朝故事传来久，乐与民同上元酒。","想像先皇得众心，尚有灯词播人口。","太平喜是百载过，边燧不惊天气和。","古来张弛皆有道，实心一日非为多。"]},{"t":"十二月十三日大雪","f":"七言律诗","c":["北风吹晴无片雪，老农戚戚生穷悲。","土中细麦乾欲死，方士结坛徒尔为。","残年一雪万人喜，天子忧勤天与之。","长安贫者死莫恨，记取当初望雪时。"]},{"t":"挽薛节妇","f":"五言律诗","c":["薛家贤节母，身住滆湖村。","老去霜春面，归来月夜魂。","孤鸿难再偶，慈竹自添孙。","不负生前恨，金书照里门。"]},{"t":"卜筑","f":"五言律诗","c":["频年生计拙，辛苦又移家。","未到新庭院，遥怜旧月华。","时名只人后，归梦几天涯。","银汉犹明没，因风欲汎槎。"]},{"t":"著存堂为吴节参政赋","f":"五言律诗","c":["悠悠三十载，一饭不忘亲。","推枕犹疑梦，登堂若见人。","海桑初隔世，风木几伤神。","要识全归意，平生在立身。"]},{"t":"雨后绝句示小女","f":"七言绝句","c":["天井无沙潦水空，临流一树石榴红。","女郎学语惊相报，几瓣胭脂落镜中。"]},{"t":"题姜廷宪中书小景画","f":"七言绝句","c":["雨落山前双树村，石溪流水带沙浑。","野人赤脚如归鸟，不怕春泥半拥门。"]},{"t":"哭坦侄二首 其一","f":"七言绝句","c":["两地惊心最可怜，别来长梦抱儿眠。","岂知一段青云器，只向人间住八年。"]},{"t":"哭坦侄二首 其二","f":"七言绝句","c":["恸指苍天泪两垂，海枯难尽竹林悲。","床头几卷残书册，一世辛勤付与谁。"]},{"t":"送徽州谢同知伯仪庆贺建储礼成南还","f":"七言律诗","c":["郡绂驱驰不惮劳，又惊飞絮点归舠。","八方共喜前星耀，千里回看北斗高。","阙下省台通姓字，山中城郭候旌旄。","因君不尽东南望，一片乡心折大刀。"]},{"t":"丙申郊祀斋居次陆廉伯太史韵 其一","f":"七言律诗","c":["东风吹冷袭虚襟，芸阁西头接羽林。","上界疏钟清客梦，广庭明月空斋心。","回惊旧壁题名遍，转觉微官阅岁深。","此夕圜丘天尺五，拥衾时听属车音。"]},{"t":"丙申郊祀斋居次陆廉伯太史韵 其二","f":"七言律诗","c":["露下虚庭月满襟，仰看残雪罥疏林。","久叨禁直随班尾，共誓斋明协帝心。","三宿夜分莲漏永，一年春到竹宫深。","题诗欲继云间陆，蝉噪终惭海鹤音。"]},{"t":"次谢鸣治侍讲韵","f":"七言律诗","c":["井乌声与柝声兼，阁道频将斗柄瞻。","郊墠礼神春奠玉，斋宫清跸夜传签。","月中晓色惊先白，雪后寒威觉倍严。","三日清斋无一事，水沈时向竹炉添。"]},{"t":"庆成宴与明中舜咨联句和韵","f":"七言律诗","c":["赐筵初及试灯时，一日风云会殿墀。","天静漏传金箭迥，晓寒春上玉颜迟。","羽林扈跸环千骑，宗伯垂绅正九仪。","胡越一家同献寿，八方谁道路多岐。"]},{"t":"送刑部郎中陈德修还南京用张汝弼驾部韵","f":"七言律诗","c":["旗亭柳树拂颓墙，祖席朝来扫半堂。","廿载不知游宦久，一春偏觉送人忙。","东风似与归途便，流水何如别意长。","执手难留陈仲子，锦帆回首正高张。"]},{"t":"送薛志渊御史随都宪袁公处置荆襄志渊旧尝巡按其地","f":"七言律诗","c":["圣主临朝重拊循，襄樊行幕绣衣新。","一方喜入皇图远，十载愁听捷奏频。","好计公田收菽粟，旋分官府辟荆榛。","土人半识招安使，马首山川属旧巡。"]},{"t":"广人黄昊久客于外夜梦二亲自写其像号其堂永思其父尝为主簿","f":"七言律诗","c":["细草双坟隔几春，天涯回首泪沾巾。","凄凉死别空成梦，想象生容自写真。","岭峤飞云时出岫，沧溟流水任扬尘。","伤心莫遣成衰落，不负庭闱在立身。"]},{"t":"钱塘沈德自成化丁亥以来从家君征川贵山都掌之夷又从平江伯出镇两广总督漕运清谨之操三度如一家君荐之始自从事为选人平江凡七荐之乃自江淮卫知事改隶通政司于是荐绅君子无不嘉君之能获乎二公也拜命言旋赋诗以赠","f":"七言律诗","c":["曾从川广著征袍，又辟江淮督餫艘。","旧业耻缘行橐富，新名多逐荐书高。","银台已换簪绅贵，玉帐应酬案牍劳。","莫为官成心便得，十年恩泽庆难遭。"]},{"t":"三月十七同日得王贡士寄来休宁腊月书马亚卿寄来南京二月书","f":"七言律诗","c":["客邸瞻云思有馀，忽传门外送双鱼。","正当南北相望处，连得春冬两季书。","千里开缄如面对，一番披读即眉舒。","年来转觉归期缓，日日经帏候起居。"]},{"t":"送蜀士赵显章赴渑池训导","f":"七言律诗","c":["薰风吹路铎声清，行李飘萧出帝城。","洛士自今沾化雨，川人从昔有文名。","崤函地接关河便，秦赵台危草树平。","黉舍有刑知尚在，好将蘋藻荐曹生。"]},{"t":"送克宽弟南还至茶庵独归 其一","f":"七言绝句","c":["垂野阴云一望迷，送行愁问路东西。","不知几日黄梅雨，门外青泥没马蹄。"]},{"t":"送克宽弟南还至茶庵独归 其二","f":"七言绝句","c":["赏心已负一年春，野寺从来别恨新。","酒尽沙头催上马，断堤新草独归人。"]},{"t":"送克宽弟南还至茶庵独归 其三","f":"七言绝句","c":["一径棠花照水开，可怜新病废衔杯。","早知别泪多如雨，悔不临岐尽醉来。"]},{"t":"题刘廷问舍人所藏夏仲昭太常晴雨二竹 其一","f":"七言绝句","c":["太常醉搦紫宣毫，不写李王金错刀。","阁舍朝回卷帘处，楚江风雨战秋涛。"]},{"t":"题刘廷问舍人所藏夏仲昭太常晴雨二竹 其二","f":"七言绝句","c":["旧宅依稀练水傍，古墩幽竹自成行。","披图却似身重到，刺眼翛翛凤尾长。"]},{"t":"送奎文阁典籍许节之东归","f":"五言古诗","c":["东山旧名家，文章羡之子。","先人国钜公，勋德藏太史。","当年受推荐，簪绂升孔堂。","日坐图书府，上应东壁光。","朅来走京师，奏书析帝宠。","南宫下新制，晔晔贲丘垄。","还思毕婚嫁，馆甥得刘郎。","官途凡几月，冰玉相扶将。","人生天地间，亢宗似君少。","尘鞅不可羁，拂袖一何早。","薰风日夕至，满路飞杨花。","都门戒晨发，祖席临水涯。","心知共月明，千里一回首。","良晤讵可期，属酒为君寿。"]},{"t":"送户部石宗海员外赴四川提学佥事宗海予同年尝为翰林庶吉士","f":"七言律诗","c":["徂徕家学未应芜，喜奉新恩向蜀都。","黉舍威声思按察，玉堂丰采重司徒。","行台晓月诸生试，比屋春风五教敷。","相守不堪相别处，暂留骢马尽离酤。"]},{"t":"送中书舍人桐城何志廉赴南京刑部员外予较艺礼闱志廉实预事于帘内","f":"七言律诗","c":["郎中早发帝城东，双旆遥乘雨后风。","南部司刑千里别，中朝挥翰十年功。","何当把酌寻乡好，犹记篝灯宿至公。","从此鱼书知不断，两京新路闸河通。"]},{"t":"次南京钱学士先生入朝之作时先生方有少宰之命 其一","f":"七言律诗","c":["十二年来出帝关，北归仍立旧鹓班。","交南使节陈临海，江左文名庾子山。","簪绂又新池上宠，冰霜难老镜中颜。","汉庭欲下安车召，楚水燕山路不难。"]},{"t":"次南京钱学士先生入朝之作时先生方有少宰之命 其二","f":"七言律诗","c":["桃花零落旧玄都，喜见腰金尚黑颅。","才藻自能当万乘，笔锋犹足扫千夫。","禁中前席多需贾，海上生祠半说苏。","晚节从来须郑重，百年文运藉人扶。"]},{"t":"新安洪生通今郑州守有约之少子乡进士远之弟而予兄汀州贰守克和之婿也来京师从人受春秋学日以成岁暮欲将往省于郑且南还入郡学以俟秋试其志可谓健矣道别之际赋诗赠之","f":"七言律诗","c":["綵衣遥向郑州城，书剑还为故国行。","官邸冬温先季子，京闱秋试待诸生。","匆匆立马辞乡丈，草草传觞愧馆甥。","但喜家声常不坠，一门难弟又难兄。"]},{"t":"邀同馆诸公赏盆池莲","f":"七言绝句","c":["新秋团扇不禁风，退直相期出禁东。","池馆不嫌来结社，水花犹有一枝红。"]},{"t":"题尹正言学士菊","f":"七言绝句","c":["陶家庄子未全荒，篱下西风一径霜。","红紫相看零落尽，寒花只作旧时黄。"]},{"t":"题画","f":"七言绝句","c":["苍山茅屋岁将阑，一卷黄庭读未残。","落叶暗桥何处客，杖藜来听水声寒。"]},{"t":"讲筵命下甚愧疏庸不足以从诸君子之后辄赋一诗录呈舜咨侍讲养正伯常二太史","f":"五言古诗","c":["天王重稽古，文教被九寰。","济济夔龙徒，终日奉宴閒。","自惭樗散质，久厕词林间。","一旦误简知，许缀经帏班。","儒冠岂徒荣，君德重有关。","格心古明训，志士亦孔艰。","况我本承乏，何恃开天颜。","所幸同袍人，逸驾难为扳。","致身及此时，淳风正来还。","策厉敢不勉，主恩似丘山。"]},{"t":"为柳楷序班题寿意图归庆其母","f":"五言古诗","c":["七十柳家母，双耳被华发。","行步若飞凫，飘然有仙骨。","诸子数公权，供奉广寒阙。","回首夜何其，天凉桂花发。","神娥海东至，荡潏凌波袜。","皎皎青镜中，居然事修谒。","酒酣一借问，沧溟几时竭。","携手问清浅，共拾蟠桃核。","仙凡隔尘水，三山翠峣屼。","可望不可亲，歌诗对明月。"]},{"t":"寿泰和王希诚七十","f":"五言古诗","c":["七十存斋叟，尚书一令孙。","天开新寿域，人羡旧清门。","荫子传家学，封君荷主恩。","一阳初复候，佳气满芳尊。","西江多逸老，季子独超群。","仙授还丹诀，家藏说玉文。","逢辰题甲子，阅世等烟云。","想和长生曲，因风一寄闻。"]},{"t":"题玉堂散直图送吴汝贤修撰省觐还闽","f":"七言古诗","c":["金殿当头玉堂署，十二朱廊隐宫树。","衣冠济济堂中人，犹似前时起居注。","门下斜连金水河，石桥五垒横蛟鼍。","扣阍不许外人到，挟册时见诸王过。","奎文上应图书府，插架连签照今古。","同游恐是十洲仙，下界纷纷半尘土。","迩来新诏开中堂，储材圣训何洋洋。","日令三馆坐群彦，应制往往催诗章。","从容退食龙楼外，松下传餐解簪带。","光禄之酒大官羊，终岁天厨有佳赉。","宫壶早午漏未央，旭日半下城西墙。","出门跨马人分首，缓步不知归路长。","老珰如能解人意，惯识青衫閤门吏。","几回尔女笑相嘲，何幸相从禁中地。","我居史馆今十年，碌碌追陪叨俸钱。","就中却爱吴汝贤，才气迥出千人先。","承恩谒告辞丹扆，綵服辉辉照秋水。","何人为写玉堂图，天上风光动桑梓。","我思古人不可当，身在江湖忧庙廊。","君是八闽奇俊郎，一饭之际宁可忘。","君家二老俱无恙，莫遣文章负今上。","朝朝散直定思君，早趣归装拜天仗。"]},{"t":"斋居有怀李宾之侍读次街字如字二韵 其一","f":"七言律诗","c":["月明人语静天街，一树松毛舞乱钗。","高论谁翻巫峡水，相思如隔叶山厓。","百年散地堪藏拙，三宿斋居漫寄怀。","独幸太平今有象，南郊春意十分佳。"]},{"t":"斋居有怀李宾之侍读次街字如字二韵 其二","f":"七言律诗","c":["潇洒仙郎玉不如，春来多病想离居。","赓酬未觉诗禅定，笑语偏惊墨妙疏。","斋舍月明灯晕小，严城风静柝声虚。","知君此夕应无寐，起望星垣候属车。"]},{"t":"罗明仲以所和谢鸣治枕上有怀李宾之之作见示倚而和之","f":"七言律诗","c":["西斋凉夜月生初，二妙诗成一枕馀。","春谷芝兰香雁荡，秋空冰玉倚匡庐。","寄声白雪来青琐，落手明珠动绮疏。","读罢怅然思短李，平生交好最知予。"]},{"t":"正月十二日庆成宴后有怀宾之用鸣治红字韵","f":"七言律诗","c":["赐宴归来醉颊红，故人清卧晓堂空。","联珠似觉新篇少，倚玉犹怀旧席同。","春到才情翻蜀绮，病回风骨挺湘筒。","一年灯火西城近，无限相思月又中。"]},{"t":"宴归忽思明早立春再一日元宵矣节物惊心为之怃然偶成柬倪舜咨侍读","f":"七言律诗","c":["又陪郊宴戴恩回，不觉春光次第催。","鳌禁未烧千炬烛，凤筒先动六葭灰。","喜逢令节添新岁，恐落明时数弃才。","欲向同人歌老大，陈根已负十年培。"]},{"t":"舜咨有诗见答再用韵复之","f":"七言律诗","c":["春去如流不自回，驽骀无力可鞭催。","风花近日多新稿，简册何时拂旧灰。","十载閒官真负主，八行明诏欲储才。","攴言敢恨知音少，一寸心田只自培。"]},{"t":"送陆文量驾部出使河南次留别韵","f":"七言律诗","c":["曾接芳邻会一茶，蓬门长许故人挝。","郎官标格晴翻雪，内史篇章醉吐霞。","明日又攀东郭柳，当时同看上林花。","春风联佩相思地，玉陛鞭声散晓鸦。"]},{"t":"凌季行鸿胪索赋清懒诗","f":"七言律诗","c":["不受黄尘点赐袍，朝回长卧日华高。","客疏幸免逢迎礼，官冷那知案牍劳。","胜地春风閒谢屐，异乡秋雨涩并刀。","等閒却有难忘处，瀹茗催诗夜续膏。"]},{"t":"题李世贤太史扇","f":"五言绝句","c":["浦上南风急，渔舟破浪还。","不知离岸远，时见树头山。"]},{"t":"分得知字送文公十世孙燉袭翰林五经博士归奉祀事","f":"五言古诗","c":["长河发秋水，白日吹凉飔。","冠盖集都门，把酒与客辞。","缅怀紫阳翁，耿耿百代师。","云礽袭簪组，乃在休明时。","夫君抱奇服，承恩固其宜。","考亭渺何许，孤绝天南涯。","乔木上参天，下有先公祠。","君归拜家庆，烨若阶庭芝。","大贤本不死，冥邈谅有知。","翘首北来鸿，车行勿迟迟。","所愿崇正学，慰我长相思。"]},{"t":"送提学戴廷珍御史考绩还南畿","f":"五言古诗","c":["离旌动朝旭，宪节飞寒霜。","使君有远役，驱车上河梁。","夙昔金兰交，念君才且良。","南畿数千里，弦诵声琅琅。","来荷天子恩，去慰诸生望。","君家大江西，经学闻四方。","敬承久不衰，显擢殊未央。","古人过化地，名与江水长。","分岐意无限，再进黄花觞。"]},{"t":"挽王瑞给事父","f":"五言律诗","c":["屡辞公府荐，赢得隐居名。","水石夸王令，江湖继陆生。","无方堪却老，有子解推荣。","小茗山前路，行人亦怆情。"]},{"t":"三月一日寿杨司徒夫人六十","f":"五言古诗","c":["家声自东鲁，门对重关西。","象服摇苍水，鸾封获紫泥。","晚春开寿域，迟日丽中闺。","想象称觞处，仙人馈枣梨。","览镜颜犹壮，盈簪发未疏。","寿当初度起，春入二分馀。","君子歌偕老，儿孙奉起居。","蟠桃亲手种，喜色照庭除。"]},{"t":"题张修撰养正所藏王舜耕山水画","f":"七言古诗","c":["山东老人王舜耕，平生与山如有情。","左涂右抹何草草，却似真山被山恼。","山西太史留侯孙，爱山自谓山可飧。","坐中忽有青万矗，终日仰看看不足。","我来把玩未始奇，真山假山远莫知。","天风惨澹动林壑，浮岚积翠空淋漓。","斗壁飞流下深树，暗响潺潺不知处。","两厓中断一桥通，谁结茅庐傍山住。","老人一去何当还，太史心胸如此山。","题诗不尽画中意，梦落齐州苍翠间。"]},{"t":"夏日偶成","f":"七言绝句","c":["瓜头果叶未全开，一寸新根蚀旧苔。","閒上小楼看雨脚，不知青蔓过墙来。"]},{"t":"愚乐庵为傅曰川太史乃尊赋 其一","f":"七言绝句","c":["不辞提瓮灌山畦，绕屋江声似冉溪。","却笑永州憔悴客，壶觞终日叹羁栖。"]},{"t":"愚乐庵为傅曰川太史乃尊赋 其二","f":"七言绝句","c":["静对苍山阅岁华，人间何地著生涯。","翻书忽到无言处，陋巷春风自一家。"]},{"t":"题常州卞六行乐图","f":"七言绝句","c":["素紽衣摺皂纶巾，不受长安马足尘。","香绕鹿车秋未老，胜游知是惜花人。"]},{"t":"苦雨漫兴 其一","f":"七言绝句","c":["久病朝籍未通名，雨窗且得卧天明。","御街石路光凌乱，坐想诸公把滑行。"]},{"t":"苦雨漫兴 其二","f":"七言绝句","c":["青裾白面扫晴妇，冯仗精灵格上穹。","黑云西行雨脚退，针线女儿争奏功。"]},{"t":"坦庵为邓州训导胡直赋","f":"七言绝句","c":["随分安居结数楹，出门何处不堪行。","知君已得羲经趣，眼见高门棘刺生。"]},{"t":"泮邻书屋为会稽处士赋","f":"五言古诗","c":["墦间事埋筑，贾肆竞刀锥。","择居苟失所，媚学将从谁。","所以孟贤母，三徙泮宫涯。","千载有杨翁，衡门久栖迟。","诵法子车氏，有家学东陲。","杏坛藉馀荫，芹沼分清漪。","缅怀邹鲁风，礼庭时一窥。","归来课诸子，肃容坐皋比。","日夕弦诵声，互答相吾伊。","居然二雏者，成名皆在兹。","科第固云好，德性能自持。","坐令环堵宫，永作藏修基。","斯人去已远，家训凛不衰。","芳邻接孟氏，此语非夸毗。","我歌泮邻词，秋风有馀思。"]},{"t":"题鲍栗之通判所藏四景牛 其一","f":"五言律诗","c":["远桃舒浅红，独柳荫馀绿。","乌犍何从来，骈首度川曲。","春波浩沄沄，好雨夜初足。","怜此耕力疲，田翁能羁束。"]},{"t":"题鲍栗之通判所藏四景牛 其二","f":"楚辞体","c":["山檞叶如斗，负此大石傍。","牸兮喘何急，徙倚南风凉。","子牛卧弗起，似恋青草长。","安得伴樵牧，留连至斜阳。"]},{"t":"题鲍栗之通判所藏四景牛 其三","f":"五言律诗","c":["农事早登场，散牧清溪浒。","迎风或长鸣，已忘力田苦。","出门认红树，对岸饶青莽。","日晚欲收栏，横吹隔深坞。"]},{"t":"题鲍栗之通判所藏四景牛 其四","f":"五言律诗","c":["晏岁风霜多，朔气动墟落。","畏寒老觳觫，引犊屡前却。","霭霭向阳坡，梅花点放萼。","养力待春来，郊原事东作。"]},{"t":"次韵萧文明给事元日早朝之作","f":"七言律诗","c":["綵鞭声里曙鸦稀，剑佩森森拱太微。","日射御床明绣衮，云回銮辂见青旂。","鸿胪立仗传三唱，马监随班鞚六飞。","曾记昔年叨侍从，起居长许近皇闱。"]},{"t":"陪祀南郊借尹先生往岁扈从看牲韵","f":"七言律诗","c":["紫坛中夜肃无声，玉趾亲来荐璧声。","华盖云垂如肸蚃，行宫尘远自屏营。","九韶迭应钧天奏，万烛高联复道明。","陪位礼成因北望，帝星当宁泰阶平。"]},{"t":"次韵李宾之侍讲庆成宴上作","f":"七言律诗","c":["门宴分行首从官，内前随例奉宸欢。","衣联锦兽晴偏见，漏咽铜龙午未乾。","羽戚两阶成化久，风云千载际时难。","桂坊敢负平生操，汉策分明戒史丹。"]},{"t":"上元日承邵文敬主事请游神乐观次韵二首 其一","f":"古风","c":["南郭春风引瘦骢，上清元不受尘蒙。","鹤因看院留当户，鹅为求书畜满笼。","赌令欢呼?一醉，弹棋消遣任谁工。","兴酣颇爱青天曲，隔坐还思唤舞童。"]},{"t":"上元日承邵文敬主事请游神乐观次韵二首 其二","f":"七言律诗","c":["曲廊深处绾吟骢，招致群仙我亦蒙。","院静不闻清籁发，坛高时有翠云笼。","一春宦海乘多暇，何处灯山说最工。","更欲早归寻旧赏，夕城高树远重重。"]},{"t":"剪灯歌元夕同年傅商佐主事家席上作","f":"七言古诗","c":["上元灯火如繁星，九衢斗靡流晶荧。","就中一椀最清绝，炯然独照郎官厅。","都城好事争来看，苦心每为良工叹。","并刀剪碎藤溪方，直缕横丝眼中乱。","海市楼台初隐霞，渚宫人物纷如麻。","天孙夜开机上锦，魔女晓散空中花。","态真意远不可了，此艺从知古来少。","颇闻令爱手能续，何得兄家擅天巧。","寒窗有女方十龄，欲遣从之愁未胜。","小弟长惭负奇赏，先请为兄歌剪灯。"]},{"t":"琴月斋为姑苏顾君赋","f":"五言古诗","c":["子夜群动息，虚斋敞前楹。","美人耿不寐，起弄朱丝绳。","肃肃天宇高，璧月流晶荧。","霓裳非雅歌，丛桂多古声。","幽怀浩然泻，纷纷竟何营。"]},{"t":"耕读为建昌士人赋","f":"五言古诗","c":["古来业诗书，守分乐田野。","缅怀有莘人，感激千载下。","耕读者谁子，若与世情寡。","朝出向陇头，一卷书在把。","莫归声吾伊，隐映枌榆社。","汉庭日选士，孰是力田者。","愿见书有年，豳风续周雅。"]},{"t":"送陆克深员外知叙州府","f":"五言古诗","c":["翰苑曾通籍，祠曹久缀班。","片符分虎重，双毂映朱殷。","具服朝辞陛，严装夜出关。","亲交开祖道，远役壮离颜。","蜀岭烟岚匝，泸江雪浪顽。","传餐迎驿吏，挝鼓拜溪蛮。","棨戟通公廨，茶盐拥市阛。","升堂延俊造，入境问痌瘝。","僻县经过少，高斋案牍閒。","奉宸瞻北斗，怀土梦东山。","宦海嗟行往，诗邮足往还。","来朝应可冀，弱柳未须攀。"]},{"t":"次韵倪舜咨侍读省亲南归留别二首 其一","f":"七言律诗","c":["晓日河梁又送归，画樯天杪见巍巍。","赐金喜尔重供膳，密线惭予屡换衣。","南浦一番春草茁，西山随处暮云飞。","灯前久办宁亲疏，不向同人惜暂违。"]},{"t":"次韵倪舜咨侍读省亲南归留别二首 其二","f":"七言律诗","c":["柳梢春色未全胜，别路危阑一共凭。","交味似倾醽醁盏，离肠难断辘轳绳。","名高讲席恩偏荷，喜溢亲庭寿屡称。","忠孝想君心力健，遄归应不待河冰。"]},{"t":"次韵罗明仲洗马新春翻阅经史之作 其一","f":"七言律诗","c":["是非千载若为评，出处当知不异情。","仇薛未堪兴礼乐，管商何得擅功名。","饮馀安乐春风暖，梦觉空同夜气清。","此境与君能一到，人生方不愧轩缨。"]},{"t":"次韵罗明仲洗马新春翻阅经史之作 其二","f":"七言律诗","c":["郢调谁云客和稀，孔坛风景尚霏微。","颜渊岂为贫方乐，蘧瑗能于老觉非。","近代情词多逸响，古来心学有馀辉。","太平儒效收公手，浅薄终惭负衮衣。"]},{"t":"会昌雪亭公子许雨中移竹诗以讯之","f":"七言绝句","c":["八尺庭除半绿苔，一春无意买花栽。","几时凭仗连朝雨，分得青鸾数尾来。"]},{"t":"春雨应制","f":"五言古诗","c":["密云起东郊，霭霭覆高阁。","条风一流转，好雨应时落。","冥濛浥街尘，顷刻满城郭。","坐见西北山，千里翠如瀹。","粼粼玉池水，㶁㶁声赴壑。","微虹隐木杪，生意动花萼。","田家方播种，喜气欲腾跃。","行看土膏润，不畏沟塍涸。","龙德普所施，预想秋大穫。","仰首谢玄功，对物有馀乐。"]},{"t":"张公子行一首送太仓张汉南归","f":"古风","c":["张公子，留侯孙，少年丰采如香荪。","读书击剑穷朝昏，海边甲第开辕门。","堂上将军不好武，千里歌吹闻兵屯。","平生陆家亲昆弟，托好愿比朱陈村。","有女近出职方氏，辇金舆币来求婚。","职方择婿正复尔，椷书许聘情何惇。","张公子，佩赤璊，刻丝裤褶悬两弴。","去年跨马入京国，一见笑语回春温。","画堂红烛谢家庆，整日开燕刲羊豚。","新郎二月发归思，行李赍送联征䑳。","闸河雨过沙水浑，旭日半下东城根。","柳枝未堪把，劝子白堕尊。","人生岁月惊涛奔，他时富贵岂足论。","冰玉相辉古难得，忠孝莫负君父恩。"]},{"t":"送云南府学司训高宗礼 其一","f":"七言绝句","c":["昆明池水隔天涯，万里西行喜过家。","莫叹青毡清似水，文风今日似中华。"]},{"t":"送云南府学司训高宗礼 其二","f":"七言绝句","c":["行人无奈歇征骖，尽与朝绅接笑谈。","他日重逢知未老，内庭供奉亦何惭。"]},{"t":"送云南府学司训高宗礼 其三","f":"七言绝句","c":["烦写新容出镜台，少年衰陋本中材。","远人若问程宫讲，应诧君曾识面来。"]},{"t":"送乡人吴之宽南归","f":"五言古诗","c":["暑月终南讹，灵风动西颢。","季子江上来，言旋亦何早。","今年霖雨剩，九陌积行潦。","怜君千里外，净若水中藻。","坐与亲朋俱，客舍静逾好。","妙指高山曲，细字浮溪稿。","有时扣我门，谭吐亦倾倒。","依依乡土情，忍别萦怀抱。","开舟潞河浒，策蹇长安道。","因君重回顾，家山有遗老。","窃禄十载馀，主恩空浩浩。","何时许归觐，看穫江南稻。","练溪拖晴雪，屏山对苍昊。","阶庭倘休暇，相期共幽讨。","把手各西东，停云下琼岛。"]},{"t":"送萧文明给事持节册封唐府得承字","f":"五言古诗","c":["藩封遵旧制，天语重亲承。","玉节龙垂綍，朱函凤结縢。","使镳联绂弁，行李却金缯。","翰墨心偏健，舟车力更胜。","王孙加礼貌，官吏足声称。","永日花明驿，南薰麦荫塍。","观风临淯水，怀古望舂陵。","封事思晨入，严程戒夙兴。","萦还应几月，青琐候良朋。"]},{"t":"陪祀西陵昌平晓行","f":"七言绝句","c":["雨净关河不受尘，一时吟眺薄秋旻。","树头黄屋如看画，马首青山欲近人。"]},{"t":"道中偶成","f":"古风","c":["望望西陵近，松阴石径分。","倚阑?涧水，下马读碑文。","寝树舍秋吹，桥山出暮云。","野人怀帝力，歌颂道中闻。"]},{"t":"夜半出山","f":"五言律诗","c":["蒇事下西陵，归鞍趁月行。","松林人影乱，石罅水声清。","不觉山程远，推便野望平。","临风歌一曲，秋思满空明。"]},{"t":"题李太史世贤梅花图集古","f":"古风","c":["四山多风溪水急，陇上何人夜吹笛。","几家春梦未知回，起傍寒梅访消息。","宛然姑射子，潇洒在风尘。","北人初未识，疑是弄珠人。","西湖处士骨应稿，洗雨梳风为谁好。","呼儿觅纸一题诗，相对真成被花恼。"]},{"t":"克宽弟南归小诗二首奉简淮阴驿丞林文秀内兄休宁上舍汪汝温亲契 其一 简林","f":"七言绝句","c":["旧榻凝尘岁屡更，秋风一雁又南征。","弟兄离合情无限，万里淮天共月明。"]},{"t":"克宽弟南归小诗二首奉简淮阴驿丞林文秀内兄休宁上舍汪汝温亲契 其二 简汪","f":"七言绝句","c":["南望家山有所思，十年谁共菊花卮。","不堪远雁传书处，又是重阳送别时。"]},{"t":"题便面小景","f":"五言绝句","c":["相看是何境，鹤啄松根苔。","道人一挥袖，天末海风来。"]},{"t":"谷庵为吴医沈公美赋","f":"五言古诗","c":["沈翁隐侯裔，素医而好儒。","有方不自秘，云是溯洄书。","绕庵播嘉种，岁岁勤菑畬。","平生活人手，荏苒七十馀。","种谷如种药，心与造化俱。","岂徒一身饱，固欲周乡闾。","时今菜色者，一半回敷腴。","永怀居药翁，慨彼肉食徒。","安得味斯语，仁寿跻寰区。"]},{"t":"蒙岩为常州邵士忠处士赋","f":"五言古诗","c":["苍岩何巍巍，壁立倚晴汉。","中有一泓泉，淅沥下岩半。","绿萝水帘泻，触石星珠散。","纡回坐成池，隐隐白虹粲。","岩栖者谁子，跬步得幽观。","徬徨此水侧，日夕味爻彖。","烱然生道心，旧染如濯盥。","不学蒙园叟，偶尔事空玩。","养正思古人，因之重三叹。"]},{"t":"题尹性之御史所藏周文靖竹","f":"五言古诗","c":["周郎识此君，落笔琅玕长。","居然步湘皋，翠袖忽两两。","相将舞回鸾，势欲凌波往。","平泉与危石，转折助清响。","坐令俗耳净，远觉烦襟爽。","亭亭吉甫孙，霜台绝尘鞅。","晏岁凛相盟，虚心惬终赏。"]},{"t":"送王司训之任丰县","f":"七言律诗","c":["父兄留得旧毡青，子弟终能守一经。","博士随班承宠渥，诸生开馆候仪型。","到时俎豆陈宣庙，去路河山拥汉亭。","想共令君谈政教，化行歌颂几时听。"]},{"t":"张汝弼驾部求椿庭诗寿其兄","f":"七言律诗","c":["贻谋能是守株人，东海家家说异椿。","壁上古阴回夕照，庭中新干薄秋旻。","衣冠几叶能诗礼，堂构当时亦奂轮。","张仲平生知孝友，连枝应愿八千春。"]},{"t":"分得元君丹臼为安城李珍赋","f":"七言律诗","c":["石臼深深长绿芸，土人犹说魏元君。","金银气逼清宵见，鸡犬声疑白昼闻。","九转谁磨新岁月，六丁长护旧烟云。","盘中李愿幽栖近，日读黄庭几卷文。"]},{"t":"送汪希颜佥事改仕湖广 其一","f":"五言律诗","c":["昭代重提刑，移官及壮龄。","楚人知约法，汉吏本通经。","入境多供帐，分司独坐厅。","洗冤公素志，民颂几时听。"]},{"t":"送汪希颜佥事改仕湖广 其二","f":"五言律诗","c":["楚楚越公孙，江南旧业存。","凌秋趍宪府，戒晓出京门。","关道喧人语，河桥落涨痕。","临岐珍重意，公恕答君恩。"]},{"t":"送张汝弼驾部知南安","f":"五言古诗","c":["吾友人中龙，落落张东海。","起家兵曹郎，回翔十馀载。","朅分五马符，袍带荷恩改。","迢递南安城，横浦一川汇。","知君足儒吏，举笔见丰采。","想当行县时，江天冻云叆。","百丈大庾山，梅花灿珠蕾。","折寄与诗来，都人正延待。"]},{"t":"三乐为晋陵胡叔虞赋","f":"五言古诗","c":["落落妫公孙，远有叔虞子。","处世宁无才，平居不干仕。","一觞与一咏，顾我方乐只。","此身非草木，有生胡弗喜。","而况得为男，已历好年纪。","兴来鼓三终，所得亦云侈。","茫茫天地间，岂不解同是。","永日行畏途，沈酣未知止。","千载鹿裘翁，见取尼山氏。","长歌念伊人，迢遥隔州里。"]},{"t":"题黄帝广成子问道图","f":"五言古诗","c":["忆昔广成子，讲道崆峒山。","抗颜为帝师，相与炼九还。","坐令千岁人，绿发而朱颜。","一朝乘龙去，下顾悲尘寰。","药垆莽犹存，逸驾不可扳。","兹事传已久，无乃空投难。","灵均赋远游，魂销汨罗湾。","邹欣注参同，寂寞蓬莱班。","我读古仙经，一一廋且悭。","或恐妙契者，不在文词间。","灵洞何幽幽，鼎湖亦潺潺。","胜境虽足爱，赋予诚疏顽。"]},{"t":"尼山高一首寿阙里孔公伯处士","f":"古风","c":["尼山高，高嶙峋，千年孕此大圣人。","圣人一去圣泽新，云礽玉树何振振。","公伯先生号贤者，韦布不沾京洛尘。","生时分值祖庭桧，荏苒于今六十春，苍髯势欲凌秋旻。","朔风吹地才一日，先生笑坐开芳辰。","戏綵儿孙行绕身，携壶陆续来亲宾。","崧高一纸驰献寿，知有内翰联佳姻。","新诗在眼酒入唇，先生陶然岸乌巾。","家山乔木色不改，百岁愿作无怀民。"]},{"t":"琴鹤东人为广人何式之赋","f":"古风","c":["小揽山中盛丘壑，朅有幽人恣行乐。","坐间时弄七弦琴，到处还随九皋鹤。","春波澹荡风日清，耳畔忽闻环佩声。","古人虽往古音在，坐使一川鱼鸟惊。","石径盘回绝尘侣，砂顶昂藏缟衣举。","幽人鼓掌一和之，万里閒云自容与。","君不见蜀川太守报政成，一鹤一琴随马行。","又不见义山诗人杀风景，煮鹤烧琴对佳境。","幽人不求禄二千，幽人不赋西昆篇。","祇与双清作东道，见者一任称何仙。","燕歌赵舞人争爱，毕竟谁宾复谁介。","何如琴鹤共平生，清誉长传岭南界。"]},{"t":"归田乐卷为彭彦充仪制赋 其一","f":"五言律诗","c":["拂衣何太早，人惜汉彭郎。","许国身犹健，还山乐自长。","分泉栽杞菊，升垄看牛羊。","莫和陶翁句，长歌与世忘。"]},{"t":"归田乐卷为彭彦充仪制赋 其二","f":"五言律诗","c":["苍雪难侵鬓，红尘自息劳。","高眠穿北牖，舒啸入东皋。","久办青山屐，初尝白社醪。","海鸥机事少，应识旧仪曹。"]},{"t":"春坊斋夜追忆旧时在翰林东署与诸君子喜雪焚香联句之作奉简亨甫鼎仪世贤三太史","f":"五言律诗","c":["斋榻游尘净，宫城刻漏残。","不知芸阁梦，何似桂坊寒。","旅夕垆香在，经春雪意难。","同袍应念及，灯火旧诗坛。"]},{"t":"藻轩为锦衣千户吴孟章赋","f":"七言律诗","c":["将军心地清如藻，小结幽居远六街。","倚榻高寒疑近水，闭门空翠欲侵阶。","撷芳曾过黄泥坂，寄傲难同画舫斋。","圣代只今需补衮，知君才副九重怀。"]},{"t":"送延都运六十致仕得何字","f":"七言律诗","c":["金带朱衣拜宠多，乞身宁待鬓双皤。","民思久系棠阴茇，国计新饶海上鹾。","白社预钞栽菊谱，沧浪随唱濯缨歌。","不知勇退青云士，屈指如公得几何。"]},{"t":"挽胡孺人","f":"七言律诗","c":["鬓丝初觉早霜凌，岂意年来不自胜。","蓬壁尚疑闻夜杼，蕙帷那复候晨兴。","推恩子望新鸾诰，偕老人伤旧雁缯。","寂寞祁阊山下路，一邱松柏锁寒藤。"]},{"t":"小儿弥月承罗洗马饷鹤歌以答之","f":"七言古诗","c":["仙禽一夕乘风至，清气朝来满庭次。","见客驯然了不惊，学舞时时鼓双翅。","丹砂入顶色犹浅，一声更有凌云思。","我家生男一月馀，每遇高人出相示。","皆云骨相如长郎，坐上啼声已堪试。","犀钱玉果竞相投，随俗惟应悦姬侍。","司经大夫公远后，辍自润笔来相贽。","谓此鹤龄千岁长，眼中定欲徵君嗣。","大夫久作瀛洲仙，许我平生可同志。","顶砂疑是鹤前身，令器而今已三四。","松阴永日相和鸣，螽羽开祥岂无自。","乃知此鹤最宜人，茅君本号还丹使。","山鸡野鹜竟何有，大笼满贮长安肆。","中年不顾縻好爵，看鹤生孙乃吾事。","两郎他日弄雏成，再拜还酬大夫赐。"]},{"t":"奉诏储材卷送翰长王谢二先生","f":"七言律诗","c":["馆阁储材自祖宗，两公承诏任陶镕。","南朝世谱衣冠盛，西掖官联雨露浓。","瑞应奎光开五夜，功期文史足三冬。","不知此夜门墙下，多少英贤赋九重。"]},{"t":"兰竹图题赠萧给事文册乃郎赴秋试","f":"五言律诗","c":["湘皋春婉娩，居然见双清。","幽香下覆之，翠条仰而承。","高石既磊磈，新泉亦泓澄。","临风况君子，去住有馀情。"]},{"t":"送李士钦尚宝持节册封楚府次沈廷美韵","f":"七言律诗","c":["晓承天语下丹霄，周室班封四牡劳。","同姓地分南岳重，殊方人仰北辰高。","朝廷近侍传司玺，江汉风流拥使旄。","预想过家归路便，朱门乔木映宫袍。"]},{"t":"送王昱知荣县","f":"七言律诗","c":["几载儒衫困一经，除书新捧下彤庭。","远趋蜀道三千里，上应郎官十五星。","黉舍秋风兴士子，畬田春雨劝租丁。","政成他日蒙推荐，尚及才人两鬓青。"]},{"t":"送董子仁给事出使琉球","f":"七言律诗","c":["万里乘槎羡董生，手持龙节气峥嵘。","远凭主上班恩到，坐使陪臣谢礼成。","番贸不收沙上市，粤船长下水边城。","知君可副中朝望，一寸心随汉月明。"]},{"t":"清明谒西陵饭昌平刘奉祠家次韵李世贤太史","f":"七言律诗","c":["何处同君寄一餐，昌平县里旧祠官。","停骖已忘征途倦，抚景惟惭得句难。","百辟分班朝太寝，五云回首认长安。","行人尽说清明近，不似常年节气寒。"]},{"t":"二十五日朝陵次世贤太史","f":"七言律诗","c":["二圣仙陵隔路岐，松林灯火夜差池。","中天绛阙长相峙，夹道苍山晚更奇。","地迥易看星次转，天寒不觉露华滋。","一年一度陪鸳侣，清庙无才续旧诗。"]},{"t":"谒陵游九龙池八首 其一 渡石涧","f":"五言绝句","c":["驱马渡南涧，涧水清且驶。","蹀躞未肯前，磊磊青石子。"]},{"t":"谒陵游九龙池八首 其二 问山下路","f":"五言绝句","c":["寻源怅何之，渺渺入荒野。","裴回灌莽中，偶尔遇樵者。"]},{"t":"谒陵游九龙池八首 其三 谷口闻鸡声","f":"五言绝句","c":["隐隐谷穷处，鸡犬如隔尘。","下窥见墙屋，知是五陵人。"]},{"t":"谒陵游九龙池八首 其四 石田分浸","f":"五言绝句","c":["石田如画局，山溜细通塍。","点点凫鹥白，亭亭蒲稗青。"]},{"t":"谒陵游九龙池八首 其五 九龙池","f":"五言绝句","c":["山脉贯龙腹，山髓出龙口。","九道下成池，千年溉灵囿。"]},{"t":"谒陵游九龙池八首 其六 石壁","f":"五言绝句","c":["池东立石壁，巉削不可扪。","颇疑天所造，鬼斧尚留痕。"]},{"t":"谒陵游九龙池八首 其七 池上峰","f":"五言绝句","c":["苍然百丈峰，峙此一池侧。","遂令活水源，长含太古色。"]},{"t":"谒陵游九龙池八首 其八 饮龙口泉","f":"古风","c":["?此沆?汁，清我尘土心。","临流不能去，山风振衣襟。"]},{"t":"成化戊戌四月十一日储皇御左春坊敏政进讲大学首章退宴文华门十二日上御经筵敏政进讲中庸第二十章退宴左顺门感愧之馀赋此呈同事诸君子","f":"七言律诗","c":["小臣踪迹本疏慵，衮职情知不易供。","才向储闱传大学，又从宣室讲中庸。","朝行辅德须耆俊，家法崇文自祖宗。","尚食屡饕无寸补，百年兴运愧亲逢。"]},{"t":"六月二十八日大雨赴斋所","f":"七言律诗","c":["黑云连阵雨声寒，骑马萧萧向掖垣。","平地急惊成海子，御沟全似泻河源。","担夫没屩犹探路，从吏篝灯不到门。","小坐未眠闻屋漏，旋移斋榻过前轩。"]},{"t":"二十九日夜晴太庙陪祀作时王惟臣詹事刘希贤汪伯谐二庶子郑瑶夫罗明仲洗马俱以疾在告","f":"七言律诗","c":["连朝阴雨一宵晴，百辟相欢仰孝诚。","鹤驭自天来九庙，衮衣成礼及三更。","迎銮乐向门前奏，扈跸人从树里行。","储辅近来多病渴，叨陪独幸夜通名。"]},{"t":"七月十七夜病起露坐偶成","f":"七言律诗","c":["古樗摇影屋西山，独坐空阶月上关。","远杵数声秋律应，明星一点曙更閒。","道心尽可消官况，酒力微堪慰病颜。","千里故园归未得，不禁征雁溯风还。"]},{"t":"送程医官诗","f":"五言古诗","c":["当年傅韩王，文行推尔祖。","近来佐雄藩，老成羡而父。","之子当妙龄，不与众郎伍。","匪徒趍礼庭，更喜游药圃。","时出应人求，床箦多告愈。","一朝被抡荐，千里来自府。","公试迥出群，官名入铨部。","青囊一编书，居然袭簪组。","伏阙谢主恩，奉檄返乡土。","谓我亦宗丈，朝来扣蓬户。","自云将启行，舣棹向河浦。","省亲方就禄，征途不为苦。","程本大族家，南北旧通谱。","恭惟两大贤，家在鸣皋浒。","寝堂闻渐衰，眼底剩榛莽。","而翁朅行县，时能作祠主。","慷慨鸠众工，彷徨走丞簿。","轮奂一回新，燕贺响钟鼓。","颇欲得予铭，盛事传永古。","子行道祠下，再拜奠觞脯。","油然慈孝心，冥冥祝多祜。","从来活人手，亦足踵前武。","都门开祖筵，薰风霁新雨。","视子真可人，濯濯好眉宇。","勉哉亢其宗，谨勿失绳矩。","饯行赋长诗，为子一挥麈。"]},{"t":"送陆处士还太仓","f":"五言古诗","c":["老人住海上，高隐不出门。","一朝念游子，乃驾北来辕。","南风吹尘净，忽忽止行轩。","游子迎再拜，喜极不可言。","是时子方贵，执经奉储垣。","朝回寡人事，退食多公餐。","老人乐兹养，心志静不烦。","秋气澹欲来，中宵梦丘樊。","呼儿整归棹，回波浩澶澶。","逸驾既莫扳，为寿奉酒尊。","颇闻老人语，去住非所论。","愿儿崇正学，不愧宣公孙。","到家应几时，及此芳桂繁。","望望渔樵侣，悠悠水云村。","岂独相劳苦，而不知本原。","古来慈孝心，坐使薄俗敦。","我歌送执事，典型谅斯存。"]},{"t":"挽董尚矩编修父母 其一","f":"五言律诗","c":["董氏宁都盛，夫君说最良。","忽捐招隐操，空贮活人方。","断简藏家塾，残碑立墓场。","由来天报德，貤赠托名郎。"]},{"t":"挽董尚矩编修父母 其二","f":"五言律诗","c":["提携双稚子，孤月几回秋。","綵服时经眼，珠冠老上头。","院松终抱节，庭草讵忘忧。","太史应裁传，千年重女流。"]},{"t":"追和江东之学士留寓南京上新河徐氏园亭之作 其一","f":"五言律诗","c":["留寓得林坰，浑疑宿幔亭。","禽声翻角徵，山色中丹青。","雨竹驱尘净，风花又梦馨。","主人能解事，终夕候文星。"]},{"t":"追和江东之学士留寓南京上新河徐氏园亭之作 其二","f":"五言律诗","c":["借住新河口，双扉逐岸垠。","水花堪索笑，山果得尝新。","暂谢催诗吏，时迎载酒人。","乘凉多竹树，随意脱簪绅。"]},{"t":"追和江东之学士留寓南京上新河徐氏园亭之作 其三","f":"五言律诗","c":["明月几回团，幽居体自宽。","绿醅时解困，白苧晚生寒。","唤客弹棋子，看人把钓竿。","年来通禁籍，回首忆清欢。"]},{"t":"送祁门周仲实赴赵州学正","f":"七言古诗","c":["南风捲地吹沙尘，落日东城辞故人。","来趋礼闱黄卷苦，去主州学铜章新。","君家江南任河北，浩气棱棱面腴色。","登车不畏征途难，问宿何须路人识。","赵州古多才杰士，慷慨遗风尚何似。","春秋书法可与言，即此上报明天子。","劝君卮酒赠君歌，亨衢白日青云多。","苏湖遗教尚可复，功名老大非蹉跎。"]},{"t":"送张太史养正升都宪巡抚宣府","f":"七言古诗","c":["北边重镇称宣府，一带关河新蕃宇。","镇朔长屯大将兵，节制还应属巡抚。","眼中之人今几年，受诏临戎已三五。","圣明不喜文法吏，特简儒臣付斯土。","张君堂堂七尺躯，生有奇才济文武。","近侍初联凤阁班，文章久擅鸡林贾。","时从经幄讲唐虞，正色棱棱似文虎。","事功直欲追前贤，蜾蠃雕虫底须数。","人言国士可无双，书剑相传自其祖。","一朝果被九重知，冠豸腰金佩长组。","想当跨马出行边，先事澄清后戎伍。","千仓有蓄问陈红，百里相望看楼橹。","守臣戍帅总郊迎，帓首联翩负前弩。","蒐田尚接金莲川，弦诵遥连赤城坞。","威声早已罢烽燧，号令谁能易旗鼓。","丈夫此行亦快哉，好在边人悉安堵。","愧予与君最相得，半生不脱儒生腐。","置身岂合在公卿，开口徒能论今古。","喜君大用夜忘寐，恨不狂歌对鸡舞。","平明载酒送君行，祖席薰风动南浦。","愿君当此得志秋，莫学人嗟守边苦。","幕府重期老范谣，家声再续留侯谱。","功成复入汉庭来，帝衮终须待君补。"]},{"t":"追和江翰长先生上新河徐氏园亭病寓之作","f":"七言律诗","c":["徐家亭子楚江东，蜀客来寻一径通。","坐下清泉消溽暑，门前乔木倚晴穹。","尽多醉兴归诗里，那复閒愁著病中。","更是可人翘首处，钟山如画绕皇宫。"]},{"t":"送何惟一御史赴云南按察副使","f":"七言律诗","c":["才骑骢马隔春回，又领除书远赴台。","万里王程劳跋涉，十年交谊重裴徊。","即看宪府威声起，曾是词林教养来。","后会有期君正健，不将离恨荐离杯。"]},{"t":"会缌庵和谢鸣治侍讲乃叔宝庆太守君寄来韵","f":"七言律诗","c":["半山乔木护空庵，奠扫来频尚有岚。","诸谢家风今浙左，老苏亭子旧川南。","已应宗法千年立，何止亲情五世覃。","考室诗成想贤守，几回歌罢又开缄。"]},{"t":"题碧桃便面","f":"五言绝句","c":["省识霜春面，何因出镜中。","暗春吹不断，掌上舞回风。"]},{"t":"题张养正都宪小画","f":"五言绝句","c":["柳岸频收网，鱼租句纳官。","晚来风浪急，却在把篙难。"]},{"t":"送户部赵祥主事奉使便道省其大母","f":"五言律诗","c":["重闱春最永，手教一孙成。","故里王程便，新图寿域明。","家人占鹊喜，堂客羡乌情。","会取官绫诰，驰封到祖名。"]},{"t":"戊戌清明谒陵宿斋所次韵江翰长","f":"五言律诗","c":["两日向山行，春深野望明。","寝园同驻马，陵树不闻莺。","寒食惊时过，清斋候礼成。","归途应便好，星斗夜纵横。"]},{"t":"归途次韵","f":"五言律诗","c":["谒陵归尚早，行李向来轻。","北阙看将近，东方启渐明。","群鸦惊客散，一马溯风鸣。","袅袅垂杨外，新烟动夹城。"]},{"t":"送郑洗马赴南京太常少卿","f":"七言律诗","c":["法从年来屡奏功，此行争说荐书公。","旧都南北舟车便，原庙春秋俎豆同。","喜奉慈颜开寿域，却劳清梦绕储宫。","重来未觉霜毛盛，看续西京白虎通。"]},{"t":"早秋游城南宗家园亭次韵周伯常中允二首 其一","f":"七言律诗","c":["宗老当时喜种花，至今池馆压堤沙。","苍颜一去成尘土，白日重来感岁华。","多谢诸公同驻马，却怜犹子解持家。","高城暮鼓催归急，不得临风奠一瓜。"]},{"t":"早秋游城南宗家园亭次韵周伯常中允二首 其二","f":"七言律诗","c":["愔愔残暑逗轻纱，马入南园识旧家。","邻酿旋分燕市酒，土宜时供歙州茶。","田苗有雨秋初熟，林影无风昼不哗。","我已分为东道主，请君随赏四时花。"]},{"t":"送王廷贵祭酒先生考绩还南京","f":"五言古诗","c":["高皇定都日，首事在国庠。","青衿变左衽，木主开中堂。","启运今百载，弦诵声逾长。","先生晋陵彦，手握司成章。","抗颜曾几何，述职来帝傍。","馆阁多故人，鬓发惊苍浪。","平生相慰藉，讲下无留良。","承恩复南辕，顿首辞明光。","望望鸡鸣山，奎星夜垂芒。","愿言崇令德，旧辅登岩廊。"]},{"t":"晚香为太仓陆处士作","f":"五言古诗","c":["笃行老不衰，有美陆仲父。","平生得高趣，卓尔在秋圃。","群芳坐销歇，黄花正纷吐。","凛如千岁夫，岁晚节逾苦。","窅窕林亭间，相对傲风雨。","慷慨陶徵君，遗踪未榛莽。","亦有韩相国，功名照千古。","出处虽不同，景行吾所取。","汤汤末流中，谁能立孤柱。","千里闻德馨，相思动吟麈。"]},{"t":"送日者方生还龙游","f":"五言古诗","c":["方生谈禄命，往往不受金。","谓是五行理，岂易钩其深。","我知据所得，稍稍从规箴。","贵贱有天定，中否非所任。","子术诚若斯，子道良足钦。","曲学以阿世，悠悠觉何心。"]},{"t":"题杂画 其一","f":"五言绝句","c":["青山寂无人，空陂澹流水。","垂杨不胜春，摇摇蘸清泚。"]},{"t":"题杂画 其二","f":"五言绝句","c":["凉月满荒原，长空白露繁。","偶来疏柳下，倚杖欲何言。"]},{"t":"题杂画 其三","f":"五言绝句","c":["落木凌秋下，青山对面开。","澄江可消酒，随意放船来。"]},{"t":"题杂画 其四","f":"五言绝句","c":["夜下竹林滩，水平船不动。","倚棹醉眠人，襟怀浩难共。"]},{"t":"挽彭处士夫妇 其一","f":"七言绝句","c":["隐君元是彭仙后，一日凌风去不回。","寂寞王屯坡下路，杖藜谁复听松来。"]},{"t":"挽彭处士夫妇 其二","f":"七言绝句","c":["我爱梅边最不群，每从先达访遗文。","由来国子先生母，却是梅边嫡派分。"]},{"t":"挽彭处士夫妇 其三","f":"七言绝句","c":["择继当时屡问名，邑南唐氏有家声。","平生妇道堪书处，请看彭门七弟兄。"]},{"t":"题梅赠山海萧生赴山东秋试","f":"七言绝句","c":["孤芳自是不凡材，顾影临池首重回。","已报东归消息好，春光随马过关来。"]},{"t":"送陈宏知事 其一","f":"七言绝句","c":["风浪曾惊滟滪堆，怜君新手护高桅。","相逢话旧浑如梦，已过年光二十回。"]},{"t":"送陈宏知事 其二","f":"七言绝句","c":["乌帽西归向我辞，久来忘却赠行诗。","闻君歌罢还惆怅，转觉吟情愧往时。"]},{"t":"送陈宏知事 其三","f":"七言绝句","c":["随牒年来多苦辛，青云此日荷恩新。","南都列卫应相问，知是尚书幕府人。"]},{"t":"詹驾部天泽出知建昌便道省母得五字","f":"五言古诗","c":["采采砀中姬，肃肃詹氏姥。","夫君久违荣，家事独攻苦。","帙登龟算七，儿有凤毛五。","一人迥超群，宦学迈其父。","诰锡盘龙书，名属司马部。","朅分郡守符，绾此建昌组。","仕途与家便，慈容喜先睹。","松阳岁将阑，梅萼纷已吐。","画堂开宿酝，綵服动新舞。","遂哉忠孝心，君恩子何补。"]},{"t":"十月二十七日出都城","f":"七言律诗","c":["供奉金銮十四霜，宁亲恩许暂还乡。","花骢远给从官厩，宝镪分颁出尚方。","行色渐惊残腊到，欢心那说畏途长。","篁墩宅畔寒梅树，定发新花候解装。"]},{"t":"卢沟别诸亲友","f":"七言绝句","c":["夕阳初下古城头，雪浪凝寒沸不流。","多谢同袍旧知己，殷勤相送过卢沟。"]},{"t":"晚次良乡","f":"五言绝句","c":["晚宿良乡馆，离家第一程。","便应今日梦，南北两关情。"]},{"t":"早发","f":"七言律诗","c":["古城衰柳散朝鸦，抚景全忘驿路赊。","山色西来寒泼黛，日光东出暖蒸霞。","远人仆仆行躔费，一处摇摇酒幔斜。","此去前村知己近，耳闻鸡犬隔林哗。"]},{"t":"遇广东守臣进鹦鹉","f":"七言律诗","c":["绿衣朱喙陇山禽，入贡新从广海浔。","辇致已闻经万里，购求何说费千金。","奉宸固表王人敬，却献谁知主上心。","不见韩公嗟二鸟，马头回看一长吟。"]},{"t":"新城公馆夜梦亡弟借邵文敬主事壁上留题韵","f":"七言律诗","c":["弟兄无分过中年，千里云山望眼穿。","地下有时还见汝，人间无路可呼天。","英魂彷佛归何处，此夜分明到我边。","公馆北风吹梦醒，不知衾枕已汍然。"]},{"t":"渡白沟","f":"七言律诗","c":["白沟东下水如襟，不尽行人吊古心。","戍垒风云流断岸，农家烟火半空林。","往来此日通燕粤，兴废千年说宋金。","似有渔郎知此意，棹歌声入水云深。"]},{"t":"雄县城南潦水成湖渡二十馀里","f":"七言律诗","c":["雄县城南初问津，一片湖光青镜匀。","橹声幽轧颇清耳，帆尾招摇如唤人。","江南路景或转徙，冀北征夫多苦辛。","扣舷笑欲问河伯，海水桑田今几春。"]},{"t":"晚行至任邱","f":"七言律诗","c":["风尘猎猎马蹄翻，旋觉残阳下古原。","五里路中三渡水，十家村里九颓垣。","一抔尚指卢医葬，两垒空馀郑市存。","此夜客怀应渐好，计程明日到乡园。"]},{"t":"至河间之明日拜扫先世赐茔","f":"七言律诗","c":["势拥长冈面四岑，千章乔木蔼成林。","幽堂结聚乘生气，天语昭回焕德音。","百世幸培先业厚，一家难报主恩深。","敢将衣锦誇乡里，忠孝相传本夙心。"]},{"t":"发河间出南门拜外祖林处士墓遂至舅家饮别","f":"五言古诗","c":["骑出瀛东门，朔气侵衣裳。","岿然外家冢，枕此官道傍。","下马一顿首，草木寒无光。","去茔数举武，升我舅氏堂。","舅年六十馀，鬓发惊苍浪。","老妗悲且喜，叩我家事详。","贱子再拜言，有亲天一方。","晏岁东南征，岐路多风霜。","忆昔四小甥，玉立森成行。","岂期中道间，少者多沦亡。","人生若电火，展转摧中肠。","矧兹远行役，聚散安可常。","但愿母家好，庆远流弥长。","尽此酒一尊，别泪纷瀼瀼。","去住两凝睇，古木留残阳。"]},{"t":"途中寄别官主事廉","f":"七言律诗","c":["涝水潺潺似海流，岁功那得半分收。","眼看饿殍盈官路，手奉恩纶出帝州。","生意渐回千里望，夙心应慰九重忧。","明年二月还过此，拟有欢声达冕旒。"]},{"t":"献县望河间献王墓","f":"五言古诗","c":["吕嬴播虐燄，天下无典籍。","楚贼嗣其凶，掌故不能匿。","迨彼马上公，儒者犹失职。","更化凡几年，书禁始销熄。","斯文天有意，宗贤起王国。","开府两河间，恭文自天识。","悯兹简册灰，访购靡馀力。","遂令先王书，次第乃有得。","缅怀仁义风，礼乐馀汉策。","高丘献城东，寒日下荆棘。","后生已千载，私淑仰遗德。"]},{"t":"渡滹沱河","f":"五言古诗","c":["寒风挟霜起，冰浪从西来。","下触断桥柱，碎此千琼瑰。","流响甚清冽，惊波屡盘洄。","官舟大如掌，疾棹过南隈。","古来济川人，感激多良材。"]},{"t":"阜城晚遇南京户部张彦质郎中附奏江南旱灾","f":"五言律诗","c":["诏使频年发，皇恩岂不覃。","水方渰冀北，旱复苦江南。","天意嗟何极，民生半不堪。","同袍夜相语，禄食漫怀惭。"]},{"t":"阜城南门过御庄铺乃刘豫始生之地","f":"七言绝句","c":["白草和烟覆矮墙，一间茅屋野茫茫。","居人不唾刘郎僣，犹把亭名号御庄。"]},{"t":"景州望董子祠","f":"七言律诗","c":["先哲巍巍老仲舒，古祠犹枕旧园居。","一时仁义江都相，百世渊源鲁国儒。","稍慰夙心思奠水，仰瞻遗像欲停车。","后生碌碌成何用，翘首风前思有馀。"]},{"t":"书所见十四韵","f":"七言古诗","c":["大水那能望有年，恤民恩诏喜拳拳。","事凭公廪终难济，情到官庄最可怜。","占取膏腴多极万，索来金谷动盈千。","税于子粒偏加重，赋入荒年亦未蠲。","港次半收烟火价，野中分握草场权。","鸡豚已尽田间利，舟楫仍需水面钱。","泛使不禁频去住，小民何日许安便。","伐残桑枣惟馀地，典尽车牛莫诉天。","罪絷便连儿女辈，鞭笞宁计令丞员。","屋庐毁废沦波底，老弱流离委道边。","糠秕无端争入市，酒浆那复敢开廛。","监门有泪挥图上，守土何人达帝前。","愧我身非观察使，伤心聊述纪行篇。"]},{"t":"日出入行","f":"楚辞体","c":["朝看红云出东海，暮看红日沈西山。","西沈东出不自已，行人到此伤心颜。","家居徽歙间，身缀蓬莱班。","南亲闱兮北帝阙，古来忠孝两难尽，此途此去终来还。","仰天戴日歌一曲，不觉清泪流潸潸。"]},{"t":"过永昌桥野老云太宗靖难过桥以旧名晋起不雅特更今名","f":"七言律诗","c":["界石巍巍表县封，永昌桥上午阴浓。","渔郎不复歌前代，野老犹能说太宗。","几里护村堤似玦，大河分派水如龙。","临风不觉徘徊久，极目高唐已暮钟。"]},{"t":"过南镇店二首 其一","f":"古风","c":["阴霭如滋稚麦，野风时振枯桑。","午市方趍南店，早行已届东昌。"]},{"t":"过南镇店二首 其二","f":"古风","c":["林外依依烟火，道中辘辘车声。","废碣犹传蒙古，短亭正及荏平。"]},{"t":"荏平道中","f":"五言绝句","c":["落日荏平道，孤村未掩关。","望中青隐隐，人说是陶山。"]},{"t":"入东平山中古坟以百十数残碑断磉多有年月可识","f":"七言绝句","c":["山过东阿两路分，草中无限昔人坟。","等閒却忘征骖苦，贪看残碑到夕曛。"]},{"t":"东阿王","f":"五言古诗","c":["我爱东阿王，翩翩贵公子。","虽读万卷书，日日弄文史。","已乖弟兄好，更遂君臣理。","盗汉者何人，胡不相谏止。","所以大道行，重义不重死。","凄凉豆箕咏，掩卷吾不齿。","当年开国地，寂寞小山趾。","谅哉朱昱心，千载有馀耻。"]},{"t":"梁颢墓","f":"七言律诗","c":["四十登科五十亡，史书犹载秘书梁。","谁将鹤发欺公道，遂使龙头失故常。","世俗固应多信耳，子孙何得误传芳。","有灵地下还知此，独对泉台笑几场。"]},{"t":"汶上","f":"七言绝句","c":["家家文石甃街渠，尽是频年伐冢馀。","所获自收金玉外，不知曾见殉书无。"]},{"t":"夜次兖州寄安邱王府教授邹钝夫","f":"七言绝句","c":["半生交契说邹阳，年少才名独擅场。","谁意兔园今白首，只将词赋动梁王。"]},{"t":"寄衍圣公","f":"七言律诗","c":["阙里巍巍入望中，后生山仰意何穷。","文光远烛奎星上，圣泽长随泗水东。","崇德已隆昭代礼，象贤当有素王风。","十年滥接葭莩契，寸札殷勤托便鸿。"]},{"t":"兖州东南望孔林居人谓之夫子冢云在九龙山下其山九峰故名","f":"五言绝句","c":["阙里何年到，匆匆一望间。","人言夫子冢，正在九龙山。"]},{"t":"峄山歌","f":"七言古诗","c":["行人朝行峄山下，山色凌寒翠堪把。","秀峰斗绝倚穹霄，复岭蜿蜒走平野。","路傍岩石亦崄巇，上似熊罴下牛马。","征夫为我一一言，数十残碑尚堪打。","不知何代帝王来，驰道犹存古砖瓦。","灵湫一眼透山巅，时有风雷起长夏。","土老能占絮帽云，刻日甘霖应时洒。","于中胜境难具论，洞府多藏石尊斝。","入眼方知造化工，披图始觉丹青假。","蹇予素乏尘中缘，最是平生爱山者。","驱驰未暇一登临，浩荡襟怀向谁泻。","思将短曲慰山灵，安得长才继骚雅。"]},{"t":"邹县城南拜亚圣祠下","f":"七言律诗","c":["万年文运若循环，此道谁堪继孔颜。","但使七篇当世用，便应三代旧风还。","子孙故里题邹国，俎豆严祠对峄山。","下马望尘修敬处，夕阳川上水潺潺。"]},{"t":"憩滕南邮亭","f":"七言绝句","c":["家山疑在望中青，征马萧萧此暂停。","屈指过江南北路，还过百二短长亭。"]},{"t":"九日怨十章 其一","f":"七言绝句","c":["黄花半老清霜后，忆弟看云白昼眠。","妙质不为平世得，悠悠生死别经年。"]},{"t":"九日怨十章 其二","f":"七言绝句","c":["满城风雨近重阳，马上谁家白面郎。","时复看云泪沾臆，寒花犹作去年香。"]},{"t":"九日怨十章 其三","f":"七言绝句","c":["怀抱何时得好开，陶然共醉菊花杯。","一行书寄千行泪，竹死桐枯凤不来。"]},{"t":"九日怨十章 其四","f":"七言绝句","c":["惠连群从总能诗，一夜霜风凋玉芝。","丛菊两开他日泪，欲欢无复似当时。"]},{"t":"九日怨十章 其五","f":"七言绝句","c":["此身那得更无家，节及登高忽叹嗟。","人面不知何处去，一年容易即黄花。"]},{"t":"九日怨十章 其六","f":"七言绝句","c":["南菊再逢人卧病，浮云世事欲如何。","哀歌未断城鸦起，鸿雁不来风雨多。"]},{"t":"九日怨十章 其七","f":"七言绝句","c":["物色生态能几时，九日尊前有所思。","遥知兄弟登高处，此恨绵绵无绝期。"]},{"t":"九日怨十章 其八","f":"七言绝句","c":["爱而不见心断绝，瘦马独吟真可哀。","寄与风光共流转，菊花从此不须开。"]},{"t":"九日怨十章 其九","f":"七言绝句","c":["与君今世为兄弟，未必秋香一夜衰。","古往今来只如此，九重泉路尽交期。"]},{"t":"九日怨十章 其十","f":"七言绝句","c":["遍插茱萸少一人，苍苔白石已成尘。","人生在世长如客，更结来生未了因。"]},{"t":"彭城废县南谒汉高祖庙","f":"七言律诗","c":["古原荒树倚村斜，高庙威灵亦可嗟。","警跸千年馀塑马，铙箫终夕舞神鸦。","砀山落日销云气，睢水寒风捲岸沙。","汉楚兴亡那复问，一龛灯火属僧家。"]},{"t":"徐州望子房山山上有祠","f":"七言律诗","c":["子房祠在望中岑，蔓草寒烟尚可寻。","五世报韩终有恨，一时兴汉本无心。","书传黄石知真假，名配青山自古今。","立马斜阳无限思，天教风壑助豪吟。"]},{"t":"徐州驿舍竹林可爱","f":"七言绝句","c":["徐州驿里萧萧竹，好手应难入画图。","北客南来初见此，不胜清思绕江湖。"]},{"t":"不寐","f":"五言绝句","c":["千载逍遥堂，独卧愁不语。","北风吹竹林，一夜响寒雨。"]},{"t":"徐王坟","f":"七言绝句","c":["兆域巍巍近凤阳，万年坤德此开祥。","当时不是灵源厚，异姓谁封一字王。"]},{"t":"夹沟山中夜行","f":"五言律诗","c":["马渡夹沟东，溪桥卧断虹。","夜阑群动息，月出四山空。","物色归尘外，天形入镜中。","兹游奇绝甚，琢句恨难工。"]},{"t":"同年范嘉龙御史于大店驿相候叙话良久乃别","f":"七言律诗","c":["浮生聚散若飞蓬，驿舍那知此会同。","可是故人非白眼，独劳前路驻青骢。","云回峻岭朝含日，霜入疏林夜战风。","近事匆匆谈不尽，出门车马又西东。"]},{"t":"固镇驿早发集古二首 其一","f":"七言绝句","c":["中夜起坐万感集，有时颠倒著衣裳。","病身最觉风露冷，离思杳如关塞长。"]},{"t":"固镇驿早发集古二首 其二","f":"七言绝句","c":["正睡梦中行十里，东方明星亦不迟。","但见乌帽出复没，马首东来知是谁。"]},{"t":"渡淮次濠梁","f":"七言律诗","c":["万里无风起片云，中流一绿浩沄沄。","源从桐柏山中泻，路自濠梁驿下分。","贾客帆樯依岸宿，皇陵钟磬隔城闻。","逢人欲问观鱼乐，庄子台前又夕曛。"]},{"t":"中都形胜","f":"七言律诗","c":["境当南北建中都，形胜遥应古亦无。","四望河山围太寝，仰知天地肇皇图。","复田万世还过汉，开国元年尚纪吴。","立马临淮城下路，五云回首欲嵩呼。"]},{"t":"凤阳南二十里陟小岭望见环滁诸山","f":"七言绝句","c":["一时飞思薄青冥，水墨图开万里屏。","若个溪山幽绝处，酿泉声绕醉翁亭。"]},{"t":"沙涧铺山行","f":"七言绝句","c":["猎猎寒风吹日黄，山中随处涧声长。","不知早稻皆成草，犹自涓涓下野塘。"]},{"t":"凤阳南行失道误趍定远","f":"五言古诗","c":["自我为近臣，块坐今几春。","出门将何之，引躅随他人。","南行二十日，但喜邮亭匀。","渡淮宿濠梁，亹亹夜问津。","晓入定远山，四顾惊荒榛。","人言此道非，迂远难具陈。","跋马重叹息，寒日吹沙尘。","古来贤达士，岐路多沾巾。","安得指南车，慰此长途身。"]},{"t":"池河驿山行二首 其一","f":"古风","c":["隔宿风销野际，登时日出林端。","牛羊自占坡暖，鹅鸭不知水寒。"]},{"t":"池河驿山行二首 其二","f":"古风","c":["古寺火烧梵塔，空坛水没田塍。","行人时复驻马，野老适来负薪。"]},{"t":"途次偶成","f":"七言绝句","c":["寸寸田塍接涧阿，一丛茅屋枕坡陀。","马蹄已近江南路，渐觉人家水竹多。"]},{"t":"大鎗岭","f":"七言律诗","c":["四顾峰峦剑戟攒，丹梯百折暗中盘。","凝眸叵测东西阔，仰面惟愁上下难。","土著已谙犹足弱，客游虽壮亦心寒。","我来疑是兹山幸，欲写微名石上刊。"]},{"t":"晚过大柳树驿","f":"七言律诗","c":["大鎗岭下马频挥，大柳冈头客渐稀。","烈火燎原虓虎避，疾风惊草雉鸡飞。","山回转觉邮亭远，月下先愁驿路微。","野戍谁家多种竹，旅怀当此更依依。"]},{"t":"月夜渡清流关","f":"七言古诗","c":["壁立万仞清流山，横截万古清流关。","人间险固不可少，老天生此青孱颜。","平生细读五朝史，柴郎亦是奇男子。","斩关缚取二将军，点捡真人入驱使。","我来吊古当穷冬，阴崖草木号天风。","当时战处杳无迹，惟有明月留山中。","圣代车书会同久，此地无劳置官守。","长歌一曲下关来，夜市还沽酿泉酒。"]},{"t":"次滁阳赠州守刘焕","f":"七言绝句","c":["琅琊山下水声长，六一堂前草树荒。","驻马喜逢刘郡守，风流犹解说欧阳。"]},{"t":"早发滁阳戏题","f":"七言绝句","c":["夜到滁阳只困眠，去时才及五更天。","匆匆谕德人应笑，何不来尝庶子泉。"]},{"t":"过家君旧任太仆所居闻当时及门者惟典术魏延一人","f":"七言绝句","c":["行云落日绕乡园，厩马如龙草自蕃。","闻说旧时门下客，萧条惟有魏生存。"]},{"t":"望琅琊诸山不及游典术魏延追及诵吾同年庄孔阳司副四十年来方一到之句不觉笑曰孔阳谢病居江浦去滁不百里而近尚半世一至况碌碌我辈乎马上次韵一首以示延便中寄声孔阳未必不为之抚掌也","f":"七言律诗","c":["林壑分明自一寰，酿泉声出两峰间。","百年纸上看陈迹，寸日忙中负此山。","到处僧为风月主，生来谁似水云閒。","逃名更笑庄周懒，半世方成一往还。"]},{"t":"和州香淋寺浴汤泉","f":"七言律诗","c":["山根流出暖汤汤，暗处斜分到石堂。","千里风尘消半霎，一团和气霭中央。","何年混沌初开窍，此地温柔别是乡。","浴罢不知将夜半，老僧频换佛前香。"]},{"t":"渡江次采石","f":"七言律诗","c":["二十年来尘鞅中，临江喜遇快哉风。","六朝隐隐寒山翠，万里沈沈夕照红。","绝海舟航南北共，兼天波浪古今雄。","拟沽采石矶头酒，浇我平生磊磈胸。"]},{"t":"李白墓","f":"七言律诗","c":["谁见吟魂月里归，临风怀古思依依。","史中出处犹真伪，地下形骸果是非。","采石人家空奠酒，盛唐诗派不传衣。","骑鲸浩气今安在，一片江流荡落晖。"]},{"t":"冬至行庆贺礼于太平府中","f":"七言绝句","c":["一线阳随夜气生，瞻天随例拜江城。","不知此际文华殿，谁导青宫鹤驾行。"]},{"t":"黄池","f":"七言律诗","c":["黄池镇下晓扬舲，扶上肩舆尚见星。","草结鲜红鸦眼粟，竹摇苍翠凤尻翎。","人家愈觉园林密，邮舍初分道里停。","已过江南三百里，乡音入耳渐中听。"]},{"t":"太平山行","f":"七言律诗","c":["江南风土最怡情，临水人家分外清。","轻棹野航如使马，密栽高竹似连城。","好山隔岸开真画，绝涧流泉奏古笙。","北去定应劳梦想，题诗留与白鸥盟。"]},{"t":"敬亭山","f":"五言律诗","c":["青山一万仞，我爱敬亭名。","胜槩一千里，分疆及数城。","不夸游目骋，转觉道心生。","李白题诗在，风流续未成。"]},{"t":"宿宛陵书院","f":"五言古诗","c":["自从删述来，诗道几更变。","骚些无遗声，汉魏起群彦。","谢绝及宋沈，入眼已葱茜。","颓波日东驰，李杜出而殿。","当时多浑成，岂必事精鍊。","云胡倡唐音，趍者若邮传。","坐令诗道衰，花月动相眩。","千载宛陵翁，惟我独歆羡。","翁词最古雅，翁才亦丰赡。","一代吟坛中，张主力不勌。","遂使天地间，留此中兴卷。","如何近代子，落落寡称善。","纷纭较唐宋，甄取失良贱。","无乃久浸淫，曾靡得真见。","渺渺岁将夕，南来宛陵县。","顿首升翁堂，松竹犹眷眷。","感慨抚陈迹，江水一再奠。","我心夙景仰，我学诚袜线。","上想三百篇，斯境复谁荐。"]},{"t":"宁国县道中","f":"七言律诗","c":["宣歙巍巍接县封，忽惊身世得奇逢。","高悬石栈三千丈，四合云峰百万重。","野庙鬼神疑作怪，水田蛇虎动留踪。","人言此去仍多景，自保看山力未慵。"]},{"t":"早发湖乐镇过黄木岭遇佐时及乡人来迎","f":"七言律诗","c":["湖乐镇下更未阑，黄木岭头山火寒。","峰腰霜满一尺径，涧底风生千仞滩。","归心急喜到家好，侧足方知行路难。","前途忽与故人接，相对不觉成悲欢。"]},{"t":"过丛山关入绩溪界巧溪桥","f":"七言绝句","c":["江南江北路迢迢，马上朱颜渐觉凋。","今日故乡初入眼，丛山关下巧溪桥。"]},{"t":"十里岩","f":"七言律诗","c":["不知何代起神雷，凿此双峰压路开。","数点落星浮水次，一湾晴雪洒岩隈。","词人试险身全汗，剑客临风志未灰。","我欲深镵崖石上，改封君作大飞来。"]},{"t":"至家","f":"七言律诗","c":["终日思归今始归，故人乔木尚依依。","庭闱喜极翻成泣，手足情深事已非。","良夜却虚姜氏被，半生长负老莱衣。","愁来便欲求终养，恩诏丁宁未敢违。"]},{"t":"谒先茔于水桥干","f":"七言律诗","c":["松萝山色荡朝晖，先垄依然树一围。","累叶相承支系在，百年今见眇孙归。","坚珉近勒尚书表，故箧犹传相国衣。","我愿宗人勤种德，几家文献重南徽。"]},{"t":"哭亡弟克宽于南山堂僧舍","f":"七言律诗","c":["寸心如折泪如麻，恨杀鸰原日易斜。","黄卷有期承世业，朱颜无分乐年华。","佛前已悟身为幻，梦里长惊目是花。","千里远来多为汝，有灵今夕定还家。"]},{"t":"汪王庙","f":"七言律诗","c":["闻说真人起晋阳，六州图籍便归唐。","干戈竟免群生难，簪笏宜传百世芳。","封诰尚存题越国，史书全失纪吴王。","丛祠香火年年盛，知是英魂恋故乡。"]},{"t":"五显庙","f":"七言律诗","c":["五岭巍巍奠一州，炳灵宁不异长流。","火旗云马分明见，风魃山魈次第收。","满坐遗形如伯仲，当时封爵比公侯。","神功最是难忘处，岁岁居民庆有秋。"]},{"t":"拜先世祖陈将军忠壮公庙于篁墩","f":"七言律诗","c":["僣侯东下势难支，出处如公最有辞。","忍见松楸污贼手，径提戈甲济王师。","两朝勋德收前史，一郡蒸尝奉古祠。","再拜遗容风动幕，凛然犹是起兵时。"]},{"t":"拜先世祖晋新安太守府君墓于双石","f":"七言律诗","c":["南朝遗迹半无闻，我郡犹传刺史君。","当日循良开甲第，至今行旅识荒坟。","百年守令孤芳在，万指儿孙一派分。","不见墓田双石磉，白杨寒雨晚纷纷。"]},{"t":"紫阳书院","f":"七言律诗","c":["千载山堂倚故墟，儿童能识紫阳朱。","乡贤依附襟裾末，县令周旋俎豆馀。","恩典近延徽国谱，奎文犹刻理宗书。","平生学道全无似，九拜趍庭愧小儒。"]},{"t":"拜先世族祖宋丞相文清公元凤祠宇墓于古城关积庆寺","f":"七言律诗","c":["石兽行行草树间，往来人说古城关。","先灵幸托青莲宇，上相曾分玉笋班。","一族再分昭穆序，百年初识祖宗颜。","非才岂足光潜德，负此穹碑勒墓山。"]},{"t":"腊月半后祠堂前并后园梅花盛开敬次家君卷中旧韵二首柬克俭 其一","f":"七言律诗","c":["年来空对写生堂，的见冰容自不常。","疏影似龙清战月，贞心如铁冷欺霜。","秪知菉竹堪为友，转觉凡花不是香。","风味独当充鼎实，肯随脂粉媚含章。"]},{"t":"腊月半后祠堂前并后园梅花盛开敬次家君卷中旧韵二首柬克俭 其二","f":"七言律诗","c":["亭亭玉立晚风前，春意终归雪意先。","后院根如前院好，南枝花比北枝妍。","边城旧曲吹山月，姑射新妆照水天。","明发定应劳梦想，乞将消息往来传。"]},{"t":"先忠烈王遗迹十二咏 其一 射蜃湖","f":"五言律诗","c":["青草湖阴路，神人迹尚留。","雕翎方出彀，蜃气不成楼。","乱石滩声急，连村树色稠。","英魂知不散，时向此中游。"]},{"t":"先忠烈王遗迹十二咏 其二 白石阡","f":"五言律诗","c":["湖上妖氛灭，山前吉兆开。","黄冠离水府，白石定泉台。","墓碣龟仍在，冥仪兽半推。","年年寒食雨，时见远孙来。"]},{"t":"先忠烈王遗迹十二咏 其三 相公木","f":"五言律诗","c":["棚木长千尺，蜿蜒距水涯。","皴皮躔荇带，老色映蘋花。","雷雨春惊蛰，星河夜汎槎。","渔舠莫轻近，神物此为家。"]},{"t":"先忠烈王遗迹十二咏 其四 鼓吹台","f":"五言律诗","c":["壮士昔登台，乡兵取次裁。","鸣鼙催阵起，吹角召军回。","旧事传遗老，荒台没草莱。","至今风雨夕，犹讶战声来。"]},{"t":"先忠烈王遗迹十二咏 其五 铧卜桥","f":"五言律诗","c":["荷锄方出郭，徵诏忽临身。","问吉占田具，祈灵拜水神。","风云曾得意，溪壑自生春。","伫立长桥下，悠悠迹未陈。"]},{"t":"先忠烈王遗迹十二咏 其六 洗马池","f":"五言律诗","c":["山前收战后，洗马向晴波。","髀肉加鞭久，腰痕受箭多。","敌兵愁弃甲，征戍喜投戈。","旧迹无寻处，沙头剩绿莎。"]},{"t":"先忠烈王遗迹十二咏 其七 射的山","f":"五言律诗","c":["空山崖石上，羽镞半留形。","鸟过不敢下，苔封疑有灵。","子孙传野史，守令刻新铭。","亦有南开府，忠勋继汗青。"]},{"t":"先忠烈王遗迹十二咏 其八 歃血台","f":"五言律诗","c":["勤王初受命，仗剑即登坛。","左袒人争奋，中兴事不难。","令岩朱雀帜，盟重白鸡盘。","想像临戎处，荒山草木寒。"]},{"t":"先忠烈王遗迹十二咏 其九 相公湖","f":"五言律诗","c":["将军本龙种，居处化渊中。","变态时常见，真游路不通。","渚宫随烛显，海市向阳空。","不是多遗爱，人争说相公。"]},{"t":"先忠烈王遗迹十二咏 其十 千年木","f":"五言律诗","c":["嘉木何年种，巃嵷护古坟。","蛇皮斜溜雨，龙角上排云。","手植传乡土，神游隔世氛。","子孙今万派，冠佩日纷纷。"]},{"t":"先忠烈王遗迹十二咏 其十一 相公坛","f":"五言律诗","c":["结坛嘉树下，村赛鼓逢逢。","老稚冠裳杂，鸡豚俎豆丰。","灵旗朝送雨，神马夜嘶风。","自是阴功厚，年年配社公。"]},{"t":"先忠烈王遗迹十二咏 其十二 世忠庙","f":"五言律诗","c":["立孤人去远，孙子更流芳。","忠节高千古，神功被一方。","旧祠传异代，新爵换真王。","何幸南归便，焚香拜寝堂。"]},{"t":"东密岩乃先世祖都使公沄淘兄弟起兵拒黄巢处","f":"七言律诗","c":["万仞巉岩百里长，此中曾蹶草头黄。","衣冠税驾趍行在，兄弟登坛守故乡。","一代风尘山戍远，千家烟火石台荒。","水田折戟时常露，知是先人旧战场。"]},{"t":"齐云岩 其一","f":"七言律诗","c":["四山回合杳难穷，翠锦屏开面面工。","巨石穿云成户牖，半崖飞雨作帘栊。","地灵今古神先据，境隔仙凡路可通。","极目丹邱何处是，巍巍楼阁起天中。"]},{"t":"齐云岩 其二","f":"七言律诗","c":["何年绛节此中停，五老依然护紫庭。","钟鼓分头双岫碧，香炉当面一峰青。","匡庐未敢争谁秀，玄武应知不自灵。","胜览日斜归未得，细磨苍藓读碑铭。"]},{"t":"古城岩","f":"七言律诗","c":["乘閒来上古城岩，石洞深深似隔凡。","叠巘每迎神驭下，危峰疑出鬼工劖。","一溪寒水围青嶂，万壑天风响翠杉。","知是何人先到此，断崖高处刻题衔。"]},{"t":"次宋县令邹补之岩口石壁留题之作","f":"七言律诗","c":["不见当年旧县基，独留孤庙想陈隋。","水过山脚无寻处，路绕云根有断时。","雉堞草荒埋废础，鹅峰苔老剥残碑。","危阑却倚青冥望，入眼分明自有诗。"]},{"t":"松萝山","f":"七言律诗","c":["双峡中分一径通，宝坊遥隔片云东。","四时山色涵空翠，万折泉声泻断虹。","清爱竹孙穿冻雪，静闻松子落香风。","登高两屐吾方健，携手无因得赞公。"]},{"t":"断石村","f":"七言律诗","c":["大星何日坠沧浪，点破风前一镜光。","野棹偶来幽涧侧，古诗谁刻断崖傍。","丹梯恐蹑苍苔滑，云碓时舂白稻香。","西望欲穷山尽处，石人峰倚暮天长。"]},{"t":"饮杨浚明推府宅夜归宿城隍道院","f":"七言律诗","c":["醉投琳馆一灯残，叶上萧萧雨未乾。","乍入故乡翻似客，倘成新社即辞官。","好山有约游方健，胜地无尘梦亦安。","半夜凉风吹酒醒，恨无奇句写琅玕。"]},{"t":"二月一日辞亲赴京出休宁东门","f":"五言古诗","c":["贱子来何时，倏焉戒晨装。","王程难久滞，俛首辞高堂。","哽咽不敢啼，惧我亲情伤。","踯躅县东门，涕下沾衣裳。","回思古之人，仕者不出乡。","自从封建废，坐使亲义戕。","我生竟何成，去住心徬徨。","春阴澹如染，遥山郁相望。","愿保忠孝期，桑梓生辉光。"]},{"t":"道中与敏德弟联句","f":"七言律诗","c":["故乡山水忍相违，聚首无端又北归。","一路春风梅正发，几家冬雨麦初肥。","杯盘祖席离情苦，车马长亭曙色微。","主上只今求道切，敢将忠孝负庭闱。"]},{"t":"渔梁坝登舟至浦口初闻雷饯者相贺","f":"五言律诗","c":["路当歙县境，水是浙江源。","竹树知谁氏，风光似故园。","峰头岚翠合，石齿浪花翻。","举棹闻雷处，嘉祯感赠言。"]},{"t":"夜宿绵溪","f":"七言绝句","c":["屈指离家又一程，篷窗欹枕梦难成。","无端水郭停舟处，半夜滩声似雨声。"]},{"t":"过乳滩","f":"七言律诗","c":["一棹迎风下乳滩，推篷忽得两奇观。","高崖瀑水淙声远，盘石孤松堕影寒。","仙境恨无同志赏，尘冠思向此中弹。","他时梦想劳题句，不用千金买画看。"]},{"t":"宿河上岭入夜风雨大作","f":"五言古诗","c":["辞家已三日，夜泊苍山矶。","遥看月仰瓦，星斗何依稀。","玄云忽四合，黯尔灯无辉。","孤眠觉有异，起坐披裳衣。","长风挟雷电，雨若天瓢挥。","万响凛不测，势恐孤篷飞。","船头屡低昂，知是江波肥。","移床避罅漏，客心转凄危。","古云行路难，此语良不非。","悄然百忧集，君父难两违。","裁诗记所遭，胡宁不怀归。"]},{"t":"淳安道中用渔梁坝韵","f":"五言律诗","c":["桐梓何年盛，溪头尚有源。","疏梅临竹岸，细麦拥茶园。","兴薄飞鸦去，閒便浴鹭翻。","舟师能指点，空谷应人言。"]},{"t":"雨中过严州与张时祯通判同年叙别","f":"七言绝句","c":["石梯如画带江楼，喜遇看花旧俊游。","十四年来情不尽，东风吹雨上官舟。"]},{"t":"严州东下两山高崖瀑布以百十数","f":"古风","c":["东崖瀑布如玉龙，西崖瀑布如白虹。","千寻之势不可杀，交飞乱落清泠中。","小声万骑驱元戎，大声五夜鞭雷公。","初疑武丁举斧开崆峒，石髓流出青山空。","又疑海若上借愁天工，鬼窟遂与银河通。","北舟直下桐川东，一江春水摇春风。","推篷左右忽见此，顿清百岁尘埃胸。","迹愧庄生为世笼，才非李白忧诗穷。","一杯酹水一自酌，安得凌虚浩然与尔争豪雄。"]},{"t":"钓台","f":"七言绝句","c":["暂掷纶竿去复还，徵书空照水云间。","桐江岩壑知心久，肯遣移文过北山。"]},{"t":"过姚文敏公墓","f":"七言律诗","c":["三朝勋业重姚崇，最与家君契谊同。","帝里风烟留故宅，仙乡山水见幽宫。","两家莫报君恩厚，百世应存士论公。","我忝礼闱门下客，不胜清泪落东风。"]},{"t":"登富春山时乡族商人多以索逋钱寓子陵祠问其所从索者皆县官也笑赋一绝","f":"七言绝句","c":["争道先生百世师，富春山麓起崇祠。","残碑尚刻希文记，终有廉贪立懦时。"]},{"t":"夜穿杭城宿吴山驿明日三司故人固请游西湖又明日遂拜岳王坟饮净慈寺时顾天锡郎中以公事寓杭不及预会 其一","f":"七言律诗","c":["匆匆行李夜穿城，好友来寻半日盟。","峰顶几多僧锡住，湖心无数酒船行。","风来废苑堪怀古，雨蚀残碑不记名。","入眼净慈还数里，望尘先拜岳家茔。"]},{"t":"夜穿杭城宿吴山驿明日三司故人固请游西湖又明日遂拜岳王坟饮净慈寺时顾天锡郎中以公事寓杭不及预会 其二","f":"七言律诗","c":["湖上东风水似苔，群公相约看山来。","午钟殷殷穿低树，春宴纷纷集宝台。","千里暂教尘梦醒，一尊思待故人开。","兴酣更欲寻龙井，谁有风流续辩才。"]},{"t":"钱唐杂咏四首 其一","f":"七言律诗","c":["水色山光似昔时，往来还动百年思。","颠崖藓蚀钱王箭，拍岸潮迎伍相祠。","岁月难胜双短鬓，兴亡能博几新诗。","望中喜是林逋宅，竹外梅花一两枝。"]},{"t":"钱唐杂咏四首 其二","f":"七言律诗","c":["康王疋马渡江时，北望谁能有所思。","洛社末由恢土宇，临安何忍奉郊祠。","两朝和议愁通表，一卷褒忠漫有诗。","只赖皇天知此意，墓林长耸向南枝。"]},{"t":"钱唐杂咏四首 其三","f":"七言律诗","c":["徙倚湖山欲暮时，行人随处动遐思。","张王僣窃今无地，白传风流尚有祠。","夜静六桥谁放鹤，春回三竺好题诗。","篷窗预买仁和酒，卧听舟人唱竹枝。"]},{"t":"钱唐杂咏四首 其四","f":"七言律诗","c":["繁华欲赋太平时，惭愧无才续左思。","晓市船趋三汊港，春游人集两峰祠。","楼台不类人间世，风月都成画里诗。","东望綵云怀帝阙，旸乌初上海桑枝。"]},{"t":"岳王墓再赋一首","f":"七言律诗","c":["南渡宗贤力相秦，不辞降表便称臣。","青衣空作还家梦，金字频追出塞人。","乱国已遭三寸舌，封王何益九原身。","渔郎似识英雄恨，日对孤坟理钓纶。"]},{"t":"皋亭山","f":"七言绝句","c":["晓受降书夜戢兵，路人犹说伯颜名。","中原多少奇男子，不向燕山立汉旌。"]},{"t":"道中六言","f":"古风","c":["皋亭山前竹铺，临平镇下桑园。","北岸方收缆索，东风忽动樯幡。"]},{"t":"调巡抚宣府张养正都宪","f":"七言绝句","c":["烽火中宵澈塞明，晓提精骑出严城。","黄云白草刘家砦，从此边人不敢行。"]},{"t":"过桐乡晚宿皂林驿","f":"七言绝句","c":["东风吹日半晴阴，不觉船窗水气侵。","三里人家春淡淡，一江烟树晚沉沉。"]},{"t":"望后舟","f":"古风","c":["前舟已过青山趾，后舟犹驻沧江涘。","得风未可遽凌人，同在江湖作舟子。","欲去不去心茫然，耳畔彷佛闻鸣舷。","须臾相见谢相候，并行不碍波中天。","君不见前舟独行方坐啸，后舟向晚终须到。","又不见后舟载比前舟轻，反过前舟三日程。","活计平生系征舸，但愿风潮共安妥。","不惜朝朝望后舟，他人岂必相忘我。"]},{"t":"嘉兴拜先师吕文懿公冢以陈无已丘园无起日江汉有东流诗韵敬赋十首 其一","f":"五言绝句","c":["隔地三千里，违颜十八秋。","悠悠生死恨，今日过林丘。"]},{"t":"嘉兴拜先师吕文懿公冢以陈无已丘园无起日江汉有东流诗韵敬赋十首 其二","f":"五言绝句","c":["先皇临御日，夫子最蒙恩。","共说青山下，双麟表墓园。"]},{"t":"嘉兴拜先师吕文懿公冢以陈无已丘园无起日江汉有东流诗韵敬赋十首 其三","f":"五言绝句","c":["已别门墙久，犹能识旧奴。","遗书三万轴，还似旧时无。"]},{"t":"嘉兴拜先师吕文懿公冢以陈无已丘园无起日江汉有东流诗韵敬赋十首 其四","f":"五言绝句","c":["鹤发太夫人，见我动容喜。","再拜升高堂，怀贤不能起。"]},{"t":"嘉兴拜先师吕文懿公冢以陈无已丘园无起日江汉有东流诗韵敬赋十首 其五","f":"五言绝句","c":["夫子虽云亡，未绝词垣笔。","尚有代言书，昭昭比星日。"]},{"t":"嘉兴拜先师吕文懿公冢以陈无已丘园无起日江汉有东流诗韵敬赋十首 其六","f":"五言绝句","c":["一代吕家府，风流重此邦。","重来还记取，双户对寒江。"]},{"t":"嘉兴拜先师吕文懿公冢以陈无已丘园无起日江汉有东流诗韵敬赋十首 其七","f":"五言绝句","c":["之子读遗经，青年盛文翰。","皦皦丹凤雏，居然立霄汉。"]},{"t":"嘉兴拜先师吕文懿公冢以陈无已丘园无起日江汉有东流诗韵敬赋十首 其八","f":"五言绝句","c":["夫子本清白，芳名亦难朽。","岂无富贵家，灰飞竟何有。"]},{"t":"嘉兴拜先师吕文懿公冢以陈无已丘园无起日江汉有东流诗韵敬赋十首 其九","f":"五言绝句","c":["滥逐门生后，何才辅两宫。","百年含愧处，此道不曾东。"]},{"t":"嘉兴拜先师吕文懿公冢以陈无已丘园无起日江汉有东流诗韵敬赋十首 其十","f":"五言绝句","c":["一瓣香难致，官亭促去舟。","船窗应作梦，清泪早先流。"]},{"t":"过太湖追和宋苏舜钦韵","f":"七言律诗","c":["万古渊源直到今，征帆如叶望中深。","天留白塔分平野，云拥青山入太阴。","江势西来寒汇玉，日华东出暖浮金。","苏郎死后閒风月，吴下何人续胜吟。"]},{"t":"李员外应祯吴太史原博约游虎丘","f":"七言律诗","c":["日散林霏见虎丘，故人清约此閒游。","望深绿树知藏寺，吟遍青山始系舟。","塔院风来花似雪，剑池春到水如油。","酒阑不尽吴中胜，老衲相招更倚楼。"]},{"t":"虎丘之游沈启南在坐作画一幅再赋一首","f":"七言律诗","c":["苍崖题字半留痕，笑倚东风酹一尊。","寺主绕山开竹牖，园丁随路作花村。","听经石古苔生绣，葬剑池深水不浑。","入眼有诗吟未得，天机都属隐侯孙。"]},{"t":"雨中次无钖寄秦廷韶太守","f":"七言绝句","c":["南来欲试惠山泉，春雨横江懒系船。","咫尺故人难晤语，相思时诵竹垆篇。"]},{"t":"寄华守正","f":"七言绝句","c":["百里江乡石路斜，东风相隔渺天涯。","离人十载今何似，无限情悬孝子家。"]},{"t":"秦廷韶太守及九龙山樵陆懋成请游惠山遂酌第二泉饮听松庵次少师姚广孝留题旧韵一首","f":"五言律诗","c":["江雨吹风过，山门向晚开。","汲瓶分水去，骑马听松来。","老鹤惊人起，新篁夹路栽。","多君怜别意，随处送春杯。"]},{"t":"留题听松庵次廷韶韵","f":"七言律诗","c":["一庵门对老松开，镇日风传万壑哀。","古井暗泉寒泻玉，长廊阴雨滑生苔。","钟声忽自山中出，人影遥从树杪来。","未濯尘缨还自笑，篱根苍犬合惊猜。"]},{"t":"寄邹镛","f":"七言绝句","c":["尚书幕下总能文，曾说邹阳最出群。","此日相思空倚棹，暮天寥落见行云。"]},{"t":"游惠山与廷韶赋诗看懋成作画不觉至暮相别未数里风雨大作竟误一程船窗灯下漫赋一律奉寄二君子","f":"七言律诗","c":["笑坐泉亭汲水尝，偶然行乐便相忘。","南来渐有江山癖，北去那忧岁月长。","好景正堪增罨画，短吟犹未病奚囊。","早知风雨春江暮，悔不随缘宿上方。"]},{"t":"常州饮廉伯家","f":"七言律诗","c":["舟到毗陵晚不移，相留曾是十年期。","坐间总说江南乐，别后应悬冀北思。","夜酌不知更已换，春城偏与月相宜。","归来忽记豪吟处，稍觉閒情似往时。"]},{"t":"谒京口魏胜将军庙","f":"五言古诗","c":["长风吹山矶，落日下京口。","桓桓魏将军，庙食此邦久。","土马剩仪卫，金书炫庭牖。","忠义夙所钦，再拜酹江酒。","忆当宋社南，君臣窜身走。","将军起田间，意气最雄﨣。","孤城江海上，日日事攻守。","中原天弗畀，竟为敌所有。","前旌晓不扬，雄剑夜空吼。","何人始召乱，志士徒殒首。","当时百战场，荒落见沙柳。","千里几兴废，激烈史官手。"]},{"t":"金山七咏 其一 金山","f":"五言绝句","c":["楼阁中天起，波涛四面降。","崔嵬千尺影，终古镇长江。"]},{"t":"金山七咏 其二 妙高台","f":"五言绝句","c":["东风留客棹，白日此登台。","帆影来无际，江声去不回。"]},{"t":"金山七咏 其三 善才石","f":"五言绝句","c":["何物瑶琨石，龙宫夜不函。","由来江岸侧，天造补陀岩。"]},{"t":"金山七咏 其四 留云亭","f":"五言绝句","c":["亭子临孤绝，江云碍不飞。","时来檐下宿，水气湿僧衣。"]},{"t":"金山七咏 其五 吞海亭","f":"五言绝句","c":["江风号万壑，峰顶一登临。","势欲吞沧海，游方惬壮心。"]},{"t":"金山七咏 其六 仙人洞","f":"五言绝句","c":["鬼斧穿山骨，明明透一窗。","仙人时举武，壁立下窥江。"]},{"t":"金山七咏 其七 郭璞墓","f":"五言绝句","c":["落日江心墓，凄凉郭景纯。","桑田不可测，抚掌笑山人。"]},{"t":"瓜州遇同年鲍栗之通判二绝 其一","f":"七言绝句","c":["满路人称鲍叔贤，一尊相见暮江边。","长安陌上看花处，回首春风十四年。"]},{"t":"瓜州遇同年鲍栗之通判二绝 其二","f":"七言绝句","c":["楚山如画水如蓝，乡思纷纷渐不堪。","今夜瓜州滩上宿，便从江北梦江南。"]},{"t":"扬州 其一","f":"七言律诗","c":["东风吹彻晚阴晴，两岸新芜一棹横。","去我青山如避俗，向人黄柳欲倾城。","潮回海口盐船上，春入淮南米价生。","二十四桥渔唱遍，嫦娥应识古今情。"]},{"t":"扬州 其二","f":"七言律诗","c":["江日辉辉下广陵，客边吟兴偶然增。","宋军水砦多编户，隋帝离宫半属僧。","鹅鸭似便春雨数，楼台争出暮云层。","往来总戴承平福，莫问从前几废兴。"]},{"t":"忆在姑苏与顾天钖郎中语次亦有亡弟之感惨然对泣不能自胜因追次其韵一首","f":"七言律诗","c":["泉下应无日再晖，一灯寥落伴僧扉。","重阳为尔愁看菊，未老凭谁共采薇。","妙质固应天最靳，芳年真与世轻违。","等閒不敢娱亲侧，忍见同时旧綵衣。"]},{"t":"过高邮湖","f":"五言律诗","c":["晓发盂城驿，人家过浅塘。","日华初耀水，风力正开洋。","竹缆收蛇蜕，蒲帆列雁行。","客心还自喜，今夕到淮阳。"]},{"t":"予谒告还朝道出淮阴方传漕运总戎平江伯过访而侍御尹君性之奉命巡贵州舣船之际得邂逅焉性之出示阁老寿光刘先生赠行之作谨步韵一首奉别而蒹葭倚玉之诮所不能免云","f":"七言律诗","c":["两岸垂杨石渍苔，皇华新馆昼长开。","方传漕运将军出，忽见分司御史来。","当道豺狼应退避，忘机鸥鹭莫惊猜。","相逢却愧无佳句，砚匣经旬积暗埃。"]},{"t":"漂母祠","f":"七言绝句","c":["一饭难忘老妪恩，崇祠应出旧王孙。","平生推食蒙知己，肯不捐躯答至尊。"]},{"t":"淮阴侯庙","f":"七言绝句","c":["钟室堪嗟走狗烹，反形千古未分明。","史官独为将军惜，不念当时老郦生。"]},{"t":"次清江浦邵文敬吴文盛二主事邀饮寄寄亭中夜放舟至清口晓渡淮至清河乃别","f":"七言律诗","c":["杏花红烂竹梢青，水次新开寄寄亭。","共挽行装春送酒，还催挝鼓夜扬铃。","风悲旧楚遥闻树，天入长淮下见星。","记取客边分去住，驿楼残角梦初醒。"]},{"t":"怀贤诗二章 其一 平江伯陈恭襄公","f":"五言古诗","c":["﨣﨣陈将军，平江始开国。","少年八石弓，勇气屡破贼。","朅逢中兴主，得附升天翼。","当宁念丰镐，京邑望南北。","安得萧与韩，晏岁足兵食。","将军家合肥，老大谙稼穑。","一朝被简知，舞蹈奉明敕。","建牙淮水阳，诸路尽承式。","孜孜竭众智，疏凿靡馀力。","廒庾便交挽，堤闸济危啬。","艘舸随浅深，湖坝几通塞。","百年民力苏，万里海涛息。","居然奠东南，不复困供亿。","将军去几时，寝庙见颜色。","火旗与云马，夜下不可测。","父老说遗事，往往动遐忆。","征夫多苦辛，国本在培植。","贤孙今代将，当复守成则。","东风吹客舟，清口日初昃。","公忠夙所钦，再拜读铭刻。"]},{"t":"怀贤诗二章 其二 工部尚书周文襄公","f":"五言古诗","c":["周公起江右，历官大司空。","文章夙有志，尝叩蓬莱宫。","愿藉九天宠，致身列宿中。","刑曹得良誉，藩辅无全功。","南畿与西浙，国赋忧难充。","主上屡顾之，政柄付此公。","肩舆行列郡，活计归深衷。","仓囷日委积，货布时通融。","出纳有盈缩，岁事无丰凶。","坐令数千里，民力不告穷。","纷纷两京道，续续舟车通。","邻封借羡馀，边檄分陈红。","东南二十年，一老如帡幪。","云胡事弗偶，谗起惊宸聪。","公归浩难期，民惠嗟无终。","所在貌公容，如奉家主翁。","我生已迟暮，素仰先达风。","兹来识民隐，非独暵涝螽。","文法岂不密，治效将无同。","公名当益显，日与江流东。"]},{"t":"宿迁早发","f":"古风","c":["驿店萧萧雨落，水村喔喔鸡鸣。","推枕偶然梦觉，沿河已有人行。"]},{"t":"祁州上巳与范嘉龙御史舟中小酌","f":"七言绝句","c":["偶尔相逢泗水滨，一舟谁主复谁宾。","论心久已同清白，不作平时祓禊人。"]},{"t":"过吕梁洪遇管洪王主事","f":"五言律诗","c":["山形四面合，水道一支通。","乱石东西岸，惊涛上下洪。","懋迁充国用，疏凿仰神功。","使馆劳晨爨，征帆快午风。"]},{"t":"歌风台","f":"七言绝句","c":["风云无限故乡情，酒半登台奏楚声。","富贵一般游子意，锦衣何似衮衣荣。"]},{"t":"与提学娄克让御史饭泗亭驿舟晤言甚洽","f":"五言古诗","c":["士行先出处，治道本惩劝。","持此律今古，有若执符篆。","大义苟失之，如水决堤堰。","寥寥千载下，圣哲炳垂宪。","不见东邻女，芳岁甘自献。","大节一以亏，容质徒秀曼。","亦有主家者，恃长足私愿。","好恶苦怫人，骨肉变雠怨。","乃知君臣间，秉德两宜健。","庶几三代风，必世可延蔓。","娄公天下士，于我情缱绻。","长途倾盖中，共此一升饭。","誓当致身来，不辱青紫楦。","谅哉同心言，功名及时建。","相期在白首，保作无瑕瑗。"]},{"t":"舟中清明有感寄克俭弟","f":"七言绝句","c":["兄弟而今一半存，想君愁上鹡鸰原。","纸钱麦饭南山路，死别生离两断魂。"]},{"t":"济宁夜雨感怀闻外叔舅侍御李公已赴山东宪副","f":"七言律诗","c":["自逐东风过大江，起居终日对船窗。","梦随野鹤孤飞健，身似山僧百虑降。","人影向灯春寂寂，水声和雨夜淙淙。","犹馀一寸思情在，不觉晨钟隔坐撞。"]},{"t":"风入松 草桥阻风雨作","f":"古风","c":["萧萧阴雨渐经旬。","有意暗摧春。","林鸠来往缘何事，声不住、故恼征人。","没脚泥壅岸尾，打头风断河漘。","篷推蓬、偏感异乡身。","归梦夜来频。","江南江北家千里，心随舵去住无因。","兀坐悄然自数，半生多少苦辛。"]},{"t":"道中有感","f":"五言古诗","c":["千里徐滕路，愁云惨不开。","使方求郡瘼，天未恤民灾。","饿殍填途卧，浮尸蔽水来。","图存归盗贼，忍爱鬻婴孩。","行乞无人顾，生于死更哀。","劝分遭吏毒，贫与富俱摧。","不任驱征役，相甘食弃骸。","一时轻转窜，几日可招徕。","汉诏先惩已，周官重理财。","忧勤劳主上，调燮仰元台。","倘及收麰麦，犹堪济草莱。","岁功曾预讲，国本在深培。","望望诸侯境，纷纷御史台。","岂无同志者，空复泪盈腮。"]},{"t":"遇汪文灿御史南归报两小儿汪保祖保俱安好","f":"五言律诗","c":["久别怜双璧，舟中数梦之。","不图逢故友，亲说见吾儿。","对客能秪揖，延茶请诵诗。","寥寥千里外，足慰一春思。"]},{"t":"过分水庙戏成棹歌六章 其一","f":"七言绝句","c":["济河潺潺向北流，济河㶁㶁向南流。","官船私舶都过此，南来北去几时休。"]},{"t":"过分水庙戏成棹歌六章 其二","f":"七言绝句","c":["一条河里两般风，南客张篷北落篷。","天公只是无心子，有心人莫怨天公。"]},{"t":"过分水庙戏成棹歌六章 其三","f":"七言绝句","c":["龙王庙前石作堤，马头湾脚路成泥。","莫笑水流分彼此，只缘地势有高低。"]},{"t":"过分水庙戏成棹歌六章 其四","f":"七言绝句","c":["东岸人家开饭奁，西岸人家垂酒帘。","传道行人莫轻买，今年沽价十分添。"]},{"t":"过分水庙戏成棹歌六章 其五","f":"七言绝句","c":["供应船头金弹丸，醉坐船里珍馐盘。","有人推篷怜饿殍，大家说是秀才官。"]},{"t":"过分水庙戏成棹歌六章 其六","f":"七言绝句","c":["老郎荷锸开浅洲，小儿曳缆送官舟。","朝朝去见垂杨柳，不管流离苦到头。"]},{"t":"次荆门管河杨郎中求题水墨葡萄","f":"七言古诗","c":["空中忽散摩尼珠，一一牵动骊龙须。","鲛人泪莫尽升斗，贾胡价可论锱铢。","居然月上蜿蜒架，真宰有心愁幻化。","玄香隐隐凝不飞，瘦影离离巧相亚。","良工近来人未知，日观不来还数谁。","乳酒年来熟银瓮，客星终夜窥端池。","关西夫子行河使，宝绘堂中了公事。","底须满摘水晶盘，眼饱令人发诗思。"]},{"t":"过聊城县境","f":"五言绝句","c":["策士知仁义，千秋一鲁生。","纷纷当日事，春水下聊城。"]},{"t":"武城","f":"五言绝句","c":["千载武城县，依然鲁水涯。","民生如不遂，弦诵亦何为。"]},{"t":"乘月夜发二鼓至甲马营","f":"七言律诗","c":["晓色苍苍下武城，解舟还趁月中行。","河流曲写之玄字，渔唱清传欸乃声。","随处倚篷吟不尽，迩来欹枕梦难成。","灯前未暇呼津吏，问是何年甲马营。"]},{"t":"次德州简管粮张道济主事同年","f":"七言绝句","c":["一冬南去一春还，历尽征途水与山。","却忆故人清话处，隔城相望夕阳间。"]},{"t":"良店道中大风夜作野泊安陵达晓风息趋连窝","f":"古风","c":["我行沧景路，渺渺夜过亥。","东风何太颠，势欲?鲸海。","盘涡如阱旋，骇浪若山嵬。","崩腾沙口决，斩剥岸形改。","官舟浮一匏，出没渐危殆。","牵夫屡前却，舟子失精采。","无乃蛟龙怒，或恐鼋鼍馁。","合力眠高桅，择地舣而待。","家人走彷徨，船头设菹醢。","相呼酹冯夷，亦欲诉真宰。","狂飙俄尔恬，愁云散其叆。","张帆下中流，击楫歌欸乃。","起望推双篷，喜气人百倍。","向来得失心，悠悠竟安在。"]},{"t":"留别沧州守禦赵将军诗三首 其一","f":"七言绝句","c":["临河高堞古沧州，一将分符得上游。","充国由来好孙子，营平终袭汉家侯。"]},{"t":"留别沧州守禦赵将军诗三首 其二","f":"七言绝句","c":["骨肉相违岁几更，偶然离合更关情。","家传只有龙韬在，一卷殷勤付馆甥。"]},{"t":"留别沧州守禦赵将军诗三首 其三","f":"七言绝句","c":["横海军声震朔庭，土人多失旧图经。","高原何处藏弓剑，落日寒云蔓草青。"]},{"t":"为赵守禦题溪云居士水墨龙","f":"七言律诗","c":["阴风萧萧吹急雨，龙子相将乞龙乳。","随潮上下不可撄，头角疑能作人语。","溪云画手工不工，抚景还思陈所翁。","旱岁安能慰民望，青天白日驱丰隆。"]},{"t":"静海道中地名杨柳青园林隐映可爱","f":"七言绝句","c":["春阴澹沲绿杨津，两岸风来不动尘。","一日船窗见桃李，便惊身是卧游人。"]},{"t":"直沽望海","f":"七言律诗","c":["击楫中流亦快哉，海门春放一帆开。","五更日透烟霏出，万里风推云浪来。","壮志不惊龙窟宅，奇观初识凤楼台。","行边历历鱼盐士，倘有平时出众才。"]},{"t":"杨村逆风通夕","f":"五言律诗","c":["忽忽无言里，悠悠不寐中。","短檠流绛蜡，阴牖落青虫。","人幸窥篷月，天悭上水风。","白河三百里，羁思浩无穷。"]},{"t":"通州道中","f":"七言律诗","c":["夹岸摇摇酒幔长，野人渔牧自成庄。","商征晓集河西务，漕粟春投水次仓。","几个鹤巢依古树，一声鸡唱出柔桑。","眼中渐觉风光好，直北红云是帝乡。"]},{"t":"张家湾","f":"七言绝句","c":["张家湾口望都城，犹是行人半日程。","羸马似龙谙旧主，临河相顾一长鸣。"]},{"t":"入都城","f":"七言律诗","c":["十里红尘马首翻，眼中不改旧颓垣。","征夫引躅犹穿巷，稚子迎欢正及门。","襆被几时淹驿路，衣冠明日叩天阍。","往来敢惮关河险，得遂私情是主恩。"]},{"t":"集李绝句十八首 其一 登京口望江楼","f":"七言绝句","c":["故国园林草自芳，望中情地转凄凉。","行人莫苦登高阁，高处何曾见故乡。"]},{"t":"集李绝句十八首 其二 途中遇郑时晖御史赴谪还家养疾二首","f":"七言绝句","c":["湛恩惟待立鸡竿，岂是明时学考槃。","身计未谐归计好，一宵清话到更阑。"]},{"t":"集李绝句十八首 其三","f":"七言绝句","c":["尘寰渐远渐凄清，地近乡关喜气生。","只恐诏书非久下，归来依旧马蹄声。"]},{"t":"集李绝句十八首 其四 自况二首","f":"七言绝句","c":["千里幽怀一凭阑，君恩宁许更盘桓。","朝中未有输忠处，肯便临溪把钓竿。"]},{"t":"集李绝句十八首 其五","f":"七言绝句","c":["铅堑辛勤十四年，幸逢圣主得称贤。","秃毫强会悠悠事，敏政当居俗吏前。"]},{"t":"集李绝句十八首 其六 车瓜州坝","f":"七言绝句","c":["泥途渐过车声滑，才得扶舁渡浅河。","从此异乡谁是侣，月明孤影落澄波。"]},{"t":"集李绝句十八首 其七 饮扬州嵩山寺二首","f":"七言绝句","c":["醉乡□□□□□，沦落多愁笑不成。","苦恨俗缘无了处，江村古寺偶閒行。"]},{"t":"集李绝句十八首 其八","f":"七言绝句","c":["閒愁不觉过年光，只有醒时觉异乡。","不醉多愁醉多病，一篇齐物是医方。"]},{"t":"集李绝句十八首 其九 淮上对月","f":"七言绝句","c":["劳生谁在定中看，境胜才知宇宙宽。","一月解行天一匝，素娥心事问应难。"]},{"t":"集李绝句十八首 其十 登泗水亭","f":"七言绝句","c":["青山行尽入红尘，古木亭边夜向晨。","书未隔年难得报，我来登望倍凝神。"]},{"t":"集李绝句十八首 其十一 歇济宁分水铺","f":"七言绝句","c":["二江斜入似娥眉，华郭春光欲暮时。","京洛路长何日到，几人相见不相知。"]},{"t":"集李绝句十八首 其十二 临清遇雨","f":"七言绝句","c":["一尊撩眼怕长迷，月欲东生日又西。","已恨碧山相阻隔，不期风雨更凄凄。"]},{"t":"集李绝句十八首 其十三 过柳青村","f":"七言绝句","c":["不知园圃是谁家，开尽无名草木花。","今日倚阑添懊恼，人言落日是天涯。"]},{"t":"集李绝句十八首 其十四 有怀亡弟五首","f":"七言绝句","c":["家园归省浙江东，璧碎珠沉几日中。","尘里笙歌千古梦，悠悠无处问苍穹。"]},{"t":"集李绝句十八首 其十五","f":"七言绝句","c":["泪滴金杯不自知，天孙何约是来时。","骑鲸别后无寻处，一步寒郊一惨眉。"]},{"t":"集李绝句十八首 其十六","f":"七言绝句","c":["月意愔愔露气微，池亭何处见清晖。","只应梦里成胡蝶，拟共杨花苦斗飞。"]},{"t":"集李绝句十八首 其十七","f":"七言绝句","c":["风月犹应似旧清，困来终是睡难成。","相思无计能相见，肠断城头画角声。"]},{"t":"集李绝句十八首 其十八","f":"七言绝句","c":["下有娇儿上有亲，阑边为汝最伤神。","流年渐共春华老，闻说清明在此辰。"]},{"t":"送康用和南归诗","f":"五言古诗","c":["矫矫丹山雏，孤飞直千仞。","昂昂汗血驹，天闲谢羁靷。","君子赋归欤，使我失朋亲。","忆昔与君友，我发始髫龄。","君气不可当，感激慕英蔺。","虎闱驰夙声，乌台发新轫。","威行畿甸间，事至若迎刃。","朝纲固已肃，颓风亦云振。","哗言倏中起，万里竟遭摈。","终为一寸铁，蹇蹇磨不磷。","驱驰闽海隅，再领县厅印。","低首奉期会，坐遣民俗顺。","霈泽岂不施，展转四更闰。","翩然徵诏下，驿骑走方镇。","谓君先天学，往往决悔吝。","行当几日程，喜入九重觐。","衣冠太史氏，相顾得豪隽。","朅从拜命来，惊君雪垂鬓。","在告越踰年，日日理衰疢。","居然停禄食，有待竭忠荩。","士节难自保，我疾可无慎。","封章乞解组，伏阙再三进。","云臣本孤陋，颇欲激芳润。","少小读韦编，漫识离与震。","挂扐有成法，筮者殆充牣。","犬马心弗胜，此选亦太遴。","倘讦遂臣私，实免负尧舜。","言词既恳切，重瞳乃回瞬。","萧萧官廨中，四鼓对馀烬。","黎明出都门，徒步一何迅。","平生几交游，逆旅漫相讯。","君言幸此归，馀生绝嫌衅。","松菊莽犹存，庭户扫还汎。","儿子已胜耕，岂复念寒馑。","水次分鱼租，山中乐田畯。","稽首荷天王，恩波一朝浚。","君才诚卓荦，君志更孤峻。","永奉大夫欢，不愧世家胤。","嗟彼名利场，人或以身徇。","富贵将何为，幻若野中燐。","是非千载后，孰是驽与骏。","郊亭九月馀，霜气入鸿阵。","渺渺征车行，落叶载途衬。","送君无限情，长歌以相赆。"]},{"t":"次南京尚宝泰和杨公述职诗韵 其一","f":"七言律诗","c":["忧国长思策治安，迩来微觉鬓毛残。","牙绯当殿初书最，清白传家久耐寒。","正论几闻倾四望，高眠犹说计三餐。","老成终近君王侧，双佩追随应八銮。"]},{"t":"次南京尚宝泰和杨公述职诗韵 其二","f":"七言律诗","c":["不随桃李竞春荣，宦辙惟君守一诚。","典瑞职当金阙近，奉常卿比玉壶清。","宠光向晚频烦下，诗思清秋一倍生。","拟有颂声歌圣德，怀乡宁似庾兰成。"]},{"t":"次南京尚宝泰和杨公述职诗韵 其三","f":"七言律诗","c":["郭隗台边秋日明，张家湾里暮潮平。","离筵句好开新社，分寺官閒说旧京。","白雁叫霜先客度，黄花经雨待谁荣。","怜予最有江南忆，把袂因君百念生。"]},{"t":"十月一日进历青宫叨预执事呈同事罗洗马","f":"七言律诗","c":["文华门启日临墀，凤历初陈鹤驾移。","卫士分行旗影杂，官僚双引佩声迟。","万年正朔遵先纪，一代规模陋汉仪。","海岳又开新泰运，愧无鸿笔颂重熙。"]},{"t":"寄王而勉太守","f":"七言律诗","c":["亲舍分明紫翠间，梦魂无夜不南还。","羁鸿远隔三千里，驽马空陪十二闲。","乡思更深云梦泽，古诗谁继陆浑山。","家书拟说贤明府，问俗时来一扣关。"]},{"t":"送张郎中彦质省亲还蜀","f":"七言律诗","c":["离筵新酒白波浑，一棹西还荷主恩。","宦辙屡经扬子渡，家园长切武侯屯。","尘生客袂身方健，喜入亲颜齿更尊。","小弟心情亦如此，敢忘天语若春温。"]},{"t":"送陆顺之赴南京户部主事 其一","f":"七言律诗","c":["征辔纷纷罥柳枝，喜君今日拜恩辞。","短亭残暑仍挥箑，久客多情屡荐卮。","辇下文章推甲第，江南财赋属留司。","两京子部皆珍选，好在诸贤答盛时。"]},{"t":"送陆顺之赴南京户部主事 其二","f":"七言律诗","c":["不须挥手听离歌，此到南都仅月过。","丛桂再开新府次，棣棠应发旧厅阿。","家常问讯通邮近，公暇储书积俸多。","小阮相逢烦致语，东朝虚席候鸣珂。"]},{"t":"圯上仙踪送吏部黄侍郎弟叔衡南归","f":"七言古诗","c":["下邳城东沂水流，水中圯桥春复秋。","何物老翁有奇术，乃此折辱张留侯。","往事悠悠已千载，履迹宁随浪纹改。","莫推授受不可当，太息无人继风采。","侯官才人黄叔衡，家居不出多史评。","文章伯氏今少宰，远省到京无限情。","雁声催人难久住，风雨萧萧复南去。","水边大石堪舣舟，予固应知赋长句。"]},{"t":"胡忠安公挽章 其一","f":"五言律诗","c":["品秩登三事，忠勋历五朝。","衣冠存典礼，风俗被薰陶。","泽国鸥盟解，钧天鹤梦遥。","独留全德在，天不想风标。"]},{"t":"胡忠安公挽章 其二","f":"五言律诗","c":["忆昔垂髫日，抠衣拜省庭。","松筠知寿考，金玉见仪刑。","命笔看题字，扶筇问治经。","百年回首处，无地候台星。"]},{"t":"半隐为濮用明教谕赋","f":"七言律诗","c":["手提文印历三城，处处岩栖少送迎。","拄笏看云惟自适，濯缨临水共谁盟。","未容全享山林福，且得兼收吏隐名。","芸阁梦回还独笑，六街尘拥马蹄声。"]},{"t":"送唐御医致仕还嘉兴 其一","f":"七言绝句","c":["早岁从徵住药坊，老来纳禄返江乡。","闽湖战处君还记，多少征人请异方。"]},{"t":"送唐御医致仕还嘉兴 其二","f":"七言绝句","c":["堂扁如心到处闻，铁厓词赋始丰文。","还家开卷遥相忆，广巷高楼隔暮云。"]},{"t":"送唐御医致仕还嘉兴 其三","f":"七言绝句","c":["日日门前客似麻，活人心苦鬓先华。","此回秀水城中路，医道谁当第一家。"]},{"t":"分得剑井送濮用昭兵部公差便道还毗陵","f":"五言古诗","c":["毗陵东城隅，剑井千尺深。","当年葛仙翁，驻鹤曾幽寻。","有时灵秀硌，白虹出其阴。","魁材与硕辅，秉毓人争歆。","濮君兵曹彦，家住此水浔。","奉檄向江南，薰风惜离襟。","安舟载老母，甚遂平生心。","颇闻井中气，耿耿发自今。","愿保忠孝期，为子歌好音。"]},{"t":"寄王而勉太守","f":"七言律诗","c":["昔在山城暂得亲，一襟潇洒浩如春。","通家谊欲兼师友，雅会情忘论主宾。","南望不堪云碍眼，北来惟有月随身。","等閒却爱听公议，藩省今思起旧人。"]},{"t":"寄孙挥使千户侯","f":"七言律诗","c":["辕门开近歙山阿，日日投壶事雅歌。","养士渐能谙礼乐，逢时全不用干戈。","梦长绕阙心何壮，住久随乡语半讹。","犹记前时相别处，一丛车骑绕临河。"]},{"t":"题小景寄汪廷器","f":"七言绝句","c":["拍岸纹溪水不浑，一间亭子傍松根。","披图恍在芝山下，倚棹来寻断石村。"]},{"t":"荣寿堂为会昌太傅公子锦衣瓒赋","f":"七言古诗","c":["醴泉乡中凤山秀，孕我景陵县太母。","庆源衮衮生公侯，忠孝承家数元舅。","元舅年过八十馀，发如皎雪颜如朱。","迩来谢兵奉朝请，出入特许乘安车。","手诏时来诏耆德，赐府潭潭帝城北。","锦衣公子开新堂，日领孙曾候颜色。","优游已似地行仙，眼看乔木上参天。","讲帏史局从公旧，愿保勋名到百年。"]},{"t":"邢侍郎居敬挽章","f":"七言律诗","c":["楚节随恩侍紫清，棹歌声里独魂惊。","空馀易学传三辅，无复官名署两京。","清白已堪书太史，经纶应未了平生。","相如老去人争羡，分赐无缘及露茎。"]},{"t":"寄于老千户","f":"七言律诗","c":["老去将军最好文，出群名字久相闻。","几人识面窥春色，十载思归隔暮云。","延客酒方应自制，游山诗韵好谁分。","投瓜拟得琼瑶报，何日双鱼寄水濆。"]},{"t":"分得洁蔬供膳为黄岩谢良温孝子赋","f":"古风","c":["采采园蔬翠堪把，粪不污茎水清洒。","晨炊又过午炊来，长跪奉盘供膝下。","于乎奉亲易，说亲难。","爱儿不脱儒生酸，藜藿到口皆成欢。"]},{"t":"送汝行敏舍人赴南京武选员外","f":"七言绝句","c":["与君相好十三年，史局曾同翰墨筵。","好别不堪携手处，西风黄叶满前川。"]},{"t":"虎图为艾光禄天锡赋","f":"七言古诗","c":["于莬何由此中伏，白日寒云静山麓。","草间百兽未全藏，困睡应知不成熟。","玄尾空回七尺长，金眸半闪双星煜。","有时独步出林莽，一声长啸千山肃。","只图当道犬羊空，岂为平生食无肉。","良工写此有深意，颇似高人卧空谷。","投身拟结岁寒盟，上有长松下脩竹。","虽云不动爪牙威，已觉风声撼庭木。","儿童见之骇欲走，不敢黄昏傍墙屋。","丹青逼真乃如此，恐是当时溪上牧。","几思把玩发豪吟，忘却摩须手还缩。","都城广厦接栋宇，入眼定知无此幅。","千金可得书画传，好事谁如汉光禄。"]},{"t":"庆孙锦衣瓒","f":"七言律诗","c":["世将家声蔼帝都，老成还拜执金吾。","由来宠数逢千载，久有才名敌万夫。","仙仗扈行朝佩剑，宫城宿卫夜分符。","他时看取勋猷盛，会续麒麟阁上图。"]},{"t":"分得先字寿致仕谢太守","f":"七言律诗","c":["不待尘中雪满巅，急流亲见赋归田。","黄堂屡换二千石，白社初周六十年。","心静自堪娱晚节，眼明犹足了残编。","池鱼庭草平生乐，底问仙人葛孝先。"]},{"t":"送义门镇巡检李廷用","f":"七言律诗","c":["西风残暑饯离筵，击节长歌宝剑篇。","辛苦携家南向亳，恩荣随例北辞燕。","垂杨驿路三千里，乔木人家五百年。","想过故乡先驻马，古穰秋熟酒如泉。"]},{"t":"题陆谕德鼎仪海榴书屋图 其一","f":"七言绝句","c":["海榴随处傍人红，只有溪山趣不同。","看画却疑家在眼，出门随步任西东。"]},{"t":"题陆谕德鼎仪海榴书屋图 其二","f":"七言绝句","c":["此心苍翠绕蓬莱，劝讲时陪鹤驾来。","退食自公无一事，赤心长对海榴开。"]},{"t":"威凤南飞曲","f":"楚辞体","c":["有虞圣人开明堂，委政师保垂衣裳。","功成治定天降祥，一日三凤鸣朝阳。","羽毛五色云锦张，两凤翥羽北阙旁。","一凤鼓翼天南翔，凤台巍巍临大江。","乌台对耸千尺强，翠竹有实苍梧芳。","十围古柏相倚飞寒霜，凤兮戾止居中央。","坐令喧啾百鸟收其吭，观者四方如堵墙。","圣泽滂，王道昌，千年一运遭明良。","他时凌风会返阿阁上，和鸣协治不可当。","愿操彤管与尔赋乐章，再拜稽首献我皇。","九成雅奏重锵锵，三凤之名传四方。"]},{"t":"送友人方丈旭南归","f":"七言律诗","c":["烟花难尽胜游情，又逐车声出凤城。","丰岁任看投旅宿，圣朝元不重商征。","大方家世当年盛，小阮功名指日成。","身到故园秋正好，环山苍翠落檐楹。"]},{"t":"簪字韵和杨维新谒陵之作","f":"七言律诗","c":["学馆萧萧暂盍簪，西风云散不成阴。","兴阑且逐寻芳步，才拙难陪倚树吟。","宦业每传三试录，家声曾畏四知金。","谒陵初度闻高论，不觉山城漏已深。"]},{"t":"挽通政沈知事父静轩母陈氏 其一","f":"五言律诗","c":["有子通朝藉，遗芳祖汴州。","静便时看槿，机息自盟鸥。","行不惭张仲，文谁继隐侯。","怀贤人共指，石屋岭东丘。"]},{"t":"挽通政沈知事父静轩母陈氏 其二","f":"五言律诗","c":["沈郎贤令母，原自许溪来。","阅世仁人寿，持家烈妇才。","香云飞不返，慈竹死难栽。","壸德流芳处，篇诗屡寄哀。"]},{"t":"六月二十二日大暑坐墙西槐树下有作","f":"五言律诗","c":["门外炎光炽，墙西一径开。","残阳馀古瓦，凉吹发高槐。","鸟与人俱乐，诗随景自来。","无因堪破寂，童子进冰梅。"]},{"t":"送刘尚质舍人乃兄还巴陵","f":"七言律诗","c":["万里家园菊未莎，一舟随雨下官河。","归时梦入东川近，老去情于北阮多。","狎鹭有盟秋未冷，宾鸿成阵夜初过。","巴人倡和真能事，赠别惭无郢上歌。"]},{"t":"黄浦寿沈尚宝廷美母夫人","f":"七言古诗","c":["黄浦之水绿沄沄，疏凿元自春申君。","浦口谁家起华屋，门中雪桧垂苍云。","符台之母乌溪女，倚桧时时听白苧。","抱孙饮水七十年，六月高堂不知暑。","上流可酿昆崙浆，下流可浣芙蓉裳。","临风再拜祝母寿，愿似东流浦水长。"]},{"t":"次山东提学毕廷珍佥宪见寄韵","f":"七言律诗","c":["承递邮筒到集仙，宛然高兴绕吟边。","彩毫香动乌台柏，秀句清分玉井莲。","东鲁化行新士馆，曲江人减旧宾筵。","寻常离合宁须计，共惜平生报主年。"]},{"t":"昌平寓馆再用簪字韵","f":"七言律诗","c":["矗矗遥峰插翠簪，策将羸马过城阴。","青篘白饭逢新主，彩笔花笺续旧吟。","风细涧声清漱玉，日斜林影淡摇金。","空庭伫立生山思，一径无人草自深。"]},{"t":"送刘振之还常熟","f":"五言律诗","c":["文章思董贾，才术陋仪秦。","利器终逢主，高谈已动人。","诗成乡国梦，衣带帝京尘。","得意重来日，容君卜近邻。"]},{"t":"题谢翰长大韶先生云山障子","f":"七言古诗","c":["拔地苍山几千丈，九叠芙蓉照林莽。","群峰夹峙青冥中，万里云开露仙掌。","山回径转得佳处，筑室何人据高壤。","古瓦参差接栋流，虚窗迢递临风敞。","别圃长栽巨胜花，閒门任结蟏蛸网。","桃源渡口短桥通，一派溪光断尘鞅。","黄鸟交啼苑树浓，白鹭低飞田水长。","幽栖彷佛晋朝人，束发乌巾被轻氅。","世途万变了不知，俯槛围棋事閒傥。","相持犹似未忘机，苦向盘中较铢两。","林间暑气不胜薄，羽箑何由更添爽。","童子手供朝暮餐，和露烹葵足斋享。","槛外芳塘五里宽，一围种作莲花荡。","兴来每欲随所之，预有家人棹兰桨。","书册薰垆共一船，水气絪缊护青幌。","远村鸡犬互鸣吠，落日渔樵自来往。","岩阿疑是古赤城，高旆招摇出天上。","树头隐约梵王宫，几杵疏钟送微响。","仙境宁论小大茅，人家不异东西瀼。","生绡咫尺意难穷，愈觉周郎画堪赏。","学士先生太傅孙，方寸之田似山广。","少年奋起大江西，澹墨题名首金榜。","经帏史局最蒙恩，不独词章在忠谠。","鼎铉终期此日调，星凤方增后人仰。","东山别墅有高情，未许披图动遐想。"]},{"t":"仆家徽之篁墩有晋循吏陈忠臣之祠第在焉土人尝更名黄以避巢贼之荼毒袭称至今仆近复篁墩之号而翰长镜川先生作十绝非之仆亦未敢以为是也谨次韵随章奉答幸终教之 其一","f":"七言绝句","c":["敢因一字浪雌黄，自分严于斧钺霜。","只有地灵知此意，年年风雨茁新篁。"]},{"t":"仆家徽之篁墩有晋循吏陈忠臣之祠第在焉土人尝更名黄以避巢贼之荼毒袭称至今仆近复篁墩之号而翰长镜川先生作十绝非之仆亦未敢以为是也谨次韵随章奉答幸终教之 其二","f":"七言绝句","c":["庙中人物气如生，正字分明欲正名。","污蔑但知当自洗，高谈元不计谁精。"]},{"t":"仆家徽之篁墩有晋循吏陈忠臣之祠第在焉土人尝更名黄以避巢贼之荼毒袭称至今仆近复篁墩之号而翰长镜川先生作十绝非之仆亦未敢以为是也谨次韵随章奉答幸终教之 其三","f":"七言绝句","c":["贼巢能识识中文，亥豕宁无辨几分。","珍重墩头贤父老，果然谈笑却秦军。"]},{"t":"仆家徽之篁墩有晋循吏陈忠臣之祠第在焉土人尝更名黄以避巢贼之荼毒袭称至今仆近复篁墩之号而翰长镜川先生作十绝非之仆亦未敢以为是也谨次韵随章奉答幸终教之 其四","f":"七言绝句","c":["璞也全身朴受诛，怜宗终复胜怜儒。","仙芝正作诸戎首，何怪蕲黄血满衢。"]},{"t":"仆家徽之篁墩有晋循吏陈忠臣之祠第在焉土人尝更名黄以避巢贼之荼毒袭称至今仆近复篁墩之号而翰长镜川先生作十绝非之仆亦未敢以为是也谨次韵随章奉答幸终教之 其五","f":"七言绝句","c":["难将疑似幸全宗，毕竟篁黄字不同。","黠盗关心生杀处，岂应无语过湘丛。"]},{"t":"仆家徽之篁墩有晋循吏陈忠臣之祠第在焉土人尝更名黄以避巢贼之荼毒袭称至今仆近复篁墩之号而翰长镜川先生作十绝非之仆亦未敢以为是也谨次韵随章奉答幸终教之 其六","f":"七言绝句","c":["王谢墩名一任谁，故园黄竹我须知。","金盘华屋杨家果，此说方应是可疑。"]},{"t":"仆家徽之篁墩有晋循吏陈忠臣之祠第在焉土人尝更名黄以避巢贼之荼毒袭称至今仆近复篁墩之号而翰长镜川先生作十绝非之仆亦未敢以为是也谨次韵随章奉答幸终教之 其七","f":"七言绝句","c":["胜地蒙污自不该，岂嫌舆隶爱公台。","片言祗欲求今是，何姓非从古圣来。"]},{"t":"仆家徽之篁墩有晋循吏陈忠臣之祠第在焉土人尝更名黄以避巢贼之荼毒袭称至今仆近复篁墩之号而翰长镜川先生作十绝非之仆亦未敢以为是也谨次韵随章奉答幸终教之 其八","f":"七言绝句","c":["轩皇何处有丹池，万仞黄山踞歙黟。","墩与此山元异脉，有灵应笑客何为。"]},{"t":"仆家徽之篁墩有晋循吏陈忠臣之祠第在焉土人尝更名黄以避巢贼之荼毒袭称至今仆近复篁墩之号而翰长镜川先生作十绝非之仆亦未敢以为是也谨次韵随章奉答幸终教之 其九","f":"七言绝句","c":["篁竹无言阅岁华，倚墩宁欲逞豪夸。","如言实重名非重，应笑人间复姓家。"]},{"t":"仆家徽之篁墩有晋循吏陈忠臣之祠第在焉土人尝更名黄以避巢贼之荼毒袭称至今仆近复篁墩之号而翰长镜川先生作十绝非之仆亦未敢以为是也谨次韵随章奉答幸终教之 其十","f":"七言绝句","c":["愧是忠良一派孙，笔锋常欲讨无君。","不忘祖武思绳处，第一当从此地论。"]},{"t":"题画册四时小景 其一","f":"五言绝句","c":["㶁㶁涧中泉，依依道傍柳。","塔院午钟声，随风出山口。"]},{"t":"题画册四时小景 其二","f":"五言绝句","c":["爱此玉泉水，携琴访翠微。","入城山下路，一任旱尘飞。"]},{"t":"题画册四时小景 其三","f":"五言绝句","c":["草阁最宜秋，况对丹枫渚。","翛翛麋鹿群，谁宾复谁主。"]},{"t":"题画册四时小景 其四","f":"五言绝句","c":["一夜溪山雪，乾坤似玉壶。","捲帘孤坐处，佳境入诗无。"]},{"t":"谒陵憩土城瑞光寺候李符台同行","f":"五言律诗","c":["日下土城根，夷犹古寺门。","水声墙外急，人影树中繁。","燕蓟诸关拥，金元一望存。","可人期不至，马上共谁论。"]},{"t":"道中","f":"七言律诗","c":["年年来作朝陵使，处处曾留纪胜题。","傍水人家随远近，入山神路隔东西。","日高午店炊应熟，云散秋城望不迷。","遥想同袍新寓宿，庙门高树马群嘶。"]},{"t":"下陵与李学士宾之联句","f":"七言律诗","c":["夜下西陵月露凉，归心偏逐马蹄忙。","迂途忽转行宫右，佳气犹瞻寝殿旁。","老树几枝低拂帽，秋岚一抹远侵裳。","昌平未到东方白，咫尺蓬山万里长。"]},{"t":"赠李士敬锦衣借其梦中旧韵","f":"七言律诗","c":["相门才子好谈兵，宝匣长闻一剑鸣。","露布已宣平寇策，凯歌频奏入关行。","古穰世远流新泽，仙李春深发旧萌。","珍重百年文献在，好将忠孝答恩荣。"]},{"t":"李符台宅暑夜","f":"五言律诗","c":["广庭堪避暑，槐幕正当轩。","凉吹梢头发，疏星叶罅翻。","忽惊羁思杳，转觉市声烦。","此夕行窗梦，遥应入故园。"]},{"t":"王封君哀挽","f":"七言古诗","c":["闻说方瞳似水清，正宜高卧享松龄。","金茎忽尽仙人露，玉宇空瞻处士星。","李白跨鲸游未返，庄周成蝶梦难醒。","烟霞痼疾谁堪疗，月旦遗风尚可听。","压座词章轻白雪，及门声价起青萍。","教条严胜师儒馆，乡约公于守令厅。","尘里冠缨长谢手，山间丘壑自忘形。","延交屡结新诗垒，睦族重开旧谱亭。","作赋不惭心似铁，守箴能戒口如瓶。","阶盈兰玉人夸谢，城隔芙蓉主换丁。","悲入夜阑鱼钓冷，坐看春尽鹿车停。","歌郎泪下风中烛，吊客魂销雨后铃。","滚滚年光嗟化鹤，飘飘身事等流萤。","丰姿彷佛惟馀画，手泽分明却在庭。","百岁难酬鸿鹄志，九霄先振凤凰翎。","朝行渐已登三事，家训由来本一经。","牲鼎几回供祖庙，丝纶重叠下王廷。","社中拟入先生祀，冢上还劳太史铭。","枫树落霜天冉冉，蘋花摇日水泠泠。","怀贤定有观风使，下马时来问典刑。"]},{"t":"送象山凌尹汝聘","f":"七言律诗","c":["象山山下旧名疆，羡子承恩握县章。","到日拥舟潮水白，行边吹马旱尘黄。","可堪奉檄人千里，正见忧民诏十行。","老学平生须大展，青云高躅看腾骧。"]},{"t":"题四美人图 其一 琴","f":"七言绝句","c":["绿绮初调曲未残，幽情应叹赏音难。","不嫌儿女声相昵，一鹤长鸣绕画阑。"]},{"t":"题四美人图 其二 棋","f":"七言绝句","c":["玉子频拈欲下迟，芭蕉红日影将移。","锦绷儿共金丝犬，问道输赢两不知。"]},{"t":"题四美人图 其三 书","f":"七言绝句","c":["倦来携手下阶行，共读周南几句成。","庭桂香中无一事，閒听公子击毬声。"]},{"t":"题四美人图 其四 画","f":"七言绝句","c":["促织场边爽气新，彩毫轻染墨华匀。","香闺不爱千红紫，只写青松与翠筠。"]},{"t":"次韵寄松江张隐君 其一","f":"七言律诗","c":["丈人零落晓星馀，张老犹堪载后车。","烛目锦云盘一诰，随身明月动双琚。","君门拟上承恩颂，官舍时翻训子书。","暂出还归应有道，不劳猿鹤怨郊居。"]},{"t":"次韵寄松江张隐君 其二","f":"七言律诗","c":["都城相别几年馀，何日追随长者车。","旧语有缘陪玉屑，新诗无力报琼琚。","山中酒熟长开社，海上鸿归一寄书。","白发可能忘帝力，时应飞梦绕宸居。"]},{"t":"出班政门渡济川桥行南山脚逢梅","f":"七言律诗","c":["风吹晴色晓初开，春入郊原绿渐回。","华扁尚馀班政额，危梁谁复济川材。","舟随雪浪穿桥过，人拂烟霏下岭来。","忽有异香生眼■，野塘斜映一株梅。"]},{"t":"山斗宗人汝翼率族众燕予于世忠行祠是日雨山斗以其所居之前有山如覆斗形故名","f":"七言律诗","c":["世忠祠下绮筵开，一族相驩重我来。","别久漫论新旧雨，情长难尽浅深杯。","好山覆斗全胜画，乔木凌云不易栽。","胜地百年今未启，后生当有出群材。"]},{"t":"大雨雪过黄茅山吴知州克宽邀宿","f":"七言律诗","c":["迢迢石径入林端，未到黄茅力已殚。","鸟啄亦愁泥滑滑，雨声如竞雪漫漫。","剡溪兴尽真须返，蜀道歌成未是难。","烟火望中知不远，主人邀宿有馀欢。"]},{"t":"度扶车岭将至大坂寄汪希颜佥宪","f":"七言律诗","c":["九仞峰头一线陉，东风残雪尚冥冥。","泉声可入宫商谱，山色真开紫翠屏。","族数程汪今共盛，路当休婺此分停。","一言鸡黍能成约，宾主谁当眼倍青。"]},{"t":"小憩三宝寺寺碑乃黄秋江处士立蔡国公张圭书","f":"五言律诗","c":["何代精严境，门当水阁虚。","烟迷黄叟宅，云锁蔡公书。","田舍春声在，人家劫火馀。","不堪山下路，横木碍肩舆。"]},{"t":"大坂行一首奉挽汪隐君夫妇并赠其子佥宪希颜","f":"七言古诗","c":["大坂之山多桧松，大坂之水多鰅鳙。","采山钓水无异姓，只有汪氏称名宗。","汪氏之先本王子，靖乱尤能保终始。","后来亦有唐端公，遂与州民共生死。","两公庙食八百年，云礽何止人三千。","出者处者恒有道，往往读书并力田。","迩来积庆谁堪数，一族咸推佥宪父。","父耕子读两无惭，那更深闺有慈母。","当今天子明孝人，每下恩典旌贤臣。","九原伉俪虽莫作，高堂五采明丝纶。","我观汪氏庆未己，科第联翩一时起。","叔侄兄弟凡六人，冠盖如云照墟里。","大坂水清山更奇，中有汪家双墓基。","他时添取石翁仲，为尔重书先德碑。"]},{"t":"题汪玺贡士四禽图 其一","f":"五言绝句","c":["春风海上桃，仙禽托栖止。","莫啄千叶花，留结千年子。"]},{"t":"题汪玺贡士四禽图 其二","f":"五言绝句","c":["何处青丝禽，飞来一枝托。","回首啄山茶，霏霏露华落。"]},{"t":"题汪玺贡士四禽图 其三","f":"五言绝句","c":["有鸟名翠碧，无花艳海棠。","依依留不去，颜色两相当。"]},{"t":"题汪玺贡士四禽图 其四","f":"五言绝句","c":["娟娟蜡啄鸟，挺挺当风立。","斜压一枝低，寒梅冻无力。"]},{"t":"大坂往返得诗十绝 其一 观文公与内弟程允夫手书真迹","f":"七言绝句","c":["渊源家学重师生，中表姻亲本弟兄。","物是人非三百载，一缄残墨两含情。"]},{"t":"大坂往返得诗十绝 其二 观尚书汪文节公真迹","f":"七言绝句","c":["百代乡邦有此翁，每于青史叹遗忠。","片言只字须珍护，留取高风配鲁公。"]},{"t":"大坂往返得诗十绝 其三 观云阳李一初先生真迹","f":"七言绝句","c":["前人往往爱钟王，才落霜毫趣便长。","颇怪一时文翰谱，风流犹欠李云阳。"]},{"t":"大坂往返得诗十绝 其四 初识黄世瑞","f":"七言绝句","c":["倒峡词长立意精，几凭春雁寄都城。","相闻十载今相见，一夜论文及四更。"]},{"t":"大坂往返得诗十绝 其五 汪处士士魁家观罗明仲洗马抑斋记","f":"七言绝句","c":["洗马文章举笔成，可人能尽抑斋名。","小楼对酌几忘味，无限停云万里情。"]},{"t":"大坂往返得诗十绝 其六 端公祠端","f":"七言绝句","c":["大坂溪头寝庙开，端公香火百年来。","一时孙子能绳武，豸绣同登内外台。"]},{"t":"大坂往返得诗十绝 其七 观高庙与枢密汪公手书真迹","f":"七言绝句","c":["午夜虹光烛斗寒，人间惊得御书看。","当时未定君臣礼，想见先皇创业难。"]},{"t":"大坂往返得诗十绝 其八 观蓉峰先生存藁","f":"七言绝句","c":["满架遗书墨尚新，立言真不愧先民。","后生学问曾何似，也作青宫辅导臣。"]},{"t":"大坂往返得诗十绝 其九 汪希大追送予至鳙溪上","f":"七言绝句","c":["君从城郭几时还，知我肩舆夜过山。","多谢有情思晤语，五更追送到溪湾。"]},{"t":"大坂往返得诗十绝 其十 小憩汪口饭上舍俞俊家","f":"七言绝句","c":["汪口人家鸡乱鸣，一樽那尽故交情。","门前溪水能相送，随我西流直到城。"]},{"t":"文公阙里谒后有作","f":"七言律诗","c":["洛水初传道己南，后生何幸此庭参。","一时气数存虹井，万古仪刑仰晦庵。","尘锁断碑馀劫火，山围新庙拥祥岚。","正心诚意言犹在，三复无能祗自惭。"]},{"t":"予过婺源宿万寿僧舍住僧敬公有望云思亲图求予诗因为下一转语","f":"古风","c":["朝看云出岫，暮见云归山，禅心正与云相閒。","如何对此生意见，思亲不觉伤朱颜。","佛法无生亦无死，割爱先从二亲始。","上人却有望云心，善学宁惭鲁男子。"]},{"t":"丁大尹燕予于万寿僧舍","f":"七言律诗","c":["肩舆五日到星源，握手斯文喜晤言。","门掩夜灯初下榻，筵开春雨正当轩。","僧来供茗饶风味，客起投壶杂笑喧。","知是政成多暇日，几人能却簿书烦。"]},{"t":"离婺源留别诸士友","f":"七言绝句","c":["僧房连日阻春霖，款意难胜别意深。","但得三农今岁饱，沾裳濡足也甘心。"]},{"t":"道中寄婺源陈教谕","f":"七言律诗","c":["星源人喜得良师，桃李春风盛一时。","荐达屡辞陈瓘疏，经营多葺晦翁祠。","情深酌我红灰酒，和寡劳君白雪词。","珍重雅怀难别处，板桥东下雨丝丝。"]},{"t":"节庵倪先生以经学教于乡既成其子进贤举进士为御史又出其馀以淑乡之人其在德兴孙司马之塾最久予过婺源望先生之庐尚远不能往拜漫成一律奉寄","f":"七言律诗","c":["鹤发朱颜笑语温，隐君遥在水云村。","诸生久立尚书馆，一子新开御史门。","丹灶药垆堪逸老，锦衣乌帽待承恩。","传经谁复倪宽在，借榻无因听一论。"]},{"t":"夜宿芙蓉岭下野寺梦京师起坐有怀","f":"五言古诗","c":["往岁红尘里，常时梦岩穴。","今夜青山中，忽尔梦京阙。","人生无定止，出处心自知。","起坐耿不寐，山雨鸣空墀。","永怀千载人，小范不可作。","岂无天下忧，敢慕一身乐。","行年将四十，于世宁有闻。","终当谢君宠，归卧南山云。"]},{"t":"过五岭","f":"七言律诗","c":["览胜心雄力未疲，不愁云路转逶迤。","上当华岳扪参处，下抵虞渊取日时。","鬼斧有灵方可凿，画工虽巧竟何施。","我来亦乏惊人句，未敢磨崖与斗奇。"]},{"t":"还过山斗遇雨宿以章宗侄家","f":"五言律诗","c":["因过星水路，重宿斗山堂。","旅次晨炊晚，宗盟夜语长。","阴晴无日定，来往笑人忙。","尘鞅何时解，同倾竹下觞。"]},{"t":"新安人以析居为常事独吾山斗宗人周生兄弟同爨至今可嘉也其家有集秀堂予为之作歌","f":"古风","c":["堂上覆斗山，堂下五城水，争羡君家好兄弟。","紫荆根固踰百年，棠棣花开香十里。","呜呼弟兄如鼎足，那忍相倾覆。","其餗紾尔臂、阋尔墙，寄言莫上君家堂。"]},{"t":"雨中访黄世瑞于古林","f":"七言律诗","c":["官路东来一径斜，不辞冲雨到君家。","古林岁久饶松子，后圃春深长菜花。","为惜病身初戒酒，欲清吟骨旋呼茶。","何时遂结青山社，静与幽人阅岁华。"]},{"t":"二月二十六日南山雨中晚归","f":"七言律诗","c":["小驻肩舆野水滨，轻雷将雨酿花辰。","板桥中断春溪涨，竹筏遥呼晚渡人。","云气黑催诗思远，江峰青入画图匀。","乘时剩结渔樵侣，少答君恩便乞身。"]},{"t":"希仁宗贤来自泾适春霖不已三月二日稍霁遂同至南山小酌时古林黄世瑞与俱","f":"七言律诗","c":["几日春霖出未能，溪园新霁兴堪乘。","鸠憎个个鸣当屋，麦喜家家绿覆塍。","古渡唤舟烦野老，花辰开宴得良朋。","青山入望多佳处，杖策何时约共登。"]},{"t":"新安旧有二程先生祠荷侍御提学娄公克让许修复之偶于婺源陈简教谕处得克让往年过博野祠下之作因借韵一首奉寄","f":"七言律诗","c":["伊水渊源出未穷，故乡尸祝礼何丰。","能崇命世真儒庙，全仗分司御史功。","伫见门墙登士子，岂徒伏腊走村翁。","他时胜迹书图志，定把新安比洛崇。"]},{"t":"春草便面为汪思恭题","f":"古风","c":["趣在窗前不剪，梦从池上初归。","但觉光风到手，犹疑清露沾衣。"]},{"t":"清明前一日至南山","f":"七言律诗","c":["一夜春溪落涨痕，不知春色遍郊原。","青山麦垄东西坂，流水桃园上下村。","鹿迹半惊樵客过，禽声如答路人言。","举头不觉先茔近，两两乔松护石门。"]},{"t":"赠新太守王公公名哲起侍御守广平凤阳二郡今易地新安","f":"七言律诗","c":["朱幡摇曳入新安，夹道驩呼老豸冠。","初政欲随春雨足，先声犹带旧霜寒。","人传遗爱仍思寇，自幸疏慵久识韩。","看取名增循吏传，紫阳山色共㠝岏。"]},{"t":"新推府陈公良至任以久雨弗克趋贺有传其诗章至休宁者因借韵奉赠","f":"七言律诗","c":["苦雨蓬门只自关，几回思见紫芝颜。","野桥水力频增涨，石路苔痕久上班。","入境便闻声价重，登堂能遣簿书閒。","锦囊剩有新珠玉，一夜流传到碧山。"]},{"t":"三月二十六日寿于千户八十","f":"七言律诗","c":["辕门齿德重新安，颜色如童发未残。","秋水深藏三尺剑，春风初试九还丹。","佳辰谢客心能静，老境看孙梦亦驩。","愿把庄椿祝君寿，八千遐算此开端。"]},{"t":"题宗人贡士迪所藏米画","f":"七言绝句","c":["襄阳人物渺如烟，画里云山尚宛然。","珍重旧宗收拾在，风流如坐米家船。"]},{"t":"饮张挥使家观戏","f":"七言律诗","c":["牡丹花折柳丝匀，雨后高堂不动尘。","武卫昼閒军令肃，家筵春启客情真。","锦棚曲奏温州调，银瓮香传采石春。","为重雅怀分席晚，不知明月照归人。"]},{"t":"宗老学可世居歙东关正统中先公奉使新安学可尝邀至其家南轩同卧七日今且四十年矣重登此轩为之惘然","f":"七言律诗","c":["咫尺东关路不遥，先人曾此驻星轺。","阮南有谱通三族，姜被多情共七宵。","过隙时光惊迅速，对窗山色尚岧峣。","感今怀古心无限，郢曲难成酒易消。"]},{"t":"刘挥使宅在南城下新起西楼予将题之曰揽胜先拟寄之","f":"七言律诗","c":["危楼新起傍高城，脱洒红尘眼倍明。","一塔穿云当砥柱，四山飞翠入檐楹。","吾伊夜课兵书读，睥睨时分武队行。","何日画阑重徙倚，彩毫浓墨为题名。"]},{"t":"题宗老文彬南薰轩追和刘邦彦韵","f":"七言律诗","c":["水色山光聚一轩，飞尘全不到吟边。","华胥剩喜身能乐，褦襶生憎客未贤。","石鼎茶香消永日，朱弦声妙入钧天。","老来心地凉如水，且把蒲葵壁上悬。"]},{"t":"予成化戊戌岁蒙恩省觐取道绩溪入徽城今五年矣复行此途怆然有感","f":"七言绝句","c":["再出东城思惘然，青山依旧绕长川。","昼游追及承恩日，屈指浮生又五年。"]},{"t":"过新馆铺宗老彦举邀宿其家别墅彦举尝从征湖南有义征图卷今老矣喜长生之说得其要领","f":"七言律诗","c":["水围村郭树扶疏，宗老相留兴不孤。","晚景颜华仙授箓，壮年心事义征图。","旋开酒令随乡俗，细剪灯花说帝都。","他日尘中应忆此，可胜清梦绕鱼凫。"]},{"t":"饮孙挥使家别后有作","f":"七言律诗","c":["相见劳君两日留，重君儒雅异凡流。","家藏韬略从先祖，世袭金绯似列侯。","客宴赏春看打马，军门防夜听传筹。","八方无事征书少，赢得清閒坐歙州。"]},{"t":"过临溪曹渡二石桥桥皆殷氏所修尝求予记","f":"七言律诗","c":["众水同归一水东，行人常此叹途穷。","山腰远近过三舍，波面参差卧两虹。","刻石浪传脩史笔，挥金谁续济川功。","殷家尚义真难事，赢得芳声满歙中。"]},{"t":"留题绩溪","f":"五言古诗","c":["绩溪东南来，遥望古仁里。","中有程氏居，隐隐入桑梓。","缅怀道轩翁，吾宗百世士。","眼中聚爱楼，遗训耿在耳。","三男如鼎足，等是克家子。","崇坊瞰村巷，华构照山址。","春霖久初晴，一榻为予启。","登堂父兄乐，拥户儿童喜。","开奁扣宗牒，张燕出肴醴。","夜下灯火明，语笑未能已。","忆当百年前，同饮相湖水。","今夕乃何夕，会晤复自此。","聚散安可常，保族在崇礼。","丁宁愿同人，契谊笃终始。","明发川途长，思情两难拟。"]},{"t":"贡士佐时生子弥月予适至焉初予以诗寿新安千户于翁八十翁以锦帕为谢因以遗儿用为远寿之徵","f":"七言绝句","c":["鲛绡一幅锦云红，得自新安八十翁。","虽愧犀钱并玉果，愿儿遐寿与翁同。"]},{"t":"登源有汪王祖齐司马墓及王庙庙后有绿照亭有石洞用故侍郎朱大同先生韵示同游仁里诸宗人","f":"七言律诗","c":["千载吾王此旧都，登源流水绿成湖。","断碑丘垄收云气，长剑风尘忆壮图。","山隔游亭闻绿照，云封仙洞似蓬壶。","联镳英俊来应惯，路转峰回不问途。"]},{"t":"未至普照寺道中作","f":"七言律诗","c":["石梁湾曲水沉沉，路下峰腰半不禁。","风外茶烟知寺近，云中鸡唱觉村深。","病多宜享山林福，才薄难胜利济心。","且为渔樵增故事，临流先续采芝吟。"]},{"t":"游普照寺观石镜相传黄巢过此照其形为异类因纵火焚之久乃复明苏子由宰绩溪日尝有留题石刻今不存矣","f":"七言古诗","c":["高崖直下如削铁，不识何年鬼工截。","巧令中有鉴光寒，万古照人长不灭。","绿苔半锁苍藤封，雾雨不晦天然铜。","禅家意巧作幻境，邻近便起空王宫。","泗滨浮石曾充磬，明者何妨堪作镜。","玉蕴山辉古则然，此论行时众方定。","颇闻巢贼窥山城，虐燄一日昏其明。","杀心久已变豹虎，何怪照出非人形。","我来适当春雨后，老僧立话徘徊久。","小苏旧迹今已亡，惟有遗诗在人口。","东风萧萧吹瘦颜，笑复摩挲对面看。","山灵可解知人意，照见胸中一寸丹。"]},{"t":"仁里宗侄素时日侍予于聚爱楼又从游石镜诸处胜地情意勤款与他宗人不同时予将重脩统宗世谱且欲编石镜古今题咏以素时之博学好古也两以属之素时其尚有以副予之志哉","f":"七言律诗","c":["年来常动竹林思，一见偏怜海鹤姿。","古寺芒鞋春眺日，高楼灯烛夜谈时。","统宗再续篁墩谱，纪胜新编石镜诗。","知子有才堪订约，双鱼相寄莫相辞。"]},{"t":"游问政山至兴道观","f":"七言律诗","c":["薰风初试旧轻纱，越岭穿崖一径斜。","雾里楼台成海市，云中鸡犬类仙家。","欲尝风味频供笋，未解春酲只唤茶。","谏议真人都不见，独留荒冢对繁花。"]},{"t":"游白水寺","f":"七言律诗","c":["几曲晴纱不受尘，望中云近绿杨津。","峰腰屏足疑无地，谷口闻声忽有人。","静爱寺山青隐隐，圣传池水白粼粼。","同来宗契兼乡契，病酒无妨更一巡。"]},{"t":"游水西太平诸寺","f":"五言律诗","c":["胜日须行乐，联镳过水西。","桐花嘶騕袅，松树隐招提。","碎月滩声在，披云黛色迷。","老僧谈故迹，随处可留题。"]},{"t":"游紫阳山寻许宣平金野仙二真遗迹次旧韵二首 其一 和宣平韵","f":"五言律诗","c":["屋踞苍崖下，人行老树颠。","寻诗敲翠竹，消醉饮清泉。","歌出黄牛背，帆飞白鸟前。","尘缨犹未洗，结社在何年。"]},{"t":"游紫阳山寻许宣平金野仙二真遗迹次旧韵二首 其二 和野仙韵","f":"七言律诗","c":["一峰孤耸碧孱颜，琳馆遥当紫翠间。","桑坞日斜鸡唱晚，松庭风静鹤声閒。","轩辕丹熟惟馀井，太白诗高可配山。","吟眺未胜天渐暝，兴随流水不知还。"]},{"t":"游万山观","f":"五言律诗","c":["何代迎仙地，高低复起楼。","东明先得日，西爽最宜秋。","帆影林梢见，岚光脚下流。","道人吹铁笛，飞思绕瀛洲。"]},{"t":"赠程都纪宗贵宋相文清公之裔藏有先世诰牒","f":"五言律诗","c":["住是真仙宅，宗传旧相家。","丝纶惊岁月，楼阁俯烟霞。","散局敲棋子，轻瓯泛茗花。","不知归兴懒，高树集昏鸦。"]},{"t":"赠刘太古","f":"五言律诗","c":["潇洒刘太古，绝似鲍参军。","老去诗还健，情多酒未醺。","疏髯飘乱雪，长啸遏行云。","何日开春社，岩花约共分。"]},{"t":"因与于文远郑时清同步东城上晚归得诗六绝 其一 越国汪公庙唐诰","f":"七言绝句","c":["乌聊山上越公祠，香火分明百世思。","留得两函唐诰在，纪年犹是太宗时。"]},{"t":"因与于文远郑时清同步东城上晚归得诗六绝 其二 东岳庙","f":"七言绝句","c":["岳祠园后见崔嵬，玉立亭亭一径回。","争扫碧苔供徙倚，不妨同醉竹根杯。"]},{"t":"因与于文远郑时清同步东城上晚归得诗六绝 其三 傍溪寺晚眺","f":"七言绝句","c":["宝坊高出旧城东，百里山川一望中。","竟日倚阑题不尽，夕阳遥射竹林红。"]},{"t":"因与于文远郑时清同步东城上晚归得诗六绝 其四 斗子山问高庙驻兵处","f":"七言绝句","c":["石址犹存旧将台，青山如斗画中开。","至今草木增颜色，知是先皇驻跸来。"]},{"t":"因与于文远郑时清同步东城上晚归得诗六绝 其五 天宁寺观枯杉相傅五圣化生于此树上","f":"七言绝句","c":["枯杉如柱倚天长，云是神人此降祥。","欲借图经询故实，定应何似古空桑。"]},{"t":"因与于文远郑时清同步东城上晚归得诗六绝 其六 杨氏祠堂观司寇先生遗像","f":"七言绝句","c":["廊庙丰姿太逼真，追思言笑转伤神。","一时先友凋零尽，不忍重来抚翠珉。"]},{"t":"宿闵口毕氏三绝 其一","f":"七言绝句","c":["山围华屋水当门，乔木森森绿护村。","白雪调高人和寡，风流还待毕公孙。"]},{"t":"宿闵口毕氏三绝 其二","f":"七言绝句","c":["秀水城东学士阡，寸心常绕瓣香前。","闻君当日曾相见，屈指流光二十年。"]},{"t":"宿闵口毕氏三绝 其三","f":"七言绝句","c":["方瞳炯炯发丝丝，每日山中赋采芝。","有约未成同甲会，因君无限望云思。"]},{"t":"与闵口临溪汊川三族人同登东密岩观远祖中丞公起兵拒黄巢处晚宿岩下方兴寺与汊川宗人逸民用光联句二首 其一","f":"七言律诗","c":["家山乘兴一来游，万仞峰颠日未收。","疑帜久空唐将壁，残钟时起梵王楼。","穿云石磴萝阴合，过雨林峦黛色流。","吟屐忽随归马散，天风吹袂晚飕飕。"]},{"t":"与闵口临溪汊川三族人同登东密岩观远祖中丞公起兵拒黄巢处晚宿岩下方兴寺与汊川宗人逸民用光联句二首 其二","f":"七言律诗","c":["东岩岩下古招提，四面阴森竹树齐。","山翠入帘朝过雨，炊烟拖巷午闻鸡。","老僧延坐劳清供，词客留诗续旧题。","话久不知鸣晚鼓，暂分禅榻伴幽栖。"]},{"t":"饮汊口宗家语次偶赋","f":"七言律诗","c":["流水溅溅石路平，几年鸡黍约初成。","古芸绕架香还盛，乔木当年老更荣。","招隐不惊探虎穴，忘机偏解结鸥盟。","斜阳未尽渔樵话，刻竹题诗寄此情。"]},{"t":"端午饮汊口汪端家忽记京华旧事","f":"七言律诗","c":["紫云溪上作端阳，忽记前年黼座傍。","分艾特颁宫样虎，侑尊时出上供羊。","綵丝系臂饶恩露，聚扇回风带御香。","抚景不堪惊岁月，愧无才力报君王。"]},{"t":"云水山房","f":"五言古诗","c":["杖策云溪上，濯足云溪下。","由来故王孙，却是忘机者。","仰看鸢戾天，俯见鱼潜渊。","欲悟动静理，日到云溪边。","溪云时卷舒，溪水可厉揭。","珍重溪居人，斯言或相契。"]},{"t":"集古八绝 其一 汊口","f":"七言绝句","c":["二水中分白鹭洲，人家多住竹棚头。","眼前有景道不得，长夏江村事事幽。"]},{"t":"集古八绝 其二 赠汊口诸宗人","f":"七言绝句","c":["文武衣冠异昔时，惠连群从总能诗。","东园载酒西园饮，药饵扶吾随所之。"]},{"t":"集古八绝 其三 赠逸民用光","f":"七言绝句","c":["清风明月两閒人，何用浮名绊此身。","闭户著书多岁月，野花啼鸟一般春。"]},{"t":"集古八绝 其四 晚步云溪上","f":"七言绝句","c":["山屐经过满径踪，閒来无事不从容。","白沙翠竹江村路，云碓无人水自舂。"]},{"t":"集古八绝 其五 夜宿用光南窗下","f":"七言绝句","c":["门外青山如屋里，嘈嘈虚枕纳溪声。","怪来诗思清人骨，欲化西园蝶未成。"]},{"t":"集古八绝 其六 谒忠壮行祠","f":"七言绝句","c":["松花风煖庙门开，百亩庭中半是苔。","怅望千秋一洒泪，安危须仗出群材。"]},{"t":"集古八绝 其七 拜端明公墓","f":"七言绝句","c":["苑边高冢卧麒麟，曾是贞元花下人。","人世几回伤往事，碑文才见满埃尘。"]},{"t":"集古八绝 其八 望岩将公墓","f":"七言绝句","c":["流水溅溅度两陂，旅坟三尺近要离。","鸟啼花发人何在，一剑曾当百万师。"]},{"t":"寿榆村宗老以顺义官七十九岁","f":"七言律诗","c":["人生难得古稀龄，况乃重看九度蓂。","庆衍芝兰盈谢砌，义沾恩宠出尧庭。","卷舒任我心何累，饮啖兼人体自宁。","遐算定同师尚父，榆川山色共青青。"]},{"t":"兖山汪处士世宁留宿予适有事辞归别后寄此","f":"七言律诗","c":["越国勋名重有唐，兖山家法冠诸汪。","主人有道开鸥社，子姓无哗列雁行。","李白拟尝新竹酝，陈登空扫旧藤床。","两怀不尽忙相别，咫尺停云万里长。"]},{"t":"黄坑寺","f":"七言律诗","c":["一坞深深竹树长，梵宫遥枕碧山冈。","废兴屡换新碑石，俎豆犹存旧寝堂。","为祝慈龄参佛母，敢将诗病叩医王。","清谈未了匆匆去，不尽毗那一瓣香。"]},{"t":"率口族人燕予世忠行祠","f":"七言律诗","c":["忠壮行祠率水边，锦屏银烛夜张筵。","祖宗望出南朝上，子姓分当北宋前。","谈麈频挥人似雨，劝筹交错酒如泉。","相违记取重逢日，万里鸥波解绶年。"]},{"t":"黄石谒太母庙","f":"五言律诗","c":["黄石丛祠在，人传太母名。","子功全故国，神鉴定佳城。","香火千家盛，冠裳八座荣。","阃仪谁有此，瞻拜不胜情。"]},{"t":"饮率东族家","f":"七言律诗","c":["路入方山一里强，百年程氏率东房。","教条半出朱隆隐，家法多宗郑浦阳。","庭户各分乔木影，图经犹带旧芸香。","花前棋局灯前酒，无限宗盟夜坐长。"]},{"t":"题钖山孙王庙","f":"七言律诗","c":["庙食青山岁月长，居人多未识孙王。","江东讨逆功初著，许下迎銮志莫偿。","一代英豪存太史，三分名节愧元方。","何当订入新图志，祀典分明重此乡。"]},{"t":"宿坑口孙启先生家次韵时予以疾戒饮故诗及之","f":"七言律诗","c":["前辈风流杳莫俦，近来人物数谁优。","閒心坐与鸥盟狎，世态看同蜃气浮。","无分清尊开北海，有情吟榻借南州。","掀髯久欲闻长啸，明月何时共倚楼。"]},{"t":"过郑公钓台","f":"七言古诗","c":["相公湖边一拳石，截断湖光三百尺。","射蛟人去今几年，谁扫云根看遗迹。","师山先生性爱山，偶然得此青孱颜。","临流坐钓不知晚，渔樵并载扁舟还。","武威余公天下士，特与先生题篆字。","良工刻入断崖傍，遂使溪山增胜事。","一朝海内风尘生，两公死国如弟兄。","平生隐显虽异迹，竹帛同垂千载名。","薰风雨过潮初落，足蹑苍苔俯幽壑。","钓丝已逐野烟飞，字画多为古藤络。","师山之节峻且孤，武威之字人争摹。","忠贤所遗众所宝，泉石清奇何处无。"]},{"t":"题唐十八学士登瀛图","f":"七言律诗","c":["冠冕分明见盛唐，百金谁购宋宫藏。","山人妙绝丹青手，学士名高翰墨场。","千里忽惊雷剑合，十年空叹楚弓亡。","摩挲手泽真非偶，抚卷令人羡紫阳。"]},{"t":"予访王氏子仁泰于泽富仁泰适以是日生男时予方以疾断酒为之喜而破戒赋诗赠之","f":"七言律诗","c":["深巷方停下泽车，便惊佳气蔼庭除。","数声喜报檐前鹊，一颗光呈掌上珠。","兆应熊罴来梦日，庆随弧矢上门初。","因君破戒重开酒，佳话流传遍里闾。"]},{"t":"过余岸拜远族祖宋枢密","f":"七言律诗","c":["高坟山下几经春，曾是先朝执政臣。","甲第儿孙惊异县，梵宫香火幸比邻。","金貂入像图应在，石兽分行迹未陈。","同出相湖惭后学，不堪追仰荐溪蘋。"]},{"t":"邵村张氏子茂植年十二俊颖可爱其父才遣从予游以其尚幼俾先之于塾师俟少长则收而教之且勖以诗","f":"五言律诗","c":["楚楚青年子，明明玉树枝。","少仪须读礼，多识贵闻诗。","乔木云霄迥，良苗雨露滋。","执经函丈下，看尔出群时。"]},{"t":"题汪本仁处士耕读轩","f":"古风","c":["小结幽轩傍水涯，此中耕读两相宜。","欲求莘野千年志，乐诵豳风一卷诗。","春垄短蓑鞭??，夜窗明烛听吾伊。","老来达道应无及，付与名郎佐盛时。"]},{"t":"过岑山渡","f":"五言律诗","c":["势比焦山小，因名忆郑公。","江鼋浮水面，天狗堕云中。","舟楫东西过，渔樵上下通。","涉溪逢旧寺，尘虑偶然空。"]},{"t":"宿万山观六言四首 其一","f":"古风","c":["词客初停尘鞅，鍊师相约楼居。","赤日正过林樾，好风时到庭除。"]},{"t":"宿万山观六言四首 其二","f":"古风","c":["石磴盘回九折，山房小结三间。","酷暑因风尽扫，道心与鹤俱閒。"]},{"t":"宿万山观六言四首 其三","f":"古风","c":["灯影半窗冉冉，垆薰一炷亭亭。","多病思投白社，老人为说丹经。"]},{"t":"宿万山观六言四首 其四","f":"古风","c":["一派滩声东去，满空月色西流。","但觉梦游尘外，不知身宿山头。"]},{"t":"饮万山观东明楼赠道庸都纪","f":"七言律诗","c":["五月高楼暑气凉，捲帘山色动晴光。","病来喜服乌蛇酒，睡起频添宝鸭香。","堆案道经翻蕊笈，绕梁仙乐奏云簧。","何时解绶归林下，许借閒云宿半床。"]},{"t":"宗家贡士迪请诗送其友人还浙","f":"七言律诗","c":["见君几日送君归，梅雨纷纷湿苧衣。","来喜客舟重返浙，去惊乡语半从徽。","石榴庭院黄蜂入，水稻田塍白鹭飞。","揽胜他时还有约，莫辞尊酒暂相违。"]},{"t":"题于文远山水小景","f":"七言绝句","c":["望中疑是富登山，只欠危亭著树间。","记得摩厓看石篆，小舟曾泊相湖湾。"]},{"t":"道庸都纪城市山林卷次韵","f":"七言律诗","c":["上逼青霄下瞰城，来游何必羡登瀛。","风前不动旌幢影，云外时闻杵臼声。","盟狎海鸥机渐了，梦回蕉鹿世空惊。","丹房何日全相借，慰我吟身太瘦生。"]},{"t":"范蠡归湖图为师鲁侄题","f":"七言绝句","c":["万顷湖光足钓丝，济川功了乞归时。","安流不用施篙楫，敛手舷头任所之。"]},{"t":"云岚山汪王墓","f":"七言绝句","c":["六州已罢新开府，千载谁思旧使君。","只有云岚桥下路，行人能指越公坟。"]},{"t":"歙北有山曰飞布甚奇山下江氏世居之山旧有主簿庙以结兵禦寇之功而江氏实主其祀今江氏之老曰嗣器其家以殷实徙京师从子韶入为京学生尝及见予予过歙欲访江氏适以疾不果赋此寄之","f":"七言律诗","c":["一峰高耸碧嶙峋，一族相延几百春。","庙守甘棠思歙簿，家传乔木自江人。","幸瞻日月分馀照，渐觉诗书起后尘。","多病未酬鸡黍约，不辞题句托双鳞。"]},{"t":"宗侄贡士式之求诗寿岩镇方翁七十","f":"七言律诗","c":["七十年来气尚豪，红颜如画映霜毛。","佳辰满酿山中秫，晚岁曾餐海上桃。","童子喜提如意舞，老人光并少微高。","亲朋欲助长生颂，为染宣城玉兔毫。"]},{"t":"观槐塘远祖宋丞相文清公明良庆会卷次王而勉太守韵","f":"七言律诗","c":["丞相勋名重斗南，讲帷曾说旧师甘。","一时奏劄多忠谏，百世赓歌继美谈。","秦律乍除闻板荡，孔墙中坏得肜戡。","后生景行无穷意，敛手临风读再三。"]},{"t":"再观丞相奏议复次前韵","f":"七言律诗","c":["庙谟惟欲保东南，几许忠言主未甘。","分镇独馀唐未议，徙戎谁说晋清谈。","传家素节推杨震，去国高风忆孔戡。","留取百年遗荫在，当门槐幄尚成三。"]},{"t":"寄进士金溪尹黄硕夫","f":"七言律诗","c":["百年谭渡水声长，一郡犹传孝子黄。","不为病躯亲药饵，定瞻遗像设椒浆。","云礽又见承新宠，父老仍思立旧坊。","坐想昼游真得意，青山乔木总生光。"]},{"t":"题汪思恭松萝书屋 其一","f":"七言绝句","c":["饱看青山读古书，无人能识市中儒。","朝朝卖药归来晚，留得芸香辟蠹鱼。"]},{"t":"题汪思恭松萝书屋 其二","f":"七言绝句","c":["松萝门下筑书台，满架牙签一径苔。","常有新诗生眼■，不知山色近人来。"]},{"t":"题汪思恭松萝书屋 其三","f":"七言绝句","c":["王孙潇洒皂纶巾，独起高轩出市尘。","见说年来书更熟，门前常有问奇人。"]},{"t":"题汪思恭松萝书屋 其四","f":"七言绝句","c":["秘府图书阅半交，故园松菊可全抛。","何时更约开新社，与子山中共结茅。"]},{"t":"雨后与克俭弟联句","f":"七言律诗","c":["细雨生凉一院风，幽情多在小斋东。","草分秀色沿阶绿，葵吐秋花拂座红。","睡起焚香初谢客，吟馀思茗漫呼童。","隔林谁奏笙歌沸，预喜山城乐岁丰。"]},{"t":"题画","f":"古风","c":["墟落莫烟相望，板桥春涨初平。","未放渔家艇子，疑闻塔院钟声。"]},{"t":"七月神会饮福","f":"七言律诗","c":["金风初动月当申，萧鼓山堂乐赛神。","眼■光阴真过客，坐中人物半姻亲。","语因随俗多成笑，酒到忘怀不记巡。","相好不堪相别处，明年应忆宦游人。"]},{"t":"卜算子 题汪汝温便面","f":"古风","c":["草长沙露尖，风急波生绉。","两个渔郎任意行，不问谁先后。","纶竿腥乍收，饭甑香初透。","回首相呼好放船，正是潮生候。"]},{"t":"拜庆千秋节敬赋","f":"七言律诗","c":["山城侵晓设行宫，礼庆千秋万国同。","新学定期随日长，睿心元自与天通。","前星位正龙楼北，南极光躔鹤禁东。","惭愧授经无寸补，四年空立御香中。"]},{"t":"盆莲盛开饮中赠潘玉汝王廷璧戴廷器三秀才","f":"七言律诗","c":["盆池花照粉墙东，不数峰头十丈红。","雅韵独超尘壒外，新妆初试月奁中。","底须瑞露分金掌，共取清香注碧筒。","良会一时真不偶，拟开佳兆为诸公。"]},{"t":"浪淘沙 八月九日早至南山庵","f":"古风","c":["沙口系兰桡。","初退溪潮。","石成山路树成桥。","又见一番新稻熟，犹未趋朝。","野寺晚钟敲。","声到书巢。","此身何日伴渔樵。","少答君恩寻旧隐，细和山谣。"]},{"t":"赠泰塘画鱼程翁希明 其一","f":"七言绝句","c":["叠嶂如城水满川，门前乔木翠参天。","路人来往能相指，文献传家几百年。"]},{"t":"赠泰塘画鱼程翁希明 其二","f":"七言绝句","c":["爱鱼何羡古濠梁，画出群鱼趣更长。","正欲垂纶寻钓隐，何时相约水云乡。"]},{"t":"中秋开宴南山宗贤毕集燕后閒步坟庵水次偶成赠同行诸君子","f":"七言律诗","c":["初向南山见月圆，笑谈相对欲忘眠。","他乡每岁思千里，好友今宵共一筵。","人影渐分山寺侧，蛩声多近石梁边。","眼前又作朝天计，同步沙头在几年。"]},{"t":"题汪道全爱萱堂","f":"七言古诗","c":["阿母生儿今已老，少年曾佩宜男草。","阿儿念母心无涯，北堂远种忘忧花。","爱母如花愿花茂，长向花前祝眉寿。","酒盏时闻花送香，舞衣欲共花争秀。","我心正复与子同，一曲薰风歌绕丛。","爱母何年心始惬，霜鬓重看绿如叶。"]},{"t":"祖保去岁八月二十五日亡于姑苏暂寄僧舍归瘗南山今一年矣其母忽于箧中得见旧佩香囊恸不能忍并楮钱焚其瘗处辄赋五十六字志予之悲","f":"七言律诗","c":["去秋今日寄僧房，泪洒西风裂寸肠。","冢上已浇新麦饭，箧中犹见旧香囊。","五年父子缘何短，万里关山恨更长。","最是不堪怀抱处，梦魂时到枕帏旁。"]},{"t":"心远轩为方景茂赋","f":"五言律诗","c":["结屋西城下，幽人自不群。","道情閒共鹤，诗思淡随云。","与客观朝槿，呼童炷夕薰。","不知门外路，车马日纷纷。"]},{"t":"闰八月二十七日早送何侍御至阳山寺","f":"七言律诗","c":["豸冠前日下山城，双旆匆匆又出行。","金气作霜天九月，法星随斗夜三更。","青围川陆知途险，黄入郊原喜岁成。","山寺相违还有约，柏台高处听蜚声。"]},{"t":"归途有作","f":"七言律诗","c":["为送行台出县门，不辞携酒到山根。","竹阴正入支公寺，树色遥连主簿村。","潮啮新沙知废路，水舂机碓隔荒垣。","望中一簇峰峦秀，问是乡名古夹源。"]},{"t":"题贵溪程原宗人濯缨亭","f":"七言律诗","c":["洗耳常思古逸民，小亭閒傍绿杨津。","能收楚泽歌中趣，不惹长安陌上尘。","触目鸢鱼千古在，忘机鸥鹭一时驯。","何年解绶遥相访，同试渊明漉酒巾。"]},{"t":"送贵溪宗人世熙会谱西归","f":"七言律诗","c":["贵溪溪上旧程源，百世宗盟此一番。","祖庙已通昭穆序，客途何惮往来烦。","云山雨后丹青出，霜叶风前锦绣翻。","他日相期定何所，碧霄千里看鹏鶱。"]},{"t":"德兴泸口程氏青云桥为贡士崧乃尊赋","f":"七言古诗","c":["泸口之木高参天，泸口之水青如烟。","主人有功能济川，长桥倏起何蜿蜒。","眼中突兀见奇事，观者纷纷若鳞次。","新制宁须玉蝀名，华榱高揭青云字。","主人系出篁墩房，银青金紫相辉光。","有家住近凤凰里，一子矫如孤凤翔。","秋桂初分广寒殿，宫花拟入琼林宴。","门前正起世科坊，绰楔巍巍两堪羡。","主人白头乐有馀，看子平步青云衢。","驷马高车自兹始，傍人不用誇相如。"]},{"t":"寿汪处士","f":"七言律诗","c":["明明丹颊映华颠，淅淅金风拂寿筵。","清向客来茶当酒，严于家教笔为田。","东篱赏记前三日，西伯徵期后十年。","遥望芙蓉秋色里，仙人应有鹤书传。"]},{"t":"赠程瑎 其一","f":"七言绝句","c":["曾到星源种德坊，紫苔春雨上君堂。","活人当日功多少，门外长闻橘井香。"]},{"t":"赠程瑎 其二","f":"七言绝句","c":["尊翁曾是凤池人，六辇时巡敢爱身。","闻说赠官并录后，中兴天子劝忠频。"]},{"t":"赠程瑎 其三","f":"七言绝句","c":["文采风流入壮年，名门当见后昆贤。","紫阳正是君同里，莫为傍人草太玄。"]},{"t":"题楚英宗人寿萱图","f":"七言古诗","c":["北堂五月薰风长，萱草花开金凤香。","儿郎再拜献春酒，花气欲透斑斓裳。","北堂十月霜回日，萱草根盘蛰龙密。","一笑当筵指旧丛，举头误认丹青笔。","老人八十真如仙，朱颜若共花争妍。","愿期百岁根无恙，一度花开胜一年。"]},{"t":"寄贵溪致政高都宪","f":"七言律诗","c":["出处无心似白云，一身高洁四方闻。","诛茅喜近张良宅，谏草惊传陆贽文。","天上故人应渐少，山中新社约谁分。","双鱼无限倾情处，番水东流未足云。"]},{"t":"约欧阳令君登高 其一","f":"七言绝句","c":["秋满南山菊正黄，又惊明日是重阳。","贤侯久订龙山约，不似邻封簿领忙。"]},{"t":"约欧阳令君登高 其二","f":"七言绝句","c":["预向家园拂径苔，令君相约此登台。","须知不是寻常出，并作郊原问稼来。"]},{"t":"题汪仪凤墨梅","f":"五言绝句","c":["春意花先觉，冰威力自禁。","漫夸三昧手，谁识岁寒心。"]},{"t":"题画","f":"古风","c":["翠筱娟娟古木秋，山林?复网罗忧。","随时饮啄随枝宿，莫向西风叹白头。"]},{"t":"题欧阳令君所藏画鱼","f":"七言古诗","c":["当今写鱼谁第一，安福刘郎募俦匹。","父子同为供奉官，等閒不下丹青笔。","刘郎写鱼如写人，想像天机精入神。","云雷惨澹真宰戚，波涛汹涌阳侯嗔。","令君何从得此轴，咫尺江乡夺人目。","鼓鬣扬鬐势欲飞，金甲光芒三十六。","渚蒲水荇交沄沄，浪花滚雪腥风闻。","变生头角在俄顷，虾群鳝队空纷纭。","濠上老人不可作，与鱼相忘识鱼乐。","刘郎此趣堪敌之，坐使龙门在高阁。","君家子姓能读书，钓鳌有日光门闾。","手分铜符佩金紫，定应不愧刘郎鱼。"]},{"t":"寿仁里宗人景华时会统宗谱","f":"七言律诗","c":["谱刻初成不世珍，寿筵遥动满堂春。","相门根柢瞻乔木，仁里光阴祝大椿。","晚福渐看周甲子，仙方何用守庚申。","持觞伐鼓从今始，莫愧康衢古逸民。"]},{"t":"满江红 南山道中晚秋","f":"古风","c":["九月南山，犹未觉、园林秋意。","无远近、丹枫黄叶，翻成佳丽。","风外磬声知有寺，云中犬吠疑无地。","见孤峰、淡淡扫蛾眉，当空际。","脩竹里，柴门闭。","古木下，渔舟系。","更牛背两两，儿童相戏。","素练摇江明一鹭，黄云漫陇飞双雉。","喜农家、细麦早纤纤，青如罽。"]},{"t":"挽洪太守夫人 其一","f":"五言律诗","c":["闻讣惊相怛，名门失女宗。","子成新进士，家出旧司农。","弦断伤琴意，尘生暗镜容。","不堪埋玉处，风木正鸣冬。"]},{"t":"挽洪太守夫人 其二","f":"五言律诗","c":["梦兆曾炊臼，形伤见藁砧。","菊松思共老，霜雪遽先侵。","不待宜人诰，无惭列女箴。","生刍叹莫奠，寒日动哀吟。"]},{"t":"木兰花慢 赠通守娄公致政还乡有序","f":"古风","c":["喜年方耳顺，何遽尔赋归田。","想十载红尘，题舆佐岳，连宵清梦，先到林泉。","抽身急流而退，任攀辕无计可留延。","万里蓬瀛身近，一州父老情牵。","故园松菊正依然。","晚景乐无边。","看满载图书，芸霏别舸，倾城冠盖，云拥离筵。","酌杯起、为公寿，问几人舒卷似公贤。","海上耆英会启，日边循吏名传。"]},{"t":"筠窗静读诗为山斗族孙天相作","f":"七言律诗","c":["少年勤学慕三馀，玉立亭亭众不如。","击节常歌君子操，闭门时诵太玄书。","光回夜榻亲萤火，香满晨窗辟蠹鱼。","万卷可开须努力，河南家世本宗儒。"]},{"t":"陪欧阳令君奠故宋尚书金忠肃公墓并立石表","f":"七言律诗","c":["桂浆三奠陇云寒，共识贤侯此意难。","泉下屡更新岁月，人间谁问古衣冠。","青山再下樵苏禁，白石重将姓字刊。","拟有颂声传故事，无边光彩动林峦。"]},{"t":"寄题婺源沙阳宗家二书院","f":"五言古诗","c":["泠泠梓水源，郁郁青山趾。","中有两书堂，如鹄东西峙。","为问作者谁，吾宗有先子。","当其全盛时，纷纷集多士。","弦诵出林樾，灯火照墟里。","固将希圣贤，岂独事青紫。","两雏得联升，家誉亦腾起。","自从兵革来，家业已中燬。","人民嗟久非，山川幸良是。","云礽今复兴，白日盛桑梓。","昂昂用泰君，志可延世美。","朅来南山中，相从订家史。","派分沙阳房，源共篁墩祀。","乃知文庆深，流泽耿未已。","堂构非侈观，诗书乃末技。","绍述或有托，尔祖为不死。","勉㫋君后人，藏修自兹始。","野钱穷一卮，山行费双履。"]},{"t":"婺源环溪程氏一乐堂","f":"七言古诗","c":["堂上何人专一乐，华扁浓书照林壑。","再世弥甥得考亭，千年谱系通伊洛。","家学渊源有自来，固应子弟非凡材。","三时不违甘旨入，连枝有合荆花开。","此意宁知轩冕重，家政成时亦堪颂。","静阅遗编师古人，前有君陈后张仲。","五岭巍巍高入天，婺水汨汨东成川。","故家想像三叹息，因风为赋名堂篇。"]},{"t":"题吴恺举人春草","f":"五言绝句","c":["习习风初度，萋萋绿正匀。","谁将方寸地，散作十分春。"]},{"t":"题文富侄萱花","f":"五言绝句","c":["一色春难老，双亲未白头。","高堂相对处，日日可忘忧。"]},{"t":"新墟吴亚卿先生哀挽二首 其一","f":"七言律诗","c":["早辞钟鼎乐丘园，盛福完名众所尊。","星象忽惊前夕变，耆英今复几人存。","庙堂拟下哀荣诏，林壑空留杖履痕。","总道庆源流不尽，一经传子又传孙。"]},{"t":"新墟吴亚卿先生哀挽二首 其二","f":"七言律诗","c":["不睹光仪岁月侵，上堂瞻拜此情深。","坐中屡说通家义，老去犹多体国心。","朝野勋名终烜赫，山川灵气忽销沉。","无由执绋东风里，西望新墟思不禁。"]},{"t":"题万山深处楼","f":"七言律诗","c":["叠嶂层峦东复西，水源穷处结岩栖。","捲帘斗柄光临座，记路桃花插满堤。","境逼衡阳无雁过，峰多巫峡有猿啼。","裹粮何日寻幽去，却倚危阑续旧题。"]},{"t":"寿南山长老性空颂并序","f":"七言古诗","c":["我闻西方极乐囿，获登彼岸真非偶。","三千大千诸佛子，中有一人无量寿。","佛言我教本寂灭，有不是无无是有。","汝寿无量何以故，一点光明终不朽。","光明一点有明暗，白牛便向恒河走。","无量寿者合掌言，我今不净亦不垢。","跏趺坐阅人间世，不用寒山竹笤帚。","南山长老有性空，五蕴一生能自守。","南山有石解点头，试与对之相夘酉。","针头之性空不空，大笑一声狮子吼。","我观性空老不衰，本来面目无妍丑。","朝暮一盂脱粟饭，五味筵中不挂口。","春冬一领百衲衣，五色场中无掣肘。","性空尔能不空性，六十年光不为久。","无量寿者诵一声，甲了还丁子还丑。","灯灯相续不空过，永作南山住山叟。","我今已作逃禅客，问尔哑禅能答否。","无无无量亦无寿，白莲社中桑落酒。","无量寿佛何有哉，劝尔波罗饮三斗。"]},{"t":"大雪至南山庵","f":"七言律诗","c":["今年大雪胜北州，一夜五尺方始休。","担夫踏路没双胫，老衲开门馀一头。","眼■迷茫失山色，耳边清冽闻溪流。","青青惟有涧傍桧，劲气犹堪回万牛。"]},{"t":"冬至县中行庆贺礼","f":"七言律诗","c":["圣诞才过至日来，礼成遥贺两叨陪。","銮舆恍接清光近，谯鼓频催曙色开。","万寿喜从天上祝，一阳初自地中回。","云占乡国应多瑞，拟上城东百尺台。"]},{"t":"元日","f":"七言律诗","c":["松槚情深懒问途，又从乡国饮屠苏。","时名浪比来仪凤，薄孝思同返哺乌。","四十头颅惊隔岁，五千文字愧今吾。","承平一饭皆君赐，遥望星杓礼帝都。"]},{"t":"人日喜晴","f":"五言律诗","c":["六日雨兼雪，今晨忽放晴。","风吹群沴散，日射四山明。","喜卜民生遂，恭惟世道亨。","正寻诗纪胜，檐鹊送新声。"]},{"t":"点绛唇 元夕大雨","f":"古风","c":["满意鳌山，一天星月交相射。","春霖无藉。","误却千金夜。","院落沉沉，坐看灯花谢。","情难写。","佳期再也。","须问天公借。"]},{"t":"新岁大雪用元日韵","f":"七言律诗","c":["几处青山失旧途，一宵寒气薄流苏。","离群色乱沙头鹭，争食饥喧屋上乌。","陇麦廉纤如妒客，庭梅清瘦欲惭吾。","近臣喜遇正元瑞，拟颂丰年达上都。"]},{"t":"谢乡饮分席","f":"五言律诗","c":["喜雨传乡饮，心知胜昔年。","笙镛疑隔座，俎豆幸分筵。","礼觉周文备，仁思舜化延。","荷恩惭未报，何日赋归田。"]},{"t":"小诗六绝寄黟县汪令君 其一 奉赠","f":"七言绝句","c":["县组遥持入万山，棠阴俄觉颂声间。","直应小试牛刀手，鹓鹭终归玉笋班。"]},{"t":"小诗六绝寄黟县汪令君 其二 谢青目寄庄","f":"七言绝句","c":["售文宁足买山钱，多幸邻封受许田。","何日解簪归栗里，相随遗老颂丰年。"]},{"t":"小诗六绝寄黟县汪令君 其三 谢惠麻姑酒","f":"七言绝句","c":["分惠霜罂手自开，便惊春色逼人来。","笺题重有麻姑字，添作高堂献寿杯。"]},{"t":"小诗六绝寄黟县汪令君 其四 谢过访","f":"七言绝句","c":["萧萧门巷驻官轺，几日春泥雪半消。","壶马酒筹劳款坐，欲将风致写生绡。"]},{"t":"小诗六绝寄黟县汪令君 其五 谢惠及第坊三大字","f":"七言绝句","c":["华扁烦君远寄将，溪藤犹带墨花香。","行人拭目知多少，蓬荜从今倍有光。"]},{"t":"小诗六绝寄黟县汪令君 其六 阻雨不得诣谢","f":"七言绝句","c":["秋水遥添一丈强，朝天相趁理行装。","春霖如此难为别，咫尺黟川万里长。"]},{"t":"成化十九年二月一日浦口与王文明太守诸公别","f":"七言律诗","c":["冠盖追随出练江，山花盈路酒盈缸。","早归肯负王孙草，迟去终怀父母邦。","暂补一番鳌禁直，愁听三叠渭城腔。","寸心亦与诸贤共，廊庙江湖两未降。"]},{"t":"赠淳安丁尹鍊","f":"七言律诗","c":["白鹿重开讲院基，多君曾此服遗规。","学分朱陆心能辨，迹比龚黄事可知。","客路杯长留坐久，邻封情厚发船迟。","青溪坊下人行处，他日来看德政碑。"]},{"t":"舟次富阳登陆有感","f":"七言律诗","c":["帆樯暂泊暮江边，舆马重过旧县前。","十口提携皆骨肉，一春盘折几山川。","潮生潮落无终古，人去人来似隔年。","道左韶光能慰客，菜花桃萼两依然。"]},{"t":"阎文振方伯王景端都阃诸公邀饯灵隐寺 其一","f":"七言律诗","c":["钱塘门外日初红，万顷湖光一镜空。","白塔苍松山向背，画船垂柳路西东。","放生字认唐遗碣，行在名传宋故宫。","吊古有情诗不逮，一林啼鸟自春风。"]},{"t":"阎文振方伯王景端都阃诸公邀饯灵隐寺 其二","f":"七言律诗","c":["飞来峰下旧祗园，胜览平生第一番。","方丈云深疑伏虎，洞门风冷罢呼猿。","天开画史丹青笔，水杂游人语笑喧。","相对东皇须尽醉，一时那得聚高轩。"]},{"t":"阎文振方伯王景端都阃诸公邀饯灵隐寺 其三","f":"七言律诗","c":["偃盖松间载酒行，才惊飘泊过清明。","五年别向兹山会，两月春无此日晴。","石古谁参圆泽偈，井湮犹带葛洪名。","酒酣又是分携处，情比江潮晚未平。"]},{"t":"胡文恭佥宪邀游西湖次张天锡湖船旧韵","f":"七言律诗","c":["湖上来寻一日欢，春风消得旅怀宽。","玉壶载酒随山住，银甲弹筝隔水看。","花雨上瞻三竺远，松云高拂两峰寒。","忘情潦倒沙鸥社，相好平生几豸冠。"]},{"t":"马嵬八景次韵为阎方伯赋 其一 马嵬故垒","f":"七言律诗","c":["槐里西来一故城，乱离曾列几屯营。","千家已托英雄庇，百战谁争竖子名。","夕照有情山戍改，东流无限野塘平。","关中此日今蕃盛，赢得荒基蔓草生。"]},{"t":"马嵬八景次韵为阎方伯赋 其二 杨妃荒冢","f":"七言律诗","c":["不思初政戮家姬，坐遣胡雏犯洛师。","野鹿已招三镇乱，青螺刚济一身危。","冰消珠翠汗新壤，云暗金汤失旧赀。","万古持盈堪作戒，开元全盛几多时。"]},{"t":"马嵬八景次韵为阎方伯赋 其三 地涌双泉","f":"七言律诗","c":["谁从坡下凿重渊，觱沸开成两玉泉。","根蚀云萝常脉脉，影涵风筱共涓涓。","旱时几藉龙功普，跑处疑存虎迹圆。","能遣菜根滋味好，千金一歃敢争妍。"]},{"t":"马嵬八景次韵为阎方伯赋 其四 园栽丛韭","f":"七言律诗","c":["玉趾青毛遍石田，名传丰本自何年。","生怜蔬甲踰兼味，日课园丁获几钱。","星列一笾春荐庙，雨翻双剪夜登筵。","品供十八思贤辅，肉食令人倍赧然。"]},{"t":"马嵬八景次韵为阎方伯赋 其五 金城古迹","f":"七言律诗","c":["胜地犹存姓屡更，淡烟荒草没秋城。","主家西逐秦云散，僧锡东随渭水倾。","天靳宝花谁伏虎，枝空仙李不闻莺。","惟馀一片长安月，夜夜相临似有情。"]},{"t":"马嵬八景次韵为阎方伯赋 其六 宝刹晨钟","f":"七言律诗","c":["宝坊高处地幽偏，钟响常疑落半天。","旅次唤醒尘土梦，上方惊散海云眠。","纱笼客诮非时饭，锡杖僧开午夜禅。","看院鹤鸣如应答，一声声出薜萝烟。"]},{"t":"马嵬八景次韵为阎方伯赋 其七 西原春意","f":"七言律诗","c":["萋萋芳草绿如烟，鸟外长空澹欲连。","路辟裙腰时隐隐，风翻书带亦芊芊。","川光远衬桃如笑，野色平分柳未眠。","南浦一番春又别，王孙归兴绕吟边。"]},{"t":"马嵬八景次韵为阎方伯赋 其八 南亩秋成","f":"七言律诗","c":["社公祠处百家同，叠鼓鸣箫俎豆丰。","千载力田嘉汉诏，六经敦本说豳风。","鸡鸣犬吠闻宵警，女馌男耕毕岁功。","无吏索钱官税足，相逢莫放酒杯空。"]},{"t":"左时翊大参约出清波门饮石屋寺遂至水籥烟霞二祠次李若虚宪副韵四首 其一","f":"七言律诗","c":["山行随处酒旗斜，风逼轻阴水漾沙。","抱岫岚光疑失路，出墙春色喜逢花。","武林佳胜当三月，文苑风流会一家。","此别相思重回首，迢迢清梦隔京华。"]},{"t":"左时翊大参约出清波门饮石屋寺遂至水籥烟霞二祠次李若虚宪副韵四首 其二","f":"七言律诗","c":["何代龙潜屋后峰，堑崖穿破碧重重。","风云变化应难测，头角峥嵘岂易逢。","新度开山祗树绕，旧游题字薜萝封。","奇观一日忘归晚，侧耳高城已暮钟。"]},{"t":"左时翊大参约出清波门饮石屋寺遂至水籥烟霞二祠次李若虚宪副韵四首 其三","f":"七言律诗","c":["何处令人俗可医，偶穿脩竹赴幽期。","水从鬼窟鸣双玉，山自灵峰转一枝。","便觉管弦声涴耳，共随猿鸟立移时。","颠崖象石常相近，幻色潮音两斗奇。"]},{"t":"左时翊大参约出清波门饮石屋寺遂至水籥烟霞二祠次李若虚宪副韵四首 其四","f":"七言律诗","c":["入山无处觅新茶，深洞翻疑散宝花。","何代神功初辟地，一时僧梵偶成家。","上方坐见潮生浦，归路谁看树隔霞。","春尽江南惊暴热，拟将纨扇拂轻纱。"]},{"t":"钟馗骑驴图为周可大宪使赋","f":"七言律诗","c":["阴风萧萧吹发寒，老馗夜踏山雨残。","恨生不作中执法，誓死肯负唐衣冠。","骊山梦破一回首，上帝毋烦六丁走。","魑魅都归鞭策中，嬴得骑驴袖双手。"]},{"t":"歙西许良庆自号松谷相会武林求予诗","f":"五言律诗","c":["歙西有佳境，老翠薄青冥。","力受风霜饱，心知岁月经。","竹梅同晚节，蒲柳愧先零。","何日开新社，相随共斸苓。"]},{"t":"陈德脩太守自金华寄雪窝诗索和","f":"五言律诗","c":["蕞尔无馀地，翛然绝点尘。","间情真却扫，爽气欲侵人。","昼迥云生座，宵空月照邻。","为言公暇日，谁与和阳春。"]},{"t":"张廷芳李若虚二宪副及江廷诸宪佥约游西湖左时翊大参后至得联句十首时成化癸夘三月三日也 其一","f":"七言律诗","c":["东风吹雨下湖船，良会今朝岂偶然。","烟景可人非为酒，春光随地不论钱。","数声啼鸟苏堤外，几树垂杨岳庙前。","满眼诗情吟不尽，孤山祠下酹三贤。"]},{"t":"张廷芳李若虚二宪副及江廷诸宪佥约游西湖左时翊大参后至得联句十首时成化癸夘三月三日也 其二","f":"七言律诗","c":["烟景霏霏入暮春，赏春多是宦游人。","野凫狎客随舟远，江燕穿花送酒频。","雅会不须歌舞溷，奇观绝胜画图新。","六桥过尽重回首，久驻湖边我未嗔。"]},{"t":"张廷芳李若虚二宪副及江廷诸宪佥约游西湖左时翊大参后至得联句十首时成化癸夘三月三日也 其三","f":"七言律诗","c":["十里湖山入望遥，可堪野色故人撩。","楼台隐显午烟淡，鹅鸭浮沉春水娇。","抚景无诗怜我拙，追欢有乐是谁招。","东风更有重来日，莫待浓阴翳断桥。"]},{"t":"张廷芳李若虚二宪副及江廷诸宪佥约游西湖左时翊大参后至得联句十首时成化癸夘三月三日也 其四","f":"七言律诗","c":["来往游人不避舟，镜天空阔雨初收。","桃花向我如相笑，竹叶浮君可自由。","山外有山深见寺，客边逢客一登楼。","唱酬遮莫归鸦尽，三竺峰前更小留。"]},{"t":"张廷芳李若虚二宪副及江廷诸宪佥约游西湖左时翊大参后至得联句十首时成化癸夘三月三日也 其五","f":"七言律诗","c":["公家事了独来迟，一笑相寻本有期。","湖上风光春最好，雨中诗景晚尤奇。","邻舟爱客供鲜鲫，古寺寻僧问紫芝。","多谢故人频饷我，可堪明日又分岐。"]},{"t":"张廷芳李若虚二宪副及江廷诸宪佥约游西湖左时翊大参后至得联句十首时成化癸夘三月三日也 其六","f":"七言律诗","c":["山当佳处启船扉，唤酒催诗思欲飞。","狼藉醉中长短句，阑珊春后裌绵衣。","忘机鸥鹭随冠盖，浪迹鹓鸾负蕨薇。","后会未涯情未已，恨中谁道故人稀。"]},{"t":"张廷芳李若虚二宪副及江廷诸宪佥约游西湖左时翊大参后至得联句十首时成化癸夘三月三日也 其七","f":"七言律诗","c":["西湖春水暖溶溶，美景佳宾岂易逢。","游到南屏船驻久，坐忘东道酒行重。","高城迢递烟钟晚，远浦参差雨树浓。","剧饮不须修禊事，会稽何地觅遗踪。"]},{"t":"张廷芳李若虚二宪副及江廷诸宪佥约游西湖左时翊大参后至得联句十首时成化癸夘三月三日也 其八","f":"七言律诗","c":["主客同舟西复东，花边烟雨柳边风。","谪仙先我诗层出，禊饮凭谁酒易空。","青雀渡头春树暗，白鸥沙外晚潮通。","相看此地情无极，吊古还寻放鹤翁。"]},{"t":"张廷芳李若虚二宪副及江廷诸宪佥约游西湖左时翊大参后至得联句十首时成化癸夘三月三日也 其九","f":"七言律诗","c":["湖上风烟三月三，湖中新水远拖蓝。","风流再续兰亭后，文物谁当北斗南。","林外鸟惊人语乱，花前春共客情酣。","乘时张弛非沈湎，纪胜无才却自惭。"]},{"t":"张廷芳李若虚二宪副及江廷诸宪佥约游西湖左时翊大参后至得联句十首时成化癸夘三月三日也 其十","f":"七言律诗","c":["维舟重憩藕花居，湖水湖山故恼予。","纱帽不妨风外侧，尘襟都向雨中舒。","满天暝色催诗急，绕座春光入醉馀。","游倦莫愁归路远，涌金门外有轻舆。"]},{"t":"景范为武林施秀才赋","f":"五言古诗","c":["往哲去已远，遗范存典册。","居然山斗尊，景仰斯有获。","多君浙西彦，揭榜示鞭策。","一善思服膺，微言亦探索。","持循苟弗已，渐可窥道脉。","或堪凤腾咮，何止鹏奋翮。","云为一愆期，名实坐难核。","悠悠圣狂分，忽忽天壤隔。","勉哉好德人，毋遣中道画。","希颜与学孔，千载后贤责。"]},{"t":"与阎方伯饮紫阳庵次韵","f":"七言律诗","c":["一缕茶烟湿未消，几梯云路暗通桥。","涛头盛拥鸱夷怒，亭上清留野鹤标。","病目临风常带缬，弊裘经雨半成潮。","重来便拟非生客，径揖山灵不待邀。"]},{"t":"程氏三节妇诗","f":"五言古诗","c":["一节已云寡，联芳良独难。","伟哉程氏妇，挺此三琅玕。","朅从夫子亡，矢死为孤鸾。","梯也谢膏沭，姒也捐罗纨。","空闺窅无人，号恸摧肠肝。","庭乌助其哀，比邻辍其餐。","抚婴尚自苦，独处尤悲酸。","人生几何时，日月如流丸。","长者遂白头，少者颜凋残。","不见昊天广，但觉春风寒。","乃知帝降衷，本固不可刓。","滔滔东逝水，足与回狂澜。","愿言冠屦子，勿作偷生安。","如此巾帼人，输彼一寸丹。","长令天地间，凛凛节操完。","我非刘更生，闻之坐长叹。","谁当传列女，千载名弗刊。"]},{"t":"刘廷讯方伯诸公邀饮紫薇楼次旧韵","f":"七言律诗","c":["登临谈笑总材雄，兴入苍茫四座同。","潮落宋元兴废外，山分吴越有无中。","一方屏翰遵周制，万里梯航念禹功。","醉倚危阑还纵目，数行征雁逐南风。"]},{"t":"与时翊大参若虚宪副同至胜果寺欲寻宋宫遗址雨不克往","f":"七言律诗","c":["出城何处可消閒，宝刹巍巍紫翠间。","下界路寻松杪入，上方人自雾中还。","女墙半锁云千叠，御沼平分水一湾。","不尽登临怀古意，谁教春雨断空山。"]},{"t":"武林写竹裴生奭求晚翠诗","f":"七言绝句","c":["万紫千红不奈看，有名谁可结诗坛。","惟馀笔下翛翛竹，解与幽人阅岁寒。"]},{"t":"阎方伯为予言藩省门对吴山有白鹭群飞朝去暮来日以为常因识以诗且将绘图以传遂次韵一首","f":"七言律诗","c":["侵晓来从杜若洲，晚风吹过紫薇楼。","水田漠漠翻晴雪，尘海茫茫点白沤。","终日往还如有约，随时啄宿本无求。","清班高处君曾立，未许吴山得久留。"]},{"t":"呈致政大理仁和夏公","f":"七言律诗","c":["风流逋老旧林居，见说曾停长者车。","释子仙翁凭结社，水经山志亦成书。","笙歌懒逐游人后，院落初更野火馀。","独有问奇船误入，时从湖口访樵渔。"]},{"t":"简刘竹东","f":"七言律诗","c":["东风日日绮罗筵，失结诗家冷淡缘。","呵卒行惭松下道，伶童声涴涧中泉。","沙鸥野鸟浑相避，岸草汀花亦自怜。","孤负湖山好春色，向君思觅卧游篇。"]},{"t":"赠嘉兴王景福通判","f":"七言律诗","c":["吏部文章第一人，奉天门下拜恩新。","家藏徽国遗书满，郡与宣公旧宅邻。","属县迎人来画舫，监州行事等朱轮。","因君相庆还相属，不负平生在泽民。"]},{"t":"双寿为刑部刘廷臣郎中赋","f":"七言律诗","c":["高堂二老面如丹，同一生申世更难。","仙授遐龄书付鹤，帝颁殊宠诰回鸾。","乔松未觉年华老，萱革能禁雪意寒。","持节平刑誇令子，过家称庆有馀欢。"]},{"t":"题礼部吕秉之郎中画册 其一","f":"五言绝句","c":["衡门俯寒江，隐隐脩竹下。","鼓棹问奇人，扁舟快于马。"]},{"t":"题礼部吕秉之郎中画册 其二","f":"五言绝句","c":["危山耸如人，绝壑下如阱。","居然垂钓翁，相呼不相应。"]},{"t":"题礼部吕秉之郎中画册 其三","f":"五言绝句","c":["凉宵万籁息，明月流天中。","放舟出浦口，仰面承江风。"]},{"t":"题礼部吕秉之郎中画册 其四","f":"五言绝句","c":["云浮天外峰，烟断江头树。","倚岸得纶竿，渔家不知处。"]},{"t":"题无锡华文君便面图诗后","f":"七言绝句","c":["当时交契满清朝，离合难禁岁月遥。","重续旧题无限思，一灯残雨宿长桥。"]},{"t":"饮虎丘舟中呈致政祝大参顾宪副及受封王太史","f":"五言律诗","c":["客里春将暮，乘閒上虎丘。","饮便荷叶盏，坐爱木兰舟。","倚棹闻啼鸟，鸣箫动狎鸥。","幸陪诸老至，不是少年游。"]},{"t":"枫桥送别图追赋送刘汝器太守","f":"七言古诗","c":["枫桥岸侧鸡乱鸣，枫桥水边舟欲行。","老稚欢呼吏人拥，云是刘侯朝帝京。","刘侯爱民如赤子，三岁大朝今岁始。","循良定作好诸侯，清白曾夸真御史。","枫桥之水来吴江，刘侯惠泽如水长。","王程有期不可挽，起舞再进黄金觞。","明年二月春满野，一路垂杨翠堪把。","焚香结綵预相期，还向枫桥候车马。"]},{"t":"读大司马三原王公奏议","f":"七言律诗","c":["三复华编思不禁，爱君忧国虑何深。","忠言如出宣公手，恸哭谁知贾谊心。","名字直应高北斗，文章宁止重南金。","何时诏许归黄阁，坐遣苍生得傅霖。"]},{"t":"追和虞道园石湖治平寺诗韵","f":"五言古诗","c":["假宿胥门驿，竹扉常反关。","时登屋角楼，望见吴中山。","居然石湖里，隐映如一寰。","繁华久销歇，流水空潺湲。","闻说古郊台，犹存兰若间。","无由策杖入，借此半日閒。","孤怀坐成晚，浮云自东还。"]},{"t":"题洞庭吴鸣翰秀才东峰卷","f":"五言绝句","c":["日出峰上红，水绕峰下碧。","中有藏修人，心期谢安石。"]},{"t":"四仙图为栗之题","f":"五言古诗","c":["不见升天翼，冷然解御风。","当时观水趣，可与仲尼同。","七贤何代士，同作过关人。","或是逃名者，联翩起避秦。","东海如清浅，蟠桃更熟无。","谁于天际路，飞舄见双凫。","仙奕心难静，经年事手谈。","倚门千古恨，谁似烂柯憨。"]},{"t":"郭忠恕雪霁江行图为沈启南题","f":"七言古诗","c":["蜀山晓起雪大晴，蜀江早有商船行。","前牵百丈后催舵，欲动不动难为情。","两舷相依若弟兄，雪后无风江水平。","古来川货甲天下，尔中何物皆充盈。","一舟系尾大于瓦，荡漾不敢相先争。","有时遇险即分载，主者自解操奇赢。","长年三老各守职，翘首疑闻呼啸声。","纷纷远树雾中出，点点玉峰天外明。","棹郎呵冻相偶语，隔岸恐是夷陵城。","大滩小滩难悉数，自出两川今几程。","嗟哉远道亦良苦，盐井有戒何相轻。","披图一见肌上粟，凛然朔气生檐楹。","摩挲久之意乃定，何人方寸劳经营。","素缣半幅不盈尺，云是东都狂郭生。","宣和天子爱书画，亲与印识题其名。","一朝桑海忽遭变，内局委弃随榛荆。","郭生惟馀比干画，犹幸不燬南来兵。","奎章学士子山子，献纳曾倾葵藿诚。","尔来二百有馀岁，屈指春秋凡几更。","不知此本尚在否，抚卷益觉心怦怦。","石田沈君最博雅，重购所得人皆惊。","装潢完好无璺裂，入手坐见增光荣。","郭生斯图乃其一，馀者往往皆精英。","题诗有暇或临扫，也以丹青吴下鸣。","闻君家住湖水侧，青山古木相回萦。","何时倚棹一寻访，君当倒屣来相迎。","翩然坐我竹窗下，石鼎细呼春茗烹。","挥童开奁取卷轴，甲唐乙宋聊相评。","旁人定诮太古癖，尘襟且拟冰壶清。","却愁玩物犯祖戒，未敢先输他日盟。"]},{"t":"结草庵与黄二宣饮","f":"五言律诗","c":["厌见敲篷雨，来寻结草庵。","土峰新鹫岭，石涧小龙潭。","路绕蔬畦外，城当竹院南。","客怀消不尽，一饭听吾谈。"]},{"t":"龚廷臣许刻图书不至诗以促之","f":"七言律诗","c":["竹风清处只题诗，一寸并刀不浪施。","能事自应难受逼，知音宁肯亦相辞。","新形活动盘苍纽，古篆横斜度赤丝。","从此文房知借重，泊舟相待已多时。"]},{"t":"夏太常竹为刘太守题","f":"七言古诗","c":["平生最爱文湖州，挥毫落纸涵清秋。","胸中自有渭川在，高卧直轻千户侯。","太常亦曾乘五马，风致不在湖州下。","剪得吴淞水半江，顿觉姑苏纸增价。","瘦节矫矫虬龙形，细叶萧萧鸾凤翎。","清潭下照不见影，爽籁一披如有声。","我朝名笔忽到此，眼中潇湘无乃是。","冰缣欲赠谁可当，总说刘侯德相似。","刘侯治苏经五寒，挺然可比青琅玕。","雅操不为雪霜变，虚心肯受尘埃干。","汉室行将召循吏，几见春花逐时媚。","惟有清风似故人，头白相看不相弃。"]},{"t":"书东峰吴鸣翰秀才与王太史顾永州华应城联句后","f":"七言律诗","c":["行人一月住姑苏，手阅珠玑兴不孤。","分道正奇知善战，无形山水见佳摹。","高杨句法真能续，韩孟才名渐可图。","颇恨风帆催去速，无缘誊藁付奚奴。"]},{"t":"戴以德侍御行台清节卷 其一","f":"七言绝句","c":["绕舍森森玉万竿，不知曾历几人看。","一经句曲仙郎手，便觉行台分外寒。"]},{"t":"戴以德侍御行台清节卷 其二","f":"七言绝句","c":["绣衣心性爱霜筠，自起新亭作主人。","公退翛然无一事，清风看扫簿书尘。"]},{"t":"登金山 其一","f":"古风","c":["眼中帆影去如飞，槛外波光碧四围。","南北胜游皆下此，乾坤高兴独凭危。","中?水品清人骨，绝海风声振客衣。","张祐有诗谁更续，留云亭畔倚斜晖。"]},{"t":"登金山 其二","f":"七言律诗","c":["大江中拥一峰孤，面面天开海岳图。","黄鹄久随拳石化，白鼋能受老僧呼。","遗丘漫指青囊郭，劫火犹传玉带苏。","起向妙高台上立，朵云红处是皇都。"]},{"t":"闻熊良佐太守复追饯江口不及诗以寄意","f":"七言律诗","c":["欲趁潮生早渡江，多君投辖意难降。","已从水上鸣双橹，莫遂沙头倒一缸。","隔岸村鸡催午爨，留人江燕集风幢。","不堪咫尺分南北，斜日孤舟独倚窗。"]},{"t":"谒董子祠","f":"五言律诗","c":["江都仍旧地，无复汉王臣。","故宅碑全燬，荒园井未湮。","一言分义利，三策动天人。","转运今祠主，相随奠绿蘋。"]},{"t":"题郭守备画卷","f":"七言绝句","c":["一尊相乐水云间，曾共辕门一日閒。","今度逢君江北路，只从图上看青山。"]},{"t":"赋琼花时与杨成玉太守鲍栗之同知饮无双亭作","f":"七言律诗","c":["仙姬谪堕偶成丛，江北淮南淑气通。","天上有容争玉雪，人间无地著青红。","野塘逼路鱼吹絮，古庙依林鸟唤风。","不尽閒花倾国恨，芜城斜日旧离宫。"]},{"t":"饮总漕平江伯陈公园","f":"七言律诗","c":["元戎能武更能文，新起园亭自不群。","尘里烟霞惟此见，胸中丘壑许谁分。","投壶散坐随花影，草帖临池傍水云。","幸我暂来仍暂去，不辞觞咏到斜曛。"]},{"t":"徐都宪新奉敕至淮上以诗贺之","f":"七言律诗","c":["乌府谁堪众论谐，多君宜进大夫阶。","旧班宠泽均三辅，新诏提封尽两淮。","拟见清霜消酷暑，可怜平地走阴霾。","宇中屈指观风使，会遣功名惬壮怀。"]},{"t":"题淮人史孟哲所藏赵仲穆兰","f":"七言绝句","c":["墨池谁解返香魂，淡叶疏花古意存。","霅水风流湘水怨，不知同是旧王孙。"]},{"t":"题增光前人卷","f":"七言古诗","c":["东南漕粟如屯云，舳舻千里声相闻。","何人转饷称第一，楼船独数陈将军。","三朝历历书勋考，抚髀无由起元老。","寝庙弘开楚水头，不断行人荐蘋藻。","楼船孙子人中龙，早从南粤分提封。","八蛮坐使遵汉法，五岭不复生烟烽。","一日功成召还阙，浩气如虹面如月。","临轩天语十分浓，许秉楼船旧时钺。","淮阳幕府今几年，门前乔木高参天。","兵彊食足两无事，谋谟一一皆家传。","平生好文不专武，清白相承守茅土。","天教良将辅中兴，何愧周家世臣虎。","仓廪不虚国不忧，二京相望皆安流。","殿岩徵入卫天子，剖符再见封元侯。"]},{"t":"思补堂为毕知县赋","f":"五言古诗","c":["淮树何苍苍，淮流下汤汤。","水木相荏苒，中有君子堂。","眷彼堂中人，意气如圭璋。","金榜昔高捷，花县方回翔。","不愿縻好爵，幡然归故乡。","閒居二十载，鬓发惊沧浪。","平生君父心，一饭宁敢忘。","清梦绕庭阙，遐思在羹墙。","孤云起复止，春草萋以长。","令德幸加勉，桑梓流其芳。","城东节孝心，郁郁遥相望。"]},{"t":"都廷美参将之子克让思以经术自奋求诗为勉","f":"七言律诗","c":["将门才子乐从儒，闻道穷经众不如。","棘院英豪堪一战，芸窗辛苦足三馀。","弯弓不射南山虎，走笔将腾北海鱼。","文武一门看世泽，他年留待史官书。"]},{"t":"题广人钟禧所藏苏东坡亲书率子廉传后 其一","f":"七言绝句","c":["紫虚阁上几丹成，杵臼声残月自明。","不是长公词翰绝，世人谁记率生名。"]},{"t":"题广人钟禧所藏苏东坡亲书率子廉传后 其二","f":"七言绝句","c":["禅榻香销一穗云，断缣遗墨喜逢君。","临风细认藏书印，犹是襄阳米芾文。"]},{"t":"饮平江伯清江浦别业中有道院及其大父恭襄公祠堂","f":"七言律诗","c":["一江如块绕堤青，琳馆丹房昼不扃。","树转阴中斜作路，景逢佳处半开亭。","鱼惊洗砚过沙荡，鹤听敲棋傍石屏。","未放客舟仍徙倚，旧勋祠畔读碑铭。"]},{"t":"留题表兄林文秀","f":"七言律诗","c":["一官辛苦向淮阴，上世犹传九牧林。","壮岁功名须努力，外家兄弟最关心。","官河发棹乘春晚，驿馆挑灯语夜深。","明日又应分去住，天涯相望各沾襟。"]},{"t":"大河卫闵恭百户玩韬轩次卞郎中华伯韵 其一","f":"七言律诗","c":["要将忠赤报皇家，手阅兵机鬓未华。","辨悟公孙非白马，勇思周处戮长蛇。","曾从老将窥三略，不数旁人泥六花。","当局定知多胜算，晓添营灶夜量沙。"]},{"t":"大河卫闵恭百户玩韬轩次卞郎中华伯韵 其二","f":"七言律诗","c":["知是淮东宿将家，剩传英誉满京华。","素书妙指传黄石，紫绶佳祥见赤蛇。","武队晓屯新细柳，戎衣秋展旧团花。","太平未可全忘战，珍重夔州碛上沙。"]},{"t":"题林良画","f":"七言绝句","c":["一鹭閒依翠藻行，一禽飞绕绛桃鸣。","辕门昼静无矰弋，何限春风笔下情。"]},{"t":"邀月轩为太河卫千户陈铠赋","f":"七言律诗","c":["不须烧烛照幽轩，夜下空阶白露繁。","开户欲分丹桂影，倚阑思共素娥言。","旋收灏气归佳酿，莫放清阴过短垣。","何羡庾楼高百尺，此中仙兴绝尘烦。"]},{"t":"题乡人毕廷馨金台别意卷","f":"五言古诗","c":["子向皇都来，我向皇都去。","相见下邳城，各诵离筵句。","子行入家山，动我游子颜。","惊风吹野水，梦逐孤云还。","我怀致君忧，子遂奉亲乐。","悠悠南北人，何时罢行脚。"]},{"t":"寿邳州致仕都督韩公八十","f":"七言律诗","c":["纳节归来二十秋，丹心犹在雪盈头。","口传豹略勋名远，身赐龙衣宠眷优。","寿域拟过周尚父，辕门相近汉留侯。","贤郎接武先诸将，新总军储十万舟。"]},{"t":"徐州与客夜酌联句留别马瞰贡魁","f":"七言律诗","c":["今夜彭城雨又来，烛花影里一尊开。","人生聚散纷萍梗，前代兴亡付劫灰。","佳会幸逢全盛日，并游谁是出群才。","明朝天北天南恨，野水孤云戏马台。"]},{"t":"沛县端午与同行徐敬夫舍人王去私司务赵梦麟主事","f":"七言律诗","c":["泗上分明古驿亭，客舟俄聚水云汀。","佳辰几遇头将白，故旧重逢眼又青。","阙下起居应赐艾，尊前离合笑看萍。","清时致主身同健，莫向东流问独醒。"]},{"t":"歌风台","f":"七言律诗","c":["土墙茅屋断堤垠，感慨当年此奉宸。","废井独来提瓮女，空亭无复打碑人。","真王业可忘思沛，猛士歌应悔狩陈。","斗酒未穷怀古意，夕阳红处麦粼粼。"]},{"t":"有感","f":"七言律诗","c":["供应纷纷接两京，舳舻千里敢争衡。","尚方味说东南美，敕使行兼日夜程。","进果谁陈加爵疏，献芹图得爱君名。","岂知仁圣忧民隐，旰食时时减大烹。"]},{"t":"醉中和去私一绝","f":"七言绝句","c":["蒲有香根芥有台，客中佳节掌中杯。","同来吊古皆豪俊，莫问诗才与酒才。"]},{"t":"砚瓦沟","f":"七言律诗","c":["一派泉声出涧长，千金犹带墨痕香。","源流色正分玄武，删述功深仰素王。","湘水有鱼还识字，荥河无马复呈祥。","稽疑欲借图经看，断港裴回又夕阳。"]},{"t":"济宁遇周仲瞻黄门夜酌","f":"七言律诗","c":["夜刻知传第几筹，谁宾谁主两淹留。","雄谈秪觉风生席，烂醉偏怜月在舟。","客路西东分济水，离歌长短奏凉州。","酒中无复惊人句，愧见城南太白楼。"]},{"t":"望阙里作","f":"七言律诗","c":["尼山东下郁苍苍，去路都无百里长。","何日礼容陈俎豆，一宵清梦绕宫墙。","孔林岂用堪舆说，周典应多掌故藏。","心口自惭还自语，进修何日敢升堂。"]},{"t":"闻重修孔庙东石宪副","f":"七言律诗","c":["礼殿辉煌照寝园，隆师一代仰宸尊。","再从海岳开形胜，谁向图书识道原。","文献不须徵杞宋，规摹从此陋金元。","提刑石介人争羡，独著贤劳满圣门。"]},{"t":"寄衍圣公昆弟","f":"七言律诗","c":["不见王孙已数年，每过东兖即茫然。","蒹葭自幸陪双玉，葩藻还能值几钱。","良夜有情应下榻，薰风无计可停船。","鱼笺一尺凭谁送，济水东流月渐圆。"]},{"t":"偶成","f":"七言绝句","c":["船窗徙倚见残阳，帆影垂流印一方。","五月畏途心不恼，喜看随处麦登场。"]},{"t":"刘阮遇仙图为提督河道杨克敏通政赋","f":"七言古诗","c":["眼中风景非尘寰，熟视毋乃天台山。","迥然仙境与世绝，断崖无罅愁跻攀。","瀑水千寻洒寒雪，危峰十二浮烟鬟。","野渡南通赤城道，石桥下锁清溪湾。","沉沉一洞截山口，恐是天造蓬莱关。","深行入洞凡几里，鸡犬声喧白云里。","浊水清尘此地分，珠宫贝阙中天起。","芝耳曾闻商调悲，松颜不受秦封耻。","涧边夹路记行踪，乱插桃花傍流水。","西天不教化人城，万片飞霞散晴绮。","洞中美人冰雪容，星冠玉佩惊游龙。","长者为姊弱为妹，临风宛若双芙蓉。","未识人间有伉俪，但觉世外无春冬。","端居不吟芍药句，蛾眉肯蹙莲花峰。","三生有客缘未了，不期而遇真奇逢。","雁荡山头日西没，采药迷途意荒忽。","珍禽逸响来缤纷，瑶草幽香散蓬勃。","客子由来阮与刘，一一平生有仙骨。","丹室原称姹女家，蓝桥即是神仙窟。","双璧相携归洞房，紫衣小队侍两旁。","霓旌翠葆总生色，鸾箫鼍鼓纷成行。","供炊拟作胡麻饭，合卺先进昆崙觞。","鲛绡文席琥珀枕，百岁宁忧春夜长。","天潢牛女漫暌隔，巫山云雨何荒唐。","流年忽忽如奔电，偶在山中忆乡县。","请从此别去还来，却对桃花重开宴。","仙凡便觉两悠悠，未尽离觞泪如霰。","一去如同涧下流，重来事异梁问燕。","轻狂柳絮非妾心，珍重蒲花似郎面。","铜烛半销云母屏，琅函未启黄庭经。","凤笙绝响缑山黑，瑶瑟断弦湘水青。","玄猿长啸白鹤舞，苍天赤日空岩扃。","岂知二客一分手，身如梦蝶愁难醒。","世移物换几尘劫，桑田海水双浮萍。","春来再理登山屐，药裹行装感畴昔。","人非物是心茫然，小桃花红水空碧。","耳畔疑闻杵臼声，道傍只见豺狼迹。","风鬟雾鬓今有无，恐在山头化为石。","此身未老将何从，紫府瑶台缪通籍。","人生有合还有离，仙犹未免将奚为。","山经地志或偶尔，见者何人传者谁。","长生久视本绝欲，诲淫野合能无欺。","赤豹凌风说山鬼，白狐拜斗成妖姬。","危哉二客幸不死，奇逢堪喜还堪悲。","锦衣郎君内供奉，一纸风流百金重。","鹅溪新绢写此图，把玩精神欲飞动。","银台敕使偶得之，坐见丹青照梁栋。","款予频挽木兰舟，催诗旋发蒲萄瓮。","安得人如宋玉才，为君一赋桃源洞。"]},{"t":"临清饮提督兵备潘廷玺宪副家","f":"七言律诗","c":["倚棹清源日未中，旧游谈笑偶然同。","兴来已尽三升酒，醉里还开一石弓。","为乐都忘宾共主，留人无奈雨兼风。","醒时始觉归时晚，漏下船窗烛影红。"]},{"t":"饮王氏园亭 其一","f":"七言绝句","c":["舣舟三日厌尘烦，步入王家百亩园。","多少风光生眼底，恨无佳什满幽轩。"]},{"t":"饮王氏园亭 其二","f":"七言绝句","c":["鸡犬深深曲径通，意行何必问西东。","井亭杨柳交加处，木槿花开一树红。"]},{"t":"饮王氏园亭 其三","f":"七言绝句","c":["雨后平沙不受尘，偶来忘却宦游身。","过江三月昏昏醉，忽见新篁似故人。"]},{"t":"饮王氏园亭 其四","f":"七言绝句","c":["谷苗深秀菜根肥，露气凉生白苧衣。","珍重主人留客晚，隔墙灯火映船扉。"]},{"t":"赠临清刘克庄孝子","f":"七言绝句","c":["贾肆歌楼日夜忙，清源佳丽比苏杭。","道旁绰楔金书字，惊见刘家孝子坊。"]},{"t":"故城见致政马太守先生 其一","f":"七言律诗","c":["前辈风流十载闻，登堂今喜沐清芬。","夜谈往事徐呼酒，老爱新知屡示文。","林壑有缘供杖屦，朝廷何日下玄纁。","顺流双桨明朝别，无限情随烛影分。"]},{"t":"故城见致政马太守先生 其二","f":"七言律诗","c":["卫水湾湾翠绕庐，如云乔木荫庭除。","白眉久待双龙阙，黄发高悬五马车。","桑梓百年恭敬日，萍蓬千里笑谈馀。","薰风拟入长安道，先为家人报起居。"]},{"t":"沧州遇张用光通守题便面赠之","f":"七言绝句","c":["相逢草草别匆匆，无限交情一握中。","千里暂应分皓月，一方还为起清风。"]},{"t":"题碧桃翠竹便面赠妹婿赵瑛千户","f":"七言绝句","c":["仙葩和露掌中开，天上灵根异种栽。","只见清风堪结好，渭川分取一枝来。"]},{"t":"青县遇漕运王瑾都阃自云宣城人甚有桑梓之念","f":"七言律诗","c":["楼船同住水西涯，一见知公是将家。","解赠不须欧冶剑，论交频煮越州茶。","山东幕府名初上，河内军储帝汝嘉。","闻说有怀荣昼锦，敬亭山色待高牙。"]},{"t":"题唐马","f":"七言绝句","c":["青青苜蓿长初齐，十二天闲望不迷。","杨柳一株沙苑道，奚官来试骕霜蹄。"]},{"t":"弟敏德在新安尝作折枝海榴过河间从弟敏聪见而说之遂题一绝与之","f":"七言绝句","c":["香实垂垂带露滋，丹青摹出压阑枝。","江南江北花相似，白日看云一赋诗。"]},{"t":"赠天津吕昂挥使","f":"七言律诗","c":["百雉高城虎豹屯，将军初识吕虔孙。","帆樯影匝河边路，刁斗声连海上村。","青镜年华应自惜，锦囊兵法共谁论。","他时不忘相逢处，驿舍迎人柳拂门。"]},{"t":"到京寄漕运平江总戎","f":"七言律诗","c":["宾客淮阳盛一时，偶随行乐倒琼卮。","投壶不废军中礼，横槊何惭马上诗。","沙柳绿完元帅府，水香花满令公祠。","南风忽倚都门棹，凭仗双鱼慰所思。"]},{"t":"寄浙江阎文振方伯李若虚宪副诸公","f":"七言律诗","c":["萍水重逢各壮颜，相留十日共乘閒。","饮馀浙市新陈酒，阅遍吴城表里山。","远意笑谈频入梦，久惭供奉乍归班。","江湖廊庙心犹在，敢厕诸公伯仲间。"]},{"t":"寄扬州杨成玉太守鲍栗之同知","f":"七言律诗","c":["后土祠前约看花，北来寺口醉呼茶。","别时已隔路千里，梦觉长惊天一涯。","大府衣冠浑得意，上京炊爨乍成家。","题诗无限停云意，南国西风雁影斜。"]},{"t":"与赵通政竹溪先生过定西大总戎筠清轩夜酌联句","f":"七言律诗","c":["侯门开燕夜如何，灯下藏阄听雅歌。","交错觥觞情自洽，倡酬诗句乐偏多。","不妨归骑将冲雨，共惜流乌似掷梭。","有约重来续清赏，万竿脩竹正婆娑。"]},{"t":"七月朔时享陪祀太庙听传制遣祭历代帝王陵阴雨陡晴诗以志喜","f":"七言律诗","c":["剑佩锵锵得步从，君王仁孝此忻逢。","箫韶迭奏终三献，玉帛将诚下九重。","朝祭一时交换服，起居今夕两闻钟。","无端风雨成新霁，天日光华仰圣容。"]},{"t":"指挥家叔将归七夕约李士敬昆仲同饯","f":"七言律诗","c":["半夜西风挟雨长，晓来庭院得新凉。","正看织女嫁河鼓，况复行人辞帝乡。","一曲离歌杂燕赵，几年骨肉似参商。","二难有约不相负，预洗金荷打酒尝。"]},{"t":"寿英国公母夫人","f":"七言律诗","c":["上公名爵冠勋贤，阿母高堂启寿筵。","黄菊才过重九节，朱颜将及古稀年。","诰封极品恩如海，曲度长生酒似泉。","晚福定期增鹤算，蓬莱他日看桑田。"]},{"t":"谢周草庭都尉惠酒时值戒饮","f":"七言绝句","c":["春满宫壶带露篘，故人分赠若为酬。","正当止酒诗成处，两斛明珠惜暗投。"]},{"t":"分得言字送卢廷佐大参赴湖广","f":"七言律诗","c":["阊阖门前喜拜恩，玉河桥畔送离尊。","旧时宾客多星散，此际衣冠独凤鶱。","钟阜云开瞻日表，楚江霜落见潮翻。","东南民物应何似，大省宁无赞一言。"]},{"t":"成化癸夘冬至谒陵与李宾之学士联句二十首 其一 宾之约德胜关土城寺候同行予误出安定关土城过道赴约","f":"七言律诗","c":["策马西来问路频，出城东望正怀人。","先声喜逐前呵至，负约几成左顾嗔。","孤堠影迟寒度日，断溪冰合远迷津。","他年记取同游事，语柄长堪寄一嚬。"]},{"t":"成化癸夘冬至谒陵与李宾之学士联句二十首 其二 清河会费廷言司业","f":"七言律诗","c":["故人相约会清河，短日羸骖奈远何。","慰藉共逢辛苦地，笑谈聊续短长歌。","野翁爱客能分火，戍客还家正拥戈。","举目关山惊岁晚，旧游那复向时多。"]},{"t":"成化癸夘冬至谒陵与李宾之学士联句二十首 其三 沙河道中大风","f":"七言律诗","c":["掩地颠风作暮寒，乱云羁思两漫漫。","沙飞屡却行人步，大冷谁供逆旅餐。","岂有贤劳裨国事，最惭多病负儒冠。","停骖小憩斜阳里，莫问前头道路难。"]},{"t":"成化癸夘冬至谒陵与李宾之学士联句二十首 其四 宿昌平新城刘谏议祠下兼怀镜川杨翰长","f":"七言律诗","c":["五年重宿此斋居，往事分明一感予。","坐久青毡回夜暖，话残红烛到更馀。","中堂谏议迎新主，西郭耆民指故墟。","因忆旧游杨翰长，摩挲三诵壁间书。"]},{"t":"成化癸夘冬至谒陵与李宾之学士联句二十首 其五 刘谏议祠旧在学东谈本彝府尹移奉于此","f":"古风","c":["谏议高名此地存，一?寒渌奠忠魂。","忧时有策堪垂涕，泚颡何人是负恩。","京府载修新栋宇，庙庭遥隔旧墙垣。","如公千载还生气，半夜惊风正到门。"]},{"t":"成化癸夘冬至谒陵与李宾之学士联句二十首 其六 不寐有怀廷言司业时屠朝宗都宪遣人相闻约同行","f":"七言律诗","c":["烟火沉沉夜对床，山城寒漏觉偏长。","诗脾欲困频呼茗，旅梦初回更换香。","司业馆深谁共宿，中丞台远漫相望。","隔窗明月窥人处，犹似前宵在玉堂。"]},{"t":"成化癸夘冬至谒陵与李宾之学士联句二十首 其七 将发","f":"七言律诗","c":["百年世世几同袍，此日追趋爱我曹。","残话半从幽梦续，壮心宁觉畏途劳。","鸡声绕舍催明发，虎旅连城散夜櫜。","北望寝园三十里，斋庐还枕碧山高。"]},{"t":"成化癸夘冬至谒陵与李宾之学士联句二十首 其八 早发暂过守备杜都阃","f":"七言律诗","c":["夜风吹尽晓晴新，城上青山欲近人。","暂访元戎回马首，远追司业认车尘。","冈峦宛转随双眺，官卫参差记六巡。","拟向穹碑观圣制，道旁先望石麒麟。"]},{"t":"成化癸夘冬至谒陵与李宾之学士联句二十首 其九 道中","f":"七言律诗","c":["山郊回望永安城，白石黄沙旧路平。","树老空山无落叶，泉通幽涧有馀声。","明楼突兀中天见，神道逶迤上界行。","下马红门分径入，四陵云气正纵横。"]},{"t":"成化癸夘冬至谒陵与李宾之学士联句二十首 其十 斋所","f":"七言律诗","c":["襆被来寻旧直庐，石门斜映小窗虚。","行厨午报新炊熟，别院寒分半榻居。","对景忽疑山入座，引流常忆水通渠。","小臣正切遗弓念，寝树风生夕照馀。"]},{"t":"成化癸夘冬至谒陵与李宾之学士联句二十首 其十一 相赠","f":"七言律诗","c":["玉署春坊本旧邻，眼中谁主复谁宾。","论文共剪斋堂烛，助祭同趋辇路尘。","岁月催人成老大，交游屈指半新陈。","松筠晚节期相保，情话惟应此最真。"]},{"t":"成化癸夘冬至谒陵与李宾之学士联句二十首 其十二 晚眺","f":"七言律诗","c":["冒险寻幽兴亦奇，空林萧飒冻云垂。","草中虎阱深难觉，山下龙池远莫窥。","万里乾坤容著眼，一川风月解供诗。","揽衣欲下愁荆棘，赖有乘高力未疲。"]},{"t":"成化癸夘冬至谒陵与李宾之学士联句二十首 其十三 夜坐","f":"七言律诗","c":["不眠相对拥寒炉，自起开门问仆夫。","城角斗杓曾转未，殿头风铎有声无。","斋心耿耿悬孤月，乡思迢迢隔五湖。","清话恐贪今夜永，呼灯无惜效先趋。"]},{"t":"成化癸夘冬至谒陵与李宾之学士联句二十首 其十四 恭诣长陵景陵行礼","f":"七言律诗","c":["寝殿门深夜未开，磬声遥自月中来。","千官鹄立供牲币，九地龙光彻斗台。","人语不闻山更静，灵风欲动仗初回。","一宵两度陪禋祀，还忆君王万寿杯。"]},{"t":"成化癸夘冬至谒陵与李宾之学士联句二十首 其十五 下陵","f":"七言律诗","c":["车从纷驰出乱山，月明灯影有无间。","松林侧过全欹帽，马首低回半脱镮。","隔路几人呼伴侣，随班十载愧容颜。","孤城尚有淹留地，旧榻残灯正候关。"]},{"t":"成化癸夘冬至谒陵与李宾之学士联句二十首 其十六 饮杜山守备宅","f":"七言律诗","c":["七年旌节驻山城，曾见官曹说姓名。","酒出佳醅缘爱客，剑传奇术为谈兵。","四陵宿卫严宵警，千顷屯田足岁耕。","试问尚书门下士，征南勋业几人成。"]},{"t":"成化癸夘冬至谒陵与李宾之学士联句二十首 其十七 至日归途有作","f":"七言律诗","c":["驿路晴风不著人，仲冬天气早回春。","寒轻颇觉貂裘重，沙软何劳马策频。","吾道渐从今日长，官曹常与故交亲。","清时令节多休暇，归引壶觞正及辰。"]},{"t":"成化癸夘冬至谒陵与李宾之学士联句二十首 其十八 游清河惠应寺","f":"七言律诗","c":["金银楼阁倚晴空，几日新城此梵宫。","同拂衣尘聊驻马，拟呼尊酒便开筒。","山僧见面如相识，词客参禅也自通。","抚事临风三叹息，一杯茶话正匆匆。"]},{"t":"成化癸夘冬至谒陵与李宾之学士联句二十首 其十九 望阙","f":"七言律诗","c":["城观巍巍入望深，五云长绕阆山岑。","尘踪暂隔仙凡境，末吏叨陪翰墨林。","池上衣冠应候我，道旁车马亦关心。","休言日共长安远，已觉天威下照临。"]},{"t":"成化癸夘冬至谒陵与李宾之学士联句二十首 其二十 入城","f":"七言律诗","c":["市桥烟火路东西，咫尺门墙望不迷。","归计从容堪作例，别怀匆卒更留题。","还家共有平安慰，行李惟多卷册携。","与子竟成三宿契，向来无地不同跻。"]},{"t":"四茔为林侍御贵实赋 其一 宝涧西原","f":"五言古诗","c":["凄迷谷城山，下有土一抔。","昔在选部君，冠裳此淹留。","山灵苦未协，来往空神游。","荏苒三十载，改奠西原丘。","龙门耸乔木，宝涧萦清流。","体魄安自今，蓍龟复何求。","慎终美孙子，正不惭弓裘。"]},{"t":"四茔为林侍御贵实赋 其二 象峰东麓","f":"五言古诗","c":["才宴曲江池，遄归象峰麓。","青春来未已，白日去何速。","当时乳下儿，襁抱未胜哭。","居然跨灶子，豸绣光一族。","归来今几时，牛眠抚前卜。","恩纶被宿莽，禄养悲风木。","应刻太史铭，千年照林谷。"]},{"t":"四茔为林侍御贵实赋 其三 凤山北陇","f":"五言古诗","c":["有山莆之野，势如凤孤鶱。","山背得佳处，林姥开新墦。","姥昔无恙时，儿方居宪垣。","当其委化日，儿正归乡园。","慈孝两无憾，哀荣一何言。","人胜境逾胜，岁岁来分膰。","青松与丹荔，蓊郁迷高原。"]},{"t":"四茔为林侍御贵实赋 其四 涂岭南窝","f":"五言古诗","c":["岭云何悠悠，岭木未盈握。","踞岭盘生茔，兹见亦超卓。","君诚达者欤，所抱非曲学。","忠言动旒冕，劲气排山岳。","纷纷尘海中，如梦若不觉。","沉疴今告痊，壮志未摧剥。","何当乐斯丘，更历千晦朔。"]},{"t":"送陈推府南归","f":"七言律诗","c":["万岁声中奏礼成，一阳生处数归程。","恩沾上国如春育，路下中原似掌平。","朔气侵车凭酒遣，寒风吹木助诗鸣。","蹇予亦作朝陵使，望别难胜此日情。"]},{"t":"寄平江总戎二绝 其一","f":"七言绝句","c":["出门终日犯尘喧，致主无才愧掖垣。","忽遇北风淮上雁，不胜清思绕东园。"]},{"t":"寄平江总戎二绝 其二","f":"七言绝句","c":["清口沙头一棹停，当时宾主最忘形。","别来水石潇潇处，闻说新开四美亭。"]},{"t":"题武侯令伯忠孝二图 其一","f":"五言绝句","c":["两雏刚幸免，万古此真才。","谁道匡时策，非从静学来。"]},{"t":"题武侯令伯忠孝二图 其二","f":"五言绝句","c":["至性通天地，遗容尚动人。","独怜图报者，曾是汉廷臣。"]},{"t":"送刘职方时雍赴福建参政巡视海道","f":"七言古诗","c":["三冬北风无寸雪，有客驱车向闽粤。","晓辞丹陛发行装，举头尚见都门月。","君在职方今几秋，边功不喜谈封侯。","金绯赫然本公论，此心久抱苍生忧。","海道平时置官守，万里鲸波骏奔走。","内修外攘君所谙，好遣耕桑罢刁斗。","长河南去冰未融，一尊相属离亭东。","行哉宦况亦不恶，荔枝满树狼烟空。"]},{"t":"旧春斋居闻诸君子用东坡韵有作甚盛今冬祈雪仆方至自江南预宿此房附骥一首录呈寅长鼎仪","f":"七言古诗","c":["斋居无尘足清暇，明月满城如雪夜。","情知露祷圣心劳，对榻不眠听漏下。","火冷初惊沉末灭，杯香已觉松涛泻。","诸公玉山相照人，著我蒹葭岂流亚。","年华忍与双毂争，时政谁当一筹借。","愁闻饥鼠去复来，屡见灯花结还谢。","萧萧树影欲过墙，隐隐棋声疑隔舍。","诗盟且喜随孟韩，世态何须问荼蔗。","莫虞久坐吏人苦，曾发高歌山鬼怕。","前身疑是刁斗公，不直一钱从怒骂。"]},{"t":"题扇赠冯盛时贡士","f":"七言绝句","c":["三十年来研席同，一尊才见又西东。","看花有待重来日，预买都城十丈红。"]},{"t":"送冯宪副佩之提学江西","f":"七言律诗","c":["久在秋曹熟教刑，故宜持节下传经。","孔门化泽春分雨，商序文光夜瞩星。","莲社情多留别句，宪台官重省心铭。","西江雅望君无负，腰带横金两鬓青。"]},{"t":"挽谢太守士元母","f":"五言古诗","c":["白箬山隐隐，白箬水沄沄。","一抔松下土，重是恭人坟。","恭人陈氏姬，长作谢家妇。","厌彼时俗妆，佐此东山父。","谢庭本馀庆，兰玉生何蕃。","中挺一枝秀，色映阶墀萱。","异产不凡材，国香动天子。","鼎食来黄堂，恩纶下丹扆。","方期冰雪操，晚共慈竹长。","那知显扬地，遽成草木场。","阃范多清风，人生一流电。","名附有道碑，事可列女传。","不见白箬阡，为歌白箬篇。","寒云起闽峤，游子应潸然。"]},{"t":"题汪廷器画牛图","f":"七言绝句","c":["西畴耕遍已春深，气力应怜两未禁。","丰草长林幸无事，区区相角是何心。"]},{"t":"元旦早朝","f":"五言律诗","c":["共上履端庆，追陪鹓鹭行。","寅宾趋玉陛，平旦下青坊。","四十行年始，涓埃报日长。","无闻知不免，惭愧授经郎。"]},{"t":"听诏","f":"五言律诗","c":["交修传有敕，拥陛正冠襟。","仁出天心爱，忧垂圣虑深。","三言移分野，六事祷桑林。","耆俊充庭在，嘉谋傥自今。"]},{"t":"金缕曲 月正元日寿董都督","f":"古风","c":["喜遇元正节。","想会合贞元，挺生材杰。","曾仗雕戈提虎旅，荡扫狼烟灰灭。","问旧将、谁优谁劣。","七十年来勋业遂，置阴符、却访还丹诀。","庆初度，华筵设。","萧萧两鬓飞晴雪。","看膝前、桂枝秀颖，兰芽香茁。","冠盖盈庭丝管沸。","银瓮椒花酒冽。","更休问、乌圆兔缺。","但祝年年春不老，比乔松、晚翠根盘铁。","奏一调，长生阕。"]},{"t":"斋夜与汪伯谐庶子陆鼎仪张启昭谕德联句 其一","f":"七言律诗","c":["月转西檐夜向深，几回思卧更看参。","天清辇道遥闻柝，火冷斋庐半拥衾。","有制共严三日戒，受釐应荅九重心。","坐来无事频呼茗，怀抱都忘俗虑侵。"]},{"t":"斋夜与汪伯谐庶子陆鼎仪张启昭谕德联句 其二","f":"七言律诗","c":["闭门春夜烛花偏，对拥寒炉久未眠。","沉水旋添销刻漏，綵毫频染动云烟。","天连御苑钟初尽，露下仙台月尚悬。","侍立小童浑不厌，晚来衣薄坐相怜。"]},{"t":"斋夜与汪伯谐庶子陆鼎仪张启昭谕德联句 其三","f":"七言律诗","c":["旅夕相看第几回，斯文尚谊许追陪。","两坊灯火还连榻，三榜才名旧擢魁。","茶话颇淹公宿意，坐眠时遣吏人猜。","书生事业犹如故，耿耿丹心独未灰。"]},{"t":"斋夜与汪伯谐庶子陆鼎仪张启昭谕德联句 其四","f":"七言律诗","c":["呼童试问夜如何，月落参横四鼓过。","寒气逼人衣渐薄，春愁泥客梦还多。","南郊大礼凭谁赋，东阁官梅许共哦。","候吏已闻催晓近，便思冠履上銮坡。"]},{"t":"南郊陪祀与鼎仪同宿史道士房联句四首 其一 斋居","f":"七言律诗","c":["翠竹娟娟小洞天，道人相候寸心虔。","新茶屡供青霄畔，旧检閒开白日前。","丹灶几回封绛雪，薰炉一炷起青烟。","明年有约还分榻，来向洪厓更拍肩。"]},{"t":"南郊陪祀与鼎仪同宿史道士房联句四首 其二 迎銮","f":"七言律诗","c":["夜下仙坛雪满天，万人精享助皇虔。","衣冠远近焄蒿里，玉帛参差缲藉前。","假寐暗销清漏水，洗心遥奉紫檀烟。","旂常动处微风起，引望诸曹接项肩。"]},{"t":"南郊陪祀与鼎仪同宿史道士房联句四首 其三 陪祀","f":"七言律诗","c":["雪浪沄沄远接天，化工呈瑞报精虔。","联翩佩影宫门外，赫奕军容燎火前。","万马不嘶悬夜月，六龙初驾拥春烟。","礼成谁奏南郊颂，给札应须付两肩。"]},{"t":"南郊陪祀与鼎仪同宿史道士房联句四首 其四 入城有怀","f":"七言律诗","c":["雪后春阳便放晴，万人欢喜庆郊成。","归来两骑河堤远，望里双龙绛阙明。","仓卒到城闻昼漏，从容还舍整朝缨。","回思夜榻曾同梦，咫尺丹房逼太清。"]},{"t":"庆成宴后有作","f":"七言律诗","c":["郊宴分行仰圣颜，暖风韶乐五云间。","贤豪屡见新前席，蹇劣宜归旧从班。","觞饮帝教沾醉出，簪花人羡戴春还。","常饕尚食曾何益，驽马空陪十二闲。"]},{"t":"上元日与林谕德亨大商懋衡李世贤二侍讲饯同年陆叙州克深考绩西还联句十首 其一","f":"七言律诗","c":["六年两觐一尊同，簪盍今看笑语中。","盈缺共怜天上月，分飞翻恨雪边风。","雷陈胶漆心长在，李杜文章思不穷。","怅别那堪还话别，春云撩恨满城东。"]},{"t":"上元日与林谕德亨大商懋衡李世贤二侍讲饯同年陆叙州克深考绩西还联句十首 其二","f":"七言律诗","c":["数载暌违此日逢，夜堂灯火笑萍踪。","名途共幸身强健，大郡争誇众景从。","秉烛意长春漏短，离樽香淡别情浓。","吟馀忽上西檐月，相对愁听紫禁钟。"]},{"t":"上元日与林谕德亨大商懋衡李世贤二侍讲饯同年陆叙州克深考绩西还联句十首 其三","f":"七言律诗","c":["去住相看作上元，交情不改旧词垣。","金莲影动笙歌沸，紫陌尘空车马喧。","樽酒流连忘夜永，衣裘疏散觉春暄。","河桥豫惜明朝别，细柳东风蜀道辕。"]},{"t":"上元日与林谕德亨大商懋衡李世贤二侍讲饯同年陆叙州克深考绩西还联句十首 其四","f":"七言律诗","c":["久别相逢似梦中，曲江年少最英雄。","流光荏苒将头白，朋酒逡巡未颊红。","地隔南川时望斗，气凌七泽拟嘘虹。","人生良会应无几，晚节冰霜此意同。"]},{"t":"上元日与林谕德亨大商懋衡李世贤二侍讲饯同年陆叙州克深考绩西还联句十首 其五","f":"七言律诗","c":["宴罢琼林十九春，东西南北故情新。","玉堂雅集今如昨，皂盖清风独胜人。","剪烛肯孤良夜赏，赓歌直遣壮怀伸。","凤毛麟角真相许，况际风云庆会辰。"]},{"t":"上元日与林谕德亨大商懋衡李世贤二侍讲饯同年陆叙州克深考绩西还联句十首 其六","f":"七言律诗","c":["月明风静主心欢，春溢宫壶夜不寒。","深巷烛光星共烂，小庭尘净雪初残。","帝城已纵金吾令，客子羞歌蜀道难。","此景不妨停五马，解襟岸帻共盘桓。"]},{"t":"上元日与林谕德亨大商懋衡李世贤二侍讲饯同年陆叙州克深考绩西还联句十首 其七","f":"七言律诗","c":["金炉银烛共灯宵，佳会宁烦折简招。","酒泼冻醅春尚浅，星随寒漏夜方遥。","十年萍海虽多事，万里云山会一朝。","欲絷场驹恨无计，出城车马已萧萧。"]},{"t":"上元日与林谕德亨大商懋衡李世贤二侍讲饯同年陆叙州克深考绩西还联句十首 其八","f":"七言律诗","c":["文翁佳政见重施，闻说怀贤更有祠。","锦里好山题欲遍，玉堂高韵押偏迟。","金兰气味忘宾主，冰雪襟怀迈等夷。","不久朱轓应赴召，使君清誉已交驰。"]},{"t":"上元日与林谕德亨大商懋衡李世贤二侍讲饯同年陆叙州克深考绩西还联句十首 其九","f":"七言律诗","c":["远别情随夜漏深，骊驹歌罢似难禁。","故人药石能投我，何处疮痍最苦心。","入蜀杜陵诗益壮，赋梁枚乘病多侵。","彤襜明日辞金阙，济旱须为四海霖。"]},{"t":"上元日与林谕德亨大商懋衡李世贤二侍讲饯同年陆叙州克深考绩西还联句十首 其十","f":"七言律诗","c":["谁从元夕启离筵，同榜交游自往年。","握手谩论川外事，回灯重和郢中篇。","情贪坐久销香篆，心怨离多涸酒泉。","江海去年今夜月，梦魂曾绕玉京天。"]},{"t":"题四马图 其一","f":"七言绝句","c":["花柳繁阴翠作堆，人间惊见两龙媒。","低头顾影无穷意，髣髴彤庭立仗回。"]},{"t":"题四马图 其二","f":"七言绝句","c":["玉关初未解秋防，苜蓿春深绿更长。","好遣霜蹄空冀北，未容归老华山阳。"]},{"t":"题四马图 其三","f":"七言绝句","c":["骏骨千金未足论，并游来试碧沄沄。","梦魂不到长城窟，须识天闲雨露恩。"]},{"t":"题四马图 其四","f":"七言绝句","c":["凉风簌簌动拳毛，入眼骊黄价并高。","未脱盐车充上乘，当时谁作九方皋。"]},{"t":"诗例奉送倪学士舜咨清明谒陵之行 其一","f":"七言绝句","c":["今年分祀园陵下，问柳寻芳亦羡渠。","往日滥陪轩盖后，冒寒冲暑最怜予。"]},{"t":"诗例奉送倪学士舜咨清明谒陵之行 其二","f":"七言绝句","c":["青山见客无生熟，白马随春共疾徐。","谏议庙前来去路，感时应复到吟馀。"]},{"t":"送侍御孙公出按南畿用同年戴以德诗韵 其一","f":"七言律诗","c":["旗亭白日酒三巡，送客乘轺下紫宸。","阙下有名思铁汉，江南无地著钱神。","月随方寸光华满，霜与平生节操均。","入觐相期应隔岁，皂囊风采定惊人。"]},{"t":"送侍御孙公出按南畿用同年戴以德诗韵 其二","f":"七言律诗","c":["肃肃前驺拥徼巡，煌煌宪节下严宸。","威风早已摧山岳，衷赤何须誓鬼神。","一道冤声应尽雪，七州民力待重均。","知公不负江南望，曾是循良第几人。"]},{"t":"送侍御孙公出按南畿用同年戴以德诗韵 其三","f":"七言律诗","c":["一年寒暑又逡巡，惭愧无才却奉宸。","星凤北来初识面，松楸南望独伤神。","同朝谩托衣冠后，邻县遥闻道里均。","浊酒易销情莫尽，画船秋水看离人。"]},{"t":"送许国用南归","f":"七言古诗","c":["子鬓如鸦面如玉，胸次萧然绝尘俗。","沿身书剑从一童，到处江山寄双足。","前年六月离钱塘，随我驱车游紫阳。","高歌花外杂山雨，烂醉松阴眠石床。","及时行乐人争羡，却买扁舟下江县。","我前子后差几程，吴楚风光阅将遍。","偃王墓前春草明，谢沟闸下春潮生。","何人访戴有馀恨，才子依刘无限情。","我行到阙随鹓侣，半月秋风送残暑。","升堂再拜尘满衣，知子来从潞河渚。","西山云拥金芙蓉，玉泉水香流白虹。","垂杨绾客客不住，行装又出东城东。","男子当怀四方志，贤达分明眼前事。","燕台千尺北鸿飞，送子令人发豪思。","蹇予浪说瀛洲仙，近来稍结山中缘。","红尘再入发将白，更暖鸥盟知几年。","嗣岁春分酒初熟，西斋扫榻留人宿。","子当高诵逍遥篇，为君重添卧游录。"]},{"t":"题画赠刘挥使还新安 其一","f":"七言绝句","c":["十道江淮转运难，指麾能事说新安。","年年有约欢相见，席上离歌不用弹。"]},{"t":"题画赠刘挥使还新安 其二","f":"七言绝句","c":["苍山老木涧声长，入眼分明似故乡。","把酒赠君东郭路，不堪心逐雁南翔。"]},{"t":"中元送蔡樊二都尉谒陵用草庭都尉韵","f":"五言古诗","c":["都城初过雨，辇道净无尘。","香帛供原庙，金貂遣懿亲。","风随行李健，景入画图真。","驿次驰应惯，斋居迹未陈。","炎光浮野黍，凉思发溪蘋。","蔡泽心何壮，樊宏性更醇。","诗才兼雅丽，交味谢甘辛。","山郭花藏市，沙桥树隔津。","碑亭围奰屃，神路截嶙峋。","谈麈挥霜尾，吟鞍压绣茵。","不辞当旅夕，深幸际佳辰。","剑佩趋双阙，笙歌奠八珍。","威灵瞻凤驭，生气协鸿钧。","礼磬声敲玉，宫壶水滴银。","忽传收燎火，早见彻严禋。","北斗光芒正，中元节候新。","断云开晓月，残露下秋旻。","蒇事同乘马，归装或驾轮。","节旄山鸟避，轩盖路人驯。","去说贤劳共，来看帝命申。","金兰忘异姓，玉树羡同伦。","欲订西园约，朱门逼禁宸。"]},{"t":"送元真观徐本道士游武当","f":"七言律诗","c":["屡到元君观里行，僻居潇洒爱徐生。","花当户外朱英烂，瓜出墙头紫蔓萦。","晓露研朱看篆字，午风敲玉认棋声。","无端又逐衡阳雁，丹灶归时几转成。"]},{"t":"寄宋民表同知","f":"七言律诗","c":["德政犹传内翰名，又烦才子福山城。","风前玉树材偏隽，雪后青松节更明。","遗老望尘惊自慰，好山随路解相迎。","无由缩地论今昔，凭仗南鸿一寄声。"]},{"t":"送程智南归","f":"五言古诗","c":["恭惟两大贤，命世出嵩洛。","上焉继往圣，下焉启来学。","侑食大成殿，专祀中山区。","俎豆无终穷，道化与之俱。","眷此海宁乡，先世所自出。","旧庙莽不存，过者愧儒术。","宪臣秉学政，令尹司化权。","坐协师生议，要使人文宣。","一函走言状，宗伯告天子。","阙典许再兴，伟观自今始。","岂无古循吏，亦有先达尊。","巍巍企德堂，同此入道门。","嗟我本末裔，怂恿恒恻恻。","六一碑可寻，云峰记重勒。","入奏者谁子，家住山斗村。","呼我大父行，等是嵩洛孙。","俯伏天九重，奔走路千里。","盛举忽告成，相看动容喜。","秋潮没津渡，落叶飘井床。","赠子一樽酒，解剑城东坊。","南望浙江源，正过黉宫下。","所期道脉长，增重枌榆社。","子归应几日，为我谢诸公。","勉旃崇令德，无负新民功。"]},{"t":"送黄世瑞南归","f":"七言古诗","c":["古林黄子江南来，矮屋借住都城隈。","平生抱玉肯轻售，敛容不上黄金台。","旅况从教白日速，壮观喜睹青天开。","西风一夜发归思，遥天北雁声相催。","往来何啻万馀里，非名非利胡为哉。","当时拂衣避文祸，历江过浙愁嫌猜。","栖栖汝颖十年久，故园风雨荒田莱。","谤者飘零恚者死，犹欲手障狂澜回。","两淮饥馑苦连岁，津征太峻人相哀。","袖书上白天子使，正色那顾群声诙。","家传世牒自江夏，兵燹之后随飞灰。","辛勤重编几易稿，收拾袒免联功缞。","迩来乃欲妄推我，分明朱墨求删裁。","后先跋涉本为此，愈见精力忘颠颓。","高人出处诚有道，馀子琐琐安能陪。","空斋露下客衣薄，亭皋叶落纷成堆。","客行去矣不可挽，蒲帆十幅悬高桅。","忆昔访子五城渡，驱车不惮青崔嵬。","子家后圃有意趣，深藏一径生莓苔。","扫云坐我松室下，文章满架千琼瑰。","或如新绮织霞蝀，或如古鼎镌云雷。","指挥神鬼加束缚，剖析义利分条枚。","留谈终日坐忘倦，澹然欲去还徘徊。","今思此会岂易得，官途扰扰冲黄埃。","白云先陇恒在望，诵诗不忍歌南垓。","两宫劝讲无才补，一身窃禄惭非才。","荒庄隔子五十里，清溪上下相萦洄。","千章老木有嘉荫，一林翠竹生新胎。","方塘活水如镜净，柳枝泼泼穿鱼腮。","兴来拟结白莲社，新知旧学交相培。","国恩未报尚留恋，饮子欲倾三百杯。","江南江北若庭户，太平岐路非邛崃。","相期有约定何日，无忘折寄山中梅。"]},{"t":"中秋士钦相邀不赴次韵","f":"七言律诗","c":["来往诗筒剧凤梭，一秋佳宴好经过。","相期却负故人甚，不饮真如良夜何。","窃禄敢思宽禁直，承颜聊欲慰奔波。","他时有月皆堪赏，少待彤庭奏凯歌。"]},{"t":"庆赵竹溪先生子登科兼有弄璋之喜","f":"五言律诗","c":["鹊声频送喜，佳气集高门。","桂籍初登子，兰阶更得孙。","极知天有意，谁谓善无根。","多少归田乐，相期颂达尊。"]},{"t":"送孝陵卫致政千户覃士英南还","f":"七言律诗","c":["旧游踪迹半相疏，喜见多君忽过予。","命驾谁期千里外，开尊今是十年馀。","钟山紫气藏弓久，幕府清风解印初。","明日不堪还送别，西风黄叶绕离车。"]},{"t":"段夫人寿诗","f":"七言古诗","c":["今年系缆交河滨，升堂再拜尊夫人。","萧萧鹤发动容喜，贱子旧是同乡亲。","夫人七十近初度，贵婿无由展情素。","符台遍索长生篇，况我年来夙钦慕。","华筵济济风日晴，杂遝贺宾罗绮明。","极知沧瀛有仙酝，况乃燕赵多新声。","儿郎鹗荐名伊始，肯坠先公旧金紫。","更期努力慰慈颜，岁岁相从祝蕃祉。"]},{"t":"与倪舜咨董尚规李士钦联句一首送太子少保保国朱公北征","f":"七言律诗","c":["大将提兵下汉庭，光生千里震雷霆。","旄头夜落尘氛净，豹尾秋屯杀气腥。","边徼岂能当庙算，山川应合助王灵。","功成拟勒燕然石，汉史无劳数卫青。"]},{"t":"送周仪宾入庆归藩","f":"七言律诗","c":["入觐年来第几番，金绯光彩又南辕。","府僚北阙随称寿，帝子东都久奉藩。","千里关山忘跋涉，一冬天气足寒暄。","坐怜亲戚无堪赠，倾倒奚囊与赠言。"]},{"t":"奉和致政令君洛阳周公见寄韵","f":"七言律诗","c":["诗筒千里寄佳声，贱子疏慵合负荆。","喜色剧增东上阁，清风如对洛阳城。","忘机定与群鸥狎，寄远时听一雁鸣。","光霁无由堪进谒，草窗新绿几回生。"]},{"t":"送敏聪弟还河间 其一","f":"七言绝句","c":["疋马来冲九月霜，路人知是白眉郎。","相逢南北今三载，不觉昂藏共我长。"]},{"t":"送敏聪弟还河间 其二","f":"七言绝句","c":["书巢如斗画堂东，日日相煨夜火红。","多少旧怀谈不尽，雁声时度月明中。"]},{"t":"送敏聪弟还河间 其三","f":"七言绝句","c":["好是江南载酒来，一尊须待季方开。","吾家手足情偏厚，不数当年七步才。"]},{"t":"送敏聪弟还河间 其四","f":"七言绝句","c":["官邸运床仅月馀，冷官长愧食无鱼。","临岐可有黄金赠，赠尔芸香一担书。"]},{"t":"送敏聪弟还河间 其五","f":"七言绝句","c":["金沙冈上大夫坟，与尔同原一派分。","苍桧白杨须爱护，碑亭中刻御书文。"]},{"t":"送敏聪弟还河间 其六","f":"七言绝句","c":["我已行年四十初，宦情人事两迂疏。","故人亲戚多英俊，怪底曾无一字书。"]},{"t":"问津图","f":"五言古诗","c":["圣心与天同，悯此世道阨。","周流寰宇间，所遇恒不获。","驾言入蔡境，又复离楚泽。","驱车莽何之，一水漫相隔。","遥遥风浪惊，隐隐岐路迫。","田中偶耕者，矫若云际翮。","愿从一问途，胡不见指画。","由来避世人，浪笑远行客。","孰知帝降衷，本负天下责。","隐显亦何心，士贵识所择。","兹事已千载，悠悠想风格。","乔木入望青，寒日照川白。","景物馀画图，得失著简策。","再拜先师容，摩挲古辕軏。","欲赋问津篇，抚卷空啧啧。"]},{"t":"送过副使太璞进表礼成还江西","f":"七言律诗","c":["晓日牙绯下九天，离亭相对朔风前。","来朝共上南山祝，去路回瞻北斗悬。","客里杯长频驻马，道中波暖更乘船。","寒梅古柏西江署，屈指风光又隔年。"]},{"t":"朝陵岁例同寅必有赠行诗以倡和为礼今次独无知我不工于此也往来三宿皆天日晴暖诗景满前竟不能措一辞诚如诸公所料行馆早起漫成一律志愧然继来者免我引玉之劳又不能不自幸也","f":"七言律诗","c":["故人怜我乏诗才，断遣吟筒第一回。","林壑献嘲从此始，风花乘兴待谁来。","黉宫地僻红尘少，寝路霜晴白日开。","只有青山知客意，嗒然相对两悠哉。"]},{"t":"次韵奉送少宰王廷贵先生还莅南京 其一","f":"七言律诗","c":["泽国芙蓉照水新，祖筵遥对夕阳津。","久期北阙司纶綍，还向南都领缙绅。","千里盈亏频看月，一番离合几经春。","赤心不共江湖远，侧耳嘉谟赞一人。"]},{"t":"次韵奉送少宰王廷贵先生还莅南京 其二","f":"七言律诗","c":["旧臣南去宠光新，熟路宁劳复问津。","三品奏功初赐诰，六堂承学久书绅。","行边菊色聊经晚，到日梅花渐及春。","欲倚渭城歌未得，才情深愧郢中人。"]},{"t":"题画为郑府典宝淳安应君赋兼寄别意 其一","f":"七言绝句","c":["白雁悠悠水满塘，柳阴芦叶似人长。","拂图髣髴清溪上，斜日渔村驻野航。"]},{"t":"题画为郑府典宝淳安应君赋兼寄别意 其二","f":"七言绝句","c":["王门无事足幽探，为赋新图句不堪。","莫听雁声思故里，筒中盘谷似江南。"]},{"t":"送太学生洛阳陈瑀司训郿县","f":"五言古诗","c":["君本洛阳人，去教关西士。","岩岩百世师，肃肃横渠子。","当时受程学，著述存圣轨。","故宅今何如，寂寞俯寒水。","行哉学干禄，知尔非得已。","华山虽万仞，后进宜仰止。","书翻定性篇，铭揭砭愚旨。","庶几坐皋比，不以道为市。","岂无郿之人，一二解臧否。","平时勉旃意，新句已盈纸。","君有仕优名，予无失言耻。"]},{"t":"送三原王天锡赴南京右府都事 其一","f":"七言绝句","c":["幕府巍巍逼上台，都人常望谏书来。","江东不用誇王导，分陕而今得异才。"]},{"t":"送三原王天锡赴南京右府都事 其二","f":"七言绝句","c":["虎旅分屯建业城，凤毛承宠署新名。","阴功自出三槐后，赢得家声播两京。"]},{"t":"送三原王天锡赴南京右府都事 其三","f":"七言绝句","c":["捧檄南行得奉亲，君王真念老成人。","江鱼竹笱承欢处，无限丹心拱北辰。"]},{"t":"送三原王天锡赴南京右府都事 其四","f":"七言绝句","c":["万仞钟山入望高，官閒宁复簿书劳。","传家见说惟诗礼，不用登坛受六韬。"]},{"t":"送贵溪宗人淳赴汀州司副 其一","f":"七言绝句","c":["相湖分派入程源，几叶儿孙秀更蕃。","喜见青毡重出色，何须高盖与华轩。"]},{"t":"送贵溪宗人淳赴汀州司副 其二","f":"七言绝句","c":["百丈山前道一堂，秋来草树未全荒。","传家正学依然在，一脉还应到粤乡。"]},{"t":"送贵溪宗人淳赴汀州司副 其三","f":"七言绝句","c":["汀郡棠阴有去思，汀庠人说旧经师。","此行拟续题名记，教养分明盛一时。"]},{"t":"送贵溪宗人淳赴汀州司副 其四","f":"七言绝句","c":["离合纷纷几岁华，客中辛苦又移家。","京城咫尺无由别，孤负清尊对菊花。"]},{"t":"寿喻君夫妇","f":"五言古诗","c":["喻君西江彦，美誉发兰芷。","白首闺中人，和音协宫徵。","相看六十年，岁月未云驶。","儿孙森玉立，绕膝承甘旨。","佳辰来众宾，拜手祝蕃祉。","悠悠径菊黄，袅袅炉烟紫。","居然尘壒中，双寿照图史。","愿酌九酝觞，朱颜似童子。","岁赋长生篇，家庆自今始。"]},{"t":"题画送敏聪弟还河间","f":"七言绝句","c":["西风吹彻桂花秋，欲去珍禽不自由。","无限人间离别意，海天明月照高楼。"]},{"t":"挽过野舟六绝 其一","f":"五言绝句","c":["岁毂如流水，霜华满鬓催。","沧江虹月在，不见米狂来。"]},{"t":"挽过野舟六绝 其二","f":"五言绝句","c":["举世皆如梦，虚堂昼掩扉。","几人名利窟，回首解忘机。"]},{"t":"挽过野舟六绝 其三","f":"五言绝句","c":["芳林围石坞，人指薛泾原。","此日归真宅，端然识寓言。"]},{"t":"挽过野舟六绝 其四","f":"五言绝句","c":["谈屑多吴体，才华似郢人。","一编窥豹稿，谁复和阳春。"]},{"t":"挽过野舟六绝 其五","f":"五言绝句","c":["凤翥鹏鶱后，冲霄一鹤翔。","九原知不憾，林立见三郎。"]},{"t":"挽过野舟六绝 其六","f":"五言绝句","c":["远客询遗行，何如汉郭君。","墓前新白石，应刻蔡邕文。"]},{"t":"饮王陈二真人园亭","f":"七言律诗","c":["二真重约饮西城，面面疏棂暑气清。","了尽宦缘投子色，唤醒尘梦步虚声。","洛花久放游人醉，闽果深劳饷客情。","多病近来思辟谷，琳宫何日报丹成。"]},{"t":"竹茶炉卷 其一","f":"七言律诗","c":["新茶曾试惠山泉，拂拭筠炉手自煎。","拟置水符千里外，忽惊诗案十年前。","野僧暂挽孤帆住，词客遥分半榻眠。","回首旧游如昨日，山中清乐羡君全。"]},{"t":"竹茶炉卷 其二","f":"七言律诗","c":["细结湘筠煮石泉，虚心宁复畏相煎。","巧形自出今人上，清供曾当古佛前。","可配瓦盆篘玉注，绝胜金鼎护砂眠。","长安诗社如相续，得似轩辕句浑全。"]},{"t":"鞠筠图题寿人母","f":"七言律诗","c":["风前一种胜金黄，头白相看树北堂。","耻与繁华争岁月，独依高节共冰霜。","綵衣欲乱参差影，绿酒能分潋滟香。","拟向花神问家庆，竹孙时拂翠云长。"]},{"t":"题南宋陈枢长江万里图 其一","f":"七言绝句","c":["曾听江声过海门，眼中忽见旧涛痕。","山崩岸坼知多少，独有中流砥柱存。"]},{"t":"题南宋陈枢长江万里图 其二","f":"古风","c":["万里沉沉水拍天，诗人犹记夜鸣舷。","醉来直上金山寺，酌取中?第一泉。"]},{"t":"题南宋陈枢长江万里图 其三","f":"七言绝句","c":["江风吹浪雪粼粼，笑抚冰缣欲问津。","短楫轻桡浑不见，未应无复济川人。"]},{"t":"题南宋陈枢长江万里图 其四","f":"七言绝句","c":["南渡陈郎笔意间，水云摇动墨池间。","长江不作华夷限，定写瓜州北岸山。"]},{"t":"题大畈汪希大养浩斋卷","f":"五言古诗","c":["我有浩然气，充之塞乾坤。","一蹴苟失养，此志日已昏。","汪君婺之彦，烈烈前王孙。","穷年事探讨，成性将存存。","昭示揭华篇，如在孟氏门。","岂无媚学子，日夕攻讨论。","所思在葩藻，谁解植本根。","若人乃超然，德性行以尊。","永言勿自馁，坐使民风敦。"]},{"t":"故刑部尚书万安刘公夫人哀挽 其一","f":"七言绝句","c":["尚书勋德重当时，伉俪分明得女师。","淑行定归刘向传，令人三诵鹊巢诗。"]},{"t":"故刑部尚书万安刘公夫人哀挽 其二","f":"七言绝句","c":["荆布家风玉雪容，诗书犹说旧儒宗。","相夫谁合隆恩泽，四度鸾书出九重。"]},{"t":"故刑部尚书万安刘公夫人哀挽 其三","f":"七言绝句","c":["清宁宫里早朝回，四翟冠高比上台。","识遍朱门金字榜，众中誇道不凡才。"]},{"t":"故刑部尚书万安刘公夫人哀挽 其四","f":"七言绝句","c":["教子丁宁读父书，策名黄甲佩金鱼。","故园花竹春如海，赢得诸孙候板舆。"]},{"t":"故刑部尚书万安刘公夫人哀挽 其五","f":"七言绝句","c":["阅世相将九十龄，白头如雪两瞳青。","缘何便作游仙梦，拭泪空瞻婺女星。"]},{"t":"故刑部尚书万安刘公夫人哀挽 其六","f":"七言绝句","c":["落日秋山起白云，森森松桧拥高坟。","贤名百世应难灭，中有天家谕祭文。"]},{"t":"定海李挥使东溟一览卷","f":"七言古诗","c":["李侯落落千人雄，指挥战舰横雕弓。","倭奴敛迹向沙岛，不敢出没鲸涛中。","新楼拔地几百尺，倚徙下见冯夷宫。","掀髯长啸动林木，胜览直尽东溟东。","晴光荡潏开鸿濛，旭日正上扶桑红。","亭台隐显蜃气灭，斥堠远近蛮烟空。","青山遥遥断海口，横天独鹗乘秋风。","时呼一斗霹雳酎，浇此百岁尘埃胸。","流年任尔添白发，飞思直欲凌苍穹。","迩闻谢兵学辟谷，匣中剑气韬长虹。","蓬莱三山渺何许，异日倘见安期公。","披图击节壮吾子，高歌远寄南归鸿。"]},{"t":"有感次高夏官克明韵二首 其一","f":"七言律诗","c":["年来閒却旧岩扃，僮仆应嫌鹊未灵。","二顷墨庄心已足，几人尘海梦初醒。","愁侵病骨须先白，春入天涯草更青。","感子投琼意何限，愧无佳什付奚丁。"]},{"t":"有感次高夏官克明韵二首 其二","f":"七言律诗","c":["山前山色绕篱斜，惯看收租与焙茶。","寸策并无空许国，一年将尽倍思家。","䲭夷旧迹馀三泖，太白新题重九华。","自分散樗成底事，春风无限上林花。"]},{"t":"喜雨与汪伯谐刘希贤吴原博同寅联句 其一","f":"七言律诗","c":["九重一念格穹苍，蓦地阴云起兑方。","檐溜即看浑似注，市尘那得更如狂。","遥知陇麦回新绿，细觉宫槐缀嫩黄。","明日趋朝同拜贺，颂声应喜动岩廊。"]},{"t":"喜雨与汪伯谐刘希贤吴原博同寅联句 其二","f":"七言律诗","c":["破柱雷声送雨来，眼前生意遍枯荄。","祷祠汉室惭方士，调燮商家待相才。","此日亭成谁志喜，早时诗就不劳催。","逼人清气知何许，频觉烦襟满坐开。"]},{"t":"喜雨与汪伯谐刘希贤吴原博同寅联句 其三","f":"七言律诗","c":["天际阴云散复联，并将风雨作丰年。","溯风群燕衣犹湿，溅水新荷叶正圆。","草野久怜农望切，桑林初识圣心虔。","莫教夕蝀轻相妒，拟挽天瓢一霈然。"]},{"t":"喜雨与汪伯谐刘希贤吴原博同寅联句 其四","f":"七言律诗","c":["满院凉风透葛衣，雨馀轻扇不须挥。","斋居静觉心无累，吟榻清期愿不违。","瓦鼎日长烟篆袅，铜壶天远漏声稀。","莱羹茗盌同三宿，诗阵堂堂未解围。"]},{"t":"沁园春 寿少詹学士镜川杨公","f":"古风","c":["天启家筵，连开寿域，总值芳辰。","喜位进储端，新悬印绶，恩加阃正，久奉丝纶。","霜拂华㒹，霞明丹颊，甲子而今才一巡。","鸣珂巷，见长庚彻夜，瑞霭凌晨。","膝前双玉，也何用、斑衣能悦亲。","看才压秋曹，方恢宦辙，名需春榜，更冠儒绅。","曲度南词，酒传内酝。","珠履纷纷来众宾。","偕老处，问几番蒲柳，得似松筠。"]},{"t":"盆梅为南园蒋大监赋","f":"七言律诗","c":["雪天谁解返冰魂，春意搀先入禁门。","蓓蕾渐看舒五出，胚胎疑为染孤根。","尘空冀北烟花梦，思绕江南水竹村。","珍重盛开应有日，洗妆先试绿醅尊。"]},{"t":"梅花引","f":"七言古诗","c":["岁云暮矣万木僵，山雪未霁江云黄。","竹间彷佛有佳处，野桥阵阵吹寒香。","冰为仙肌铁作肠，平生不入桃李场。","老天有心慰清绝，先遣春意回孤芳。","写生近世惟王郎，一幅轻缣摇素光。","宛然再见姑射子，瘦影下照清泠塘。","罗浮梦破月转廊，羌笛声随风度墙。","喜从旧谱得三昧，不说新妆傅寿阳。","临池想像白玉堂，垂垂鼎实乘春忙。","巡檐欲诵广平赋，花神一笑天苍凉。"]},{"t":"分得閤皂山送伍希渊太守考绩还广州","f":"七言古诗","c":["青山突起沧江垠，宝气夜发腾秋旻。","鍊师叱剑启洞穴，刻玉俨坐真天人。","山灵几时閟琬琰，道院一日开荆榛。","寰中福地七十二，名数閤皂非常伦。","使君五马数过此，与山识面惊乡邻。","奏功近自广州入，归路复拟停朱轮。","鸟啼花舞满涧谷，知有恩露来枫宸。","浮岚暖翠杳难极，莞尔昔年川效珍。","奚囊欲斗两奇绝，罨画不尽千嶙峋。","明当有诏起循吏，酹山细倒罗浮春。"]},{"t":"三月十七日原博谕德饯汝玉给事于玉延亭会者宾之学士于乔谕德济之世贤侍讲曰川校书道亨编修暨予得联句四章时黄蔷薇盛开复移尊于海月庵酹花酌别又得三章予亦将有饯约而觞汝玉者多刻日有次第不能夺也手录此以致缱绻不已之意 其一","f":"七言律诗","c":["酒半离筵客未来，诸公兴浅欲停杯。","亭前花影看移日，池上波光爱泼醅。","延伫不堪南省迥，淹留岂待北门催。","蹇予恐未当君意，习氏池边未肯回。"]},{"t":"三月十七日原博谕德饯汝玉给事于玉延亭会者宾之学士于乔谕德济之世贤侍讲曰川校书道亨编修暨予得联句四章时黄蔷薇盛开复移尊于海月庵酹花酌别又得三章予亦将有饯约而觞汝玉者多刻日有次第不能夺也手录此以致缱绻不已之意 其二","f":"七言律诗","c":["皇华南去正春风，水长湾头画鹢通。","万里潇湘如在眼，九重霄汉未忘忠。","淮阳夜泊应怀古，吴越秋成久愿丰。","归疏边储报明主，太仓无地不陈红。"]},{"t":"三月十七日原博谕德饯汝玉给事于玉延亭会者宾之学士于乔谕德济之世贤侍讲曰川校书道亨编修暨予得联句四章时黄蔷薇盛开复移尊于海月庵酹花酌别又得三章予亦将有饯约而觞汝玉者多刻日有次第不能夺也手录此以致缱绻不已之意 其三","f":"七言律诗","c":["命下龙楼重岁储，城东春色拥离车。","过家路便心先到，报国身劳我不如。","献纳暂违青琐直，咨询争睹紫泥书。","送君正是花时节，饮尽瓶罍兴有馀。"]},{"t":"三月十七日原博谕德饯汝玉给事于玉延亭会者宾之学士于乔谕德济之世贤侍讲曰川校书道亨编修暨予得联句四章时黄蔷薇盛开复移尊于海月庵酹花酌别又得三章予亦将有饯约而觞汝玉者多刻日有次第不能夺也手录此以致缱绻不已之意 其四","f":"七言律诗","c":["江南春色动归人，画舫红旗早问津。","湖口过家鱼正美，城边迓客酒初醇。","催诗数点朝来雨，扑马无端陌上尘。","莫忘玉延亭下宴，相看不是白头新。"]},{"t":"三月十七日原博谕德饯汝玉给事于玉延亭会者宾之学士于乔谕德济之世贤侍讲曰川校书道亨编修暨予得联句四章时黄蔷薇盛开复移尊于海月庵酹花酌别又得三章予亦将有饯约而觞汝玉者多刻日有次第不能夺也手录此以致缱绻不已之意 其五","f":"七言律诗","c":["刺蘼花下送离觞，别思诗情共渺茫。","折赠不须河上柳，醉眠真爱井边床。","篱根㶁㶁闻流水，屋角亭亭见夕阳。","绕树未堪方去住，还看海月照东堂。"]},{"t":"三月十七日原博谕德饯汝玉给事于玉延亭会者宾之学士于乔谕德济之世贤侍讲曰川校书道亨编修暨予得联句四章时黄蔷薇盛开复移尊于海月庵酹花酌别又得三章予亦将有饯约而觞汝玉者多刻日有次第不能夺也手录此以致缱绻不已之意 其六","f":"七言律诗","c":["移席东园就看花，花前起坐即喧哗。","却因送别成嘉集，不用寻芳感物华。","渐有绿阴看系马，岂无银汉待乘槎。","共君秉烛须今夕，最喜西邻酒易赊。"]},{"t":"三月十七日原博谕德饯汝玉给事于玉延亭会者宾之学士于乔谕德济之世贤侍讲曰川校书道亨编修暨予得联句四章时黄蔷薇盛开复移尊于海月庵酹花酌别又得三章予亦将有饯约而觞汝玉者多刻日有次第不能夺也手录此以致缱绻不已之意 其七","f":"七言律诗","c":["一种篱边未满丛，瓣香含雨叶含风。","游丝惹地牵黄蝶，细雨临阶缀玉虫。","满院旃檀春欲暮，印池罗縠夜将空。","行人幸与凭阑会，尽有光华付与公。"]},{"t":"画竹","f":"古风","c":["墨本惊传抱节君，佩声摇动水苍文。","龙孙??争穿上，凤尾翛翛半入云。","满地雪霜甘耐晚，一春红绿耻随群。","摩挲欲扫琅玕净，恐有诗题隔坐分。"]},{"t":"送丁玉夫舍人谪晋安州判","f":"五言律诗","c":["池上人如许，怜君万里行。","蛮方风土异，客路旱尘生。","一饭皆君赐，孤吟足宦情。","到询前给事，应续旧题名。"]},{"t":"分题得芭蕉分绿","f":"七言律诗","c":["倚石亭亭翠几攒，清标不似雪中看。","梦回猎圃思藏鹿，影拂书窗爱舞鸾。","聚扇一挥风力迥，捲杯三酌露华残。","谁便净绿无尘染，细写新诗墨未乾。"]},{"t":"吴人张祚母王节妇","f":"七言律诗","c":["三十年来妇节完，玉壶清冷逼人寒。","松筠自保知心久，桃李空惊入社难。","化及乡闾堪树表，教成儿子解承欢。","凭谁更续离鸾操，为谱琴声膝下弹。"]},{"t":"题画莱","f":"七言绝句","c":["曾移蔬甲课园丁，爱嚼霜根养性灵。","独有画工知此意，能将风味入丹青。"]},{"t":"夏日独卧西斋陶懋学贡士与克俭弟隔坐写画笑语而窗外槐阴与盆石掩映宛如往岁回舟北上时事因成一诗","f":"七言律诗","c":["卧我西斋坐两君，不知谈笑久离群。","墙槐影似中流见，盆石青疑隔岸分。","屈指三年如昨日，开颜一酌又斜曛。","相烦画舫题新额，满壁挥毫动水云。"]},{"t":"广平王同守原常治水底绩卷","f":"古风","c":["一宵水决漳河冲，鲸波突下驱雷风。","划然蚀出贾村口，联堤属堰如飞蓬。","城门昼闭人反走，四顾已作冯夷宫。","贰车王公智且勇，拯溺坐遣舟车通。","行人拔济免鱼腹，公仓保护留陈红。","秪馀决口水如故，屡塞屡坏愁民穷。","民言必得贰车往，上官委牒来匆匆。","王公一念通昊穹，单骑直抵漳河东。","左畚右锸万众集，指呼中坐如元戎。","先疏下土杀水势，巨楗却捣奔流中。","土黏石砌完且固，十里隐隐拖晴虹。","几年泛滥一朝去，入眼似觉沧溟空。","施工次第在方寸，旁观束手真吴蒙。","挽牛未数百步洪，射蛟不用千钧弓。","跨岸长桥复绵亘，绕坻嘉木还青葱。","膏腴可佃六千顷，官租遮莫忧难充。","马前加额来田翁，道上拍手歌村童。","神龙庙下磨巨石，太史执笔书成功。","埭称召伯可专美，堤号苏公谁长雄。","我家中寓瀛海郡，北方水患恒忡忡。","考图按谱多旧迹，坐视孰肯劳其躬。","假令稍费疏筑工，斩地即挽凶为丰。","临风抚卷三叹息，惠政安得千王公，呼呜惠政安得千王公。"]},{"t":"七月六日饮北城友人园亭","f":"七言律诗","c":["北郭分明远市哗，小亭幽绝似山家。","閒翻画册评三昧，醉抚盆峰忆九华。","秋后可容来扑枣，暑中先许坐呼茶。","重游自拟非生客，深巷沿苔一径斜。"]},{"t":"题春山楼观图","f":"七言绝句","c":["一带好山横树杪，几重高阁起云中。","何当避暑钩帘坐，纳取虚窗八面风。"]},{"t":"题画莱","f":"七言绝句","c":["篱下分披绀叶长，枝间凉缀紫团香。","已应风味堪登谱，更著丹青与擅场。"]},{"t":"丙午六月同黄大器避暑朝天宫李鍊师之来鹤轩","f":"七言律诗","c":["雨馀凉思一襟回，琳馆苔花满石台。","双鹤溯风留语去，独槐当户送阴来。","丹炉几向清宵伏，芸检时从白日开。","避暑又看今岁始，不辞冰果荐春杯。"]},{"t":"爱山亭为赵梦麟主事赋 其一","f":"七言绝句","c":["北固山前水一湾，小亭遥对数峰閒。","要贪紫翠来窗几，日日呼童莫掩关。"]},{"t":"爱山亭为赵梦麟主事赋 其二","f":"七言绝句","c":["海岳庵头石路通，结茅人似米南宫。","醉来徙倚穷双目，误指青山作画中。"]},{"t":"次韵贺李学士宾之诞子","f":"七言律诗","c":["吉梦遥占一月馀，果然兰茁见阶除。","门闾不是寻常喜，汤饼连传伯仲书。","骨法生来应克肖，啼声闻处定何如。","眼中足慰而翁意，他日将同颖上车。"]},{"t":"送婺源宗人瑎南归","f":"七言律诗","c":["相逢未久促归装，草草停车饯一觞。","冰释御沟波尽绿，日烘官榭柳初黄。","回瞻北斗皇州近，去逐东风客路长。","莫负壮年须力学，旧家原住晦翁乡。"]},{"t":"钱君宗甫以素扇索诗寄施君彦清","f":"七言绝句","c":["诗社南寻旧日盟，尚方终记国医名。","惠山泉水清如许，一为高人暂濯缨。"]},{"t":"赵梦麟员外琼林醉归图","f":"五言律诗","c":["甲榜传高第，春风入北颜。","琼林沾醉出，紫陌看花还。","巾服存唐制，官仪簉汉班。","莫将经济策，相愧画图间。"]},{"t":"送黄进士金还定远","f":"七言律诗","c":["才从边塞犒军来，又向高堂戏綵回。","河上薰风吹去棹，城隅初日引离杯。","山间旧属兴王地，科甲新传出众才。","可得孤云恋桑梓，即看双佩上蓬莱。"]},{"t":"送屠元勋郎中赴南京大理丞","f":"七言律诗","c":["冰花消尽柳条新，好友相看别意真。","分署才名归汉吏，擅场诗律似唐人。","钟山到日遥瞻斗，秀水经时剩得春。","闻说双旌催晓发，城东还拟逐车尘。"]},{"t":"送安成欧阳子履进士奉命犒师广中便道归省","f":"七言律诗","c":["驿舟南下柳初黄，春冻全消水力长。","奉使一番聊过岭，宁亲千里得还乡。","行装价重题名记，贺客欢生具庆堂。","却倚东风听候雁，定多诗梦到池塘。"]},{"t":"次同年张汝弼韵赠锦衣林公","f":"七言绝句","c":["将军先世本材雄，常在先皇宿卫中。","要识儿孙能继武，门前乔木是遗风。"]},{"t":"和韵萧文明给事留别","f":"七言律诗","c":["一日春风满帝京，独怜回首送君行。","恩纶已觉苏凋瘵，谪籍终应雪姓名。","都下旧桃留赏约，道旁新柳识离情。","瘴乡山水原多幸，嬴得珠玑照眼明。"]},{"t":"万福寺送文明与倪舜咨李宾之二学士傅曰川吴原博谢于乔三谕德林亨大修撰陈汝玉给事李士常侍御联句 其一","f":"七言律诗","c":["送客东城拥雾来，对炉先遣一尊开。","盘因待别留兼味，诗为陶情且共裁。","庭竹未青寒尚在，江波初绿煖将回。","临岐聊为歌三叠，门外骊驹莫漫催。"]},{"t":"万福寺送文明与倪舜咨李宾之二学士傅曰川吴原博谢于乔三谕德林亨大修撰陈汝玉给事李士常侍御联句 其二","f":"七言律诗","c":["爱客幽僧开竹房，春来偏称举离觞。","东风立马情如海，南雪欺人鬓欲霜。","关树萧疏家在望，江梅零落路生香。","后期莫忘论交地，随处江湖与庙廊。"]},{"t":"次韵魏端壁鸿胪述怀之作","f":"七言律诗","c":["红尘滚滚翳双瞳，一室萧然借远公。","守道懒随人俯仰，肃容常立陛西东。","平生志肯隳家学，薄宦情思翊圣躬。","闻说感时新扣闼，万言长疏已留中。"]},{"t":"题南京邵思谊漏月轩有庄孔阳同年记 其一","f":"七言绝句","c":["定山居士久离群，一纸新传漏月文。","文古字奇谁似者，近来应学武夷君。"]},{"t":"题南京邵思谊漏月轩有庄孔阳同年记 其二","f":"七言绝句","c":["小轩生业未全贫，为厌笙歌暖送春。","上雨旁风元不计，只教明月下窥人。"]},{"t":"送王汝璧同知自河南督运大同","f":"七言律诗","c":["壮哉骑马出居庸，转饷归来倏过冬。","敌境尚闻传夜柝，汉屯谁复事春农。","发随驿路年华改，酒入旗亭别意浓。","莱色更深伊洛地，使君何以慰喁喁。"]},{"t":"送宁县张泰省母南归","f":"七言律诗","c":["久侍严君官冀北，又宁慈母返江南。","舅家派远新通谱，官邸情深屡接谈。","行处片帆冲暑雨，到时双屐破晴岚。","承恩堂上春如海，预喜称觞客尽酣。"]},{"t":"六年考满日偶成","f":"七言律诗","c":["厕迹宫僚十载馀，无功堪上考功书。","冷官幸免三宜黜，丑女真成百不如。","发白渐惊闻道晚，才非原合致身疏。","经帏不厌儒生说，敢惜朝朝理蠹鱼。"]},{"t":"宝泽堂为吴人陈翥赋","f":"五言古诗","c":["有美太丘翁，家声重吴城。","授子以诗礼，不贵金满籯。","笼中小学书，手笔严且精。","翁去倏几年，诸郎亦多成。","进思过庭训，展玩惊如生。","什袭古缥囊，共守百世程。","恭惟考亭老，有期在躬行。","我愿君子心，顾此宝泽名。","芸香拂旧签，白石回光荣。","勖哉景贤范，庶以归乡评。"]},{"t":"书仁里族侄佐时家庆卷后八绝 其一","f":"七言绝句","c":["弓冶相承每自怜，喜闻能受一经传。","春风绿鬓芸香重，何止青云属少年。"]},{"t":"书仁里族侄佐时家庆卷后八绝 其二","f":"七言绝句","c":["古来耕读两相循，立志谁堪慕有莘。","闻说一犁春雨后，绿阴长作带经人。"]},{"t":"书仁里族侄佐时家庆卷后八绝 其三","f":"七言绝句","c":["儒硕堂深世禄长，云烟飞处墨花香。","对人好写颜公帖，珍重吾家白面郎。"]},{"t":"书仁里族侄佐时家庆卷后八绝 其四","f":"七言绝句","c":["梦中疑有笔生花，不比书窗学画鸦。","努力顾名思擢第，读书休负好年华。"]},{"t":"书仁里族侄佐时家庆卷后八绝 其五","f":"七言绝句","c":["书斋晴日乍挥毫，天与佳儿一字褒。","吉兆已开休忘取，家风须并士风高。"]},{"t":"书仁里族侄佐时家庆卷后八绝 其六","f":"七言绝句","c":["红隐危楼御墨鲜，家鸡何止得家传。","文章不愧昌黎伯，好读城南训子篇。"]},{"t":"书仁里族侄佐时家庆卷后八绝 其七","f":"七言绝句","c":["早从怀抱识之无，太傅功成雪满颅。","玉汝异时探学海，碧霄红日看鹓雏。"]},{"t":"书仁里族侄佐时家庆卷后八绝 其八","f":"七言绝句","c":["风尘楚楚脱尘凡，更向群中数阿咸。","坐想后来应跨灶，笑人终岁著青衫。"]},{"t":"送郑太史廷纲赴浙江提学宪副","f":"七言律诗","c":["长身玉立旧词臣，喜服牙绯拜命新。","一舸溯风惊远别，诸生悬日候分巡。","谱通夹漈归闽产，学数康成重汉人。","知子政閒应念阙，吴山高处见枫宸。"]},{"t":"送小彭阁老养疾还安成","f":"七言律诗","c":["几年黄阁赞宸旒，早乞身閒未白头。","多病渐驰林壑梦，寸心终切庙堂忧。","新分雨露随双履，旧积图书载一舟。","勿药有期应更健，九重虚席待前筹。"]},{"t":"送敖太史静之赴江西提学宪副","f":"七言律诗","c":["乡榜曾传第一人，词林相见十经春。","史堪朱墨抡才久，服称金绯荷宠新。","官向洪都分宪节，化从殷序播恩纶。","巡行不用申条约，白鹿遗规有翠珉。"]},{"t":"送蔡德馨从父宦游三衢 其一","f":"七言绝句","c":["中郎年少美丰标，千里薰风拂画桡。","此去壮怀增几许，推蓬初看浙江潮。"]},{"t":"送蔡德馨从父宦游三衢 其二","f":"七言绝句","c":["綵侍宁忧客路难，直从鱼浦过严滩。","吴山越水经游处，得似当时画里看。"]},{"t":"送旴江宗人正式南还","f":"七言律诗","c":["梅雨多时水正肥，河梁遥逐一帆归。","阮南有谱通应久，郢曲无才和转稀。","明月屡回桑梓梦，红尘不上芰荷衣。","旧家人物如君少，无限离情对落晖。"]},{"t":"与李世贤学士邵文敬太守同饮复春杨氏玉河寓馆联句 其一","f":"七言律诗","c":["盆池香散一株红，杯酒临轩醉晚风。","病起故人刚下马，别来豪论欲吞虹。","夜深明月当窗白，天阔流云堕地空。","拟剪碧筒寻后约，吟坛高起玉河东。"]},{"t":"与李世贤学士邵文敬太守同饮复春杨氏玉河寓馆联句 其二","f":"七言律诗","c":["醉来高卧碧纱幮，何似临池静看鱼。","晒药有香随屐齿，落花无意点衣裾。","十年故旧怜青眼，千里江湖托素书。","无限交情重对酒，夜阑张烛梦何如。"]},{"t":"送吴学士汝贤莅事南京","f":"七言律诗","c":["吴兢良史最知闻，南去词林职暂分。","白下山川堪寄傲，青坊冠冕惜离群。","才高未许终淹骥，官冷何妨且售文。","曾向玉亭看旧刻，恨无清福可陪君。"]},{"t":"送曾士美侍读莅任南京","f":"七言律诗","c":["春风吹水一帆轻，喜拜新恩向旧京。","对策本无阿世语，上书终有爱君情。","北辰绕梦瞻天阙，东壁流光动石城。","分署近来人物盛，閒居嬴得颂时平。"]},{"t":"送杨维立侍读莅任南京","f":"七言律诗","c":["特奉新恩旧所无，奎星光采映南图。","暂分晓日鹓行侣，未觉春风雁影孤。","江左诗盟添社友，关西经学盛门徒。","不须对酒增离思，天遣才名重两都。"]},{"t":"送庶吉士吴俨养疾南还","f":"七言律诗","c":["一舟遥出潞河浔，赐告南还喜不禁。","吟望铜官秋屐远，梦回天禄夜灯深。","青年暂赋思归引，白日长萦恋阙心。","屈指重来身更健，春风双佩入词林。"]},{"t":"蟠桃图寿星者王璧母句容陈孺人八十","f":"七言律诗","c":["海上仙桃熟几番，写生光映北堂萱。","九重好见旌孀节，八帙今看启寿元。","庆衍太丘知阀阅，秀钟勾曲是乡园。","贤郎最解君平术，甲子无烦绛老言。"]},{"t":"送姑苏仰彦政同知滨州","f":"七言律诗","c":["离歌一曲帝城南，喜佐名州促去骖。","禾黍送香秋正熟，衣冠为别酒初酣。","人材久说虞庠盛，德化宁当汉史惭。","阙下有期重到日，闾阎甘苦听君谈。"]},{"t":"寿亚参吴文盛母夫人许氏七十","f":"七言律诗","c":["七十精神不用扶，庆辰须见雪盈颅。","寿萱吐秀侵香鸭，慈竹连阴护酒凫。","恩湛北堂重赐诰，瑞徵南极更张图。","分藩有客归宁便，无限情申反哺乌。"]},{"t":"赠别徐廷盛亲契南行","f":"七言律诗","c":["残暑西风促去装，潞河南下听鸣榔。","小槽酒罄乡情在，半榻尘生别意长。","脉理近谁谙太素，名途还子逐飞黄。","题诗为订重来约，多病相烦写异方。"]},{"t":"挽工部颜员外泾父母","f":"七言律诗","c":["纶书初赠水曹郎，旌典仍题贞节坊。","家声何止万金直，吉壤俄看双玉藏。","遥望吴山为谁好，忽闻楚些令人伤。","史臣有刻诏千载，寿算宁须论短长。"]},{"t":"尚书谢大韶先生哀挽","f":"七言律诗","c":["文章座主大司空，晓梦惊随逝水东。","汗竹香生良史墨，宫花尘拂状元红。","英魂彷佛陪仙驭，恤典分明感圣衷。","丹旐素舆攀送地，不胜清泪落西风。"]},{"t":"送侍御朱朝用副宪山东","f":"七言律诗","c":["圣主龙飞景运开，豸冠人数出群才。","方期抗疏当前席，忽报承恩佐外台。","晓路星辰瞻北拱，春城车马候东来。","洗冤泽物君能事，听取欢声遍草莱。"]},{"t":"饮会昌侯公子锦衣池亭","f":"七言律诗","c":["白苧风生暑未收，夕阳容我复迟留。","危亭翠匝诸峰晚，小洞阴涵六月秋。","醉里尚能窥画品，兴来何必置诗邮。","摩挲欲剖琅玕节，留取题名续胜游。"]},{"t":"雨中饮孙雪亭家看竹留题与雪亭子颐","f":"七言律诗","c":["紫翠中盘一径苔，竹庭深处绝纤埃。","穿林剩见新篁出，破暑俄惊旧雨来。","秋露不辞分瓮吸，春风何必选花栽。","主人爱客能传子，白社还应几度开。"]},{"t":"送徐用和御史调平凉镇原县令","f":"五言古诗","c":["东风作轻阴，寒雨半成雪。","端居政不怡，况子有远别。","子本江汉英，所学重名节。","平生爱君心，讵忍结吾舌。","一疏天九重，冗食愧饕餮。","皇恩真浩荡，暂遣谢朝列。","迢迢西入关，山水几盘折。","从来行路难，士岂动忧悦。","相送城东门，车声晓幽咽。","劝子酒一卮，世故若骚屑。","勖哉夷险地，仗此一寸铁。","不久应赐环，离歌勿终阕。"]},{"t":"忆家山有作寄逸民用光道新 其一","f":"七言律诗","c":["古城岩下半庄山，恰对澄江水一湾。","列岫拖岚围竹坞，小塘分绿浸柴关。","醉招猿鹤惊相下，清爱渔樵去复还。","此景近来频入梦，病身何日可投閒。"]},{"t":"忆家山有作寄逸民用光道新 其二","f":"七言律诗","c":["隔林沙径到岩扃，绕舍奇峰叠翠屏。","野话有时逢衲子，溪行随处课租丁。","看云净扫松间石，避暑閒登竹下亭。","一自别来空怅望，移文真愧北山灵。"]},{"t":"分题履寿周原已院判乃尊","f":"七言律诗","c":["老人不踏红尘路，踪迹常便水竹居。","蹑屐登山如北日，杖藜随步胜安车。","庭中任解王生袜，桥下谁传孺子书。","但祝仙乔同寿考，双凫他日得凌虚。"]},{"t":"送似都宪大器巡抚畿北","f":"七言律诗","c":["宪节煌煌出帝州，一时风采属君侯。","姓名已副苍生望，筹策应分圣主忧。","六郡锄犁思乐岁，三关兵甲待防秋。","行台咫尺红尘近，先听封章达冕旒。"]},{"t":"送翰林检讨方昌言考绩还南京","f":"七言律诗","c":["风流文采旧词臣，阙下重逢喜暂亲。","别意两分鳌禁月，官情三及凤台春。","山行水宿仍归路，饮社诗坛足慰人。","何日南中容半席，玉亭深处看霜筠。"]},{"t":"丁祭日简费司业廷言","f":"七言律诗","c":["陪祀年年候孔庭，每从司业借莎厅。","衣冠假寐环东壁，钟漏传签报上丁。","礼罢佩声风隐约，归时灯火夜晶荧。","病躯无分随班列，展转斋居寝未宁。"]},{"t":"陈通政夫人哀挽","f":"七言律诗","c":["晓日高堂罢起居，鬓丝萧索晚霜馀。","回鸾色惨皇封诰，辟蠹香销女戒书。","潮落钱塘悲逝水，山围龙井见幽墟。","贤郎啼血扶归衬，不忍重看旧板舆。"]},{"t":"西宁侯著色牡丹为英国公题 其一","f":"七言绝句","c":["侯门三月花如锦，分得春光与上公。","何用洛阳求异谱，彩毫随处落香风。"]},{"t":"西宁侯著色牡丹为英国公题 其二","f":"七言绝句","c":["镜中谁点旧姚黄，金缕衣轻翠袖长。","倦倚东风娇白日，王孙亭榭见花王。"]},{"t":"送徵书纪南游","f":"七言律诗","c":["炉薰经卷束装行，秋入船窗水气清。","禅室未忘星北拱，乡心遥逐雁南征。","三吴锦树长洲苑，六代青山建业城。","来往诗筒应不绝，听人传取惠休名。"]},{"t":"送定西侯总戎北征","f":"七言律诗","c":["手提金印下龙荒，九月边城草木黄。","随处建牙分战士，刻期舆榇得戎王。","风吹汉月笳声远，霜拂胡云剑气长。","拟听玉关驰露布，泰阶那复候天狼。"]},{"t":"寄于文远户侯","f":"七言绝句","c":["横经日日缀鹓班，致主无才独厚颜。","追忆旧游春醉处，梦魂常绕歙州山。"]},{"t":"题画二首 其一 枯荷鹁鸽","f":"七言绝句","c":["白苇枯荷两岸霜，水禽相恋水云乡。","人间手足情何似，落日秋原引睇长。"]},{"t":"题画二首 其二 梅花翠禽","f":"七言绝句","c":["竹间无数玉森森，渐觉春随雪意深。","山下地偏人迹少，野禽能识岁寒心。"]},{"t":"为周都尉题沈石田画","f":"七言律诗","c":["不见姑苏老沈郎，披图疑在石田庄。","眼看雪乳春酲解，手拂云根午坐凉。","高柳似填山下缺，奇峰如出镜中妆。","草庭都尉能珍鉴，何日重开宝绘堂。"]},{"t":"送户部叶叔通郎中知宁国府 其一","f":"七言绝句","c":["民部清风十载馀，金绯一日荷恩除。","秧田麦陇宣州道，多少人迎五马车。"]},{"t":"送户部叶叔通郎中知宁国府 其二","f":"七言绝句","c":["桑梓悠悠共歙城，宦游京国倍多情。","红尘离合常无定，从此相看听雁声。"]},{"t":"送户部叶叔通郎中知宁国府 其三","f":"七言绝句","c":["昔年曾过敬亭山，花雾濛濛湿翠鬟。","别后山容应不改，凭君传语慰孱颜。"]},{"t":"送户部叶叔通郎中知宁国府 其四","f":"七言绝句","c":["宛陵祠下竹娟娟，一榻曾分听夜泉。","携酒寓公谁复在，六回春色到吟边。"]},{"t":"送户部叶叔通郎中知宁国府 其五","f":"七言绝句","c":["故乡乔木隔山青，山郡人应候福星。","民俗士风谙已熟，不须随路借图经。"]}]};